MODULES = json.loads("{\"train\":{\"filename\":\"GHG_9models_Bayes_SHAP_full_273data_fixed.py\",\"source\":\"# -*- coding: utf-8 -*-\\n\\\"\\\"\\\"\\n三种温室气体机器学习与SHAP完整流程\\n====================================\\n\\n功能：\\n1. 读取最终数据表；\\n2. 分别构建 CO2、N2O、CH4 数据集；\\n3. 对13个输入变量统一进行 KNN 缺失值填补和 Z-score 标准化；\\n4. 对9种回归模型分别进行贝叶斯超参数优化；\\n5. 自动确定每种气体的最优模型；\\n6. 输出模型指标、最优参数、预测值和600 dpi性能图；\\n7. 使用每种气体实际选出的最优模型计算并绘制SHAP图；\\n8. 输出SHAP重要性排序和依赖图。\\n\\n首次运行前可安装依赖：\\npip install pandas numpy matplotlib openpyxl scikit-learn scikit-optimize \\\\\\n            xgboost lightgbm catboost shap joblib\\n\\\"\\\"\\\"\\n\\nimport os\\nimport re\\nimport json\\nimport copy\\nimport time\\nimport warnings\\nfrom pathlib import Path\\n\\nimport numpy as np\\nimport pandas as pd\\nimport matplotlib as mpl\\nimport matplotlib.pyplot as plt\\nfrom matplotlib.cm import ScalarMappable\\nfrom matplotlib.colors import Normalize\\n\\nfrom sklearn.base import clone\\nfrom sklearn.pipeline import Pipeline\\nfrom sklearn.impute import KNNImputer\\nfrom sklearn.preprocessing import StandardScaler\\nfrom sklearn.model_selection import train_test_split, KFold\\nfrom sklearn.metrics import r2_score, mean_squared_error, mean_absolute_error\\nfrom sklearn.ensemble import (\\n    GradientBoostingRegressor,\\n    RandomForestRegressor,\\n    ExtraTreesRegressor,\\n)\\nfrom sklearn.tree import DecisionTreeRegressor\\nfrom sklearn.neighbors import KNeighborsRegressor\\nfrom sklearn.svm import SVR\\n\\nfrom xgboost import XGBRegressor\\nfrom lightgbm import LGBMRegressor\\nfrom catboost import CatBoostRegressor\\n\\nfrom skopt import BayesSearchCV\\nfrom skopt.space import Integer, Real, Categorical\\n\\nimport shap\\nimport joblib\\n\\n\\n# ============================================================\\n# 0. 用户设置：通常只需要修改这里\\n# ============================================================\\n\\n# 代码会从上到下寻找第一个存在的数据文件。\\nDATA_CANDIDATES = [\\n    # 优先填写你电脑上“273数据(1).xlsx”的实际路径\\n    r\\\"E:\\\\温室气体模型\\\\7\\\\273数据(1).xlsx\\\",\\n    r\\\"E:\\\\温室气体模型\\\\7\\\\273数据.xlsx\\\",\\n    r\\\"D:\\\\污染物排放量预测\\\\273数据(1).xlsx\\\",\\n    # 如果Notebook与Excel位于同一文件夹，可直接识别下面的相对路径\\n    r\\\"273数据(1).xlsx\\\",\\n    r\\\"273数据.xlsx\\\",\\n]\\n\\n# Excel工作表。None表示读取第一个工作表。\\nSHEET_NAME = None\\n\\n# 原Notebook使用 header=1；代码若识别失败会自动尝试 header=0。\\nPREFERRED_HEADER = 0\\n\\n# 输出目录。None表示在数据文件同级新建“ML_SHAP_最优模型”。\\nSAVE_DIR = None\\n\\n# 训练集/测试集比例\\nTEST_SIZE = 0.20\\n\\n# 三种气体沿用原Notebook的固定划分随机种子\\nGAS_SPLIT_SEEDS = {\\n    \\\"N2O\\\": 33,\\n    \\\"CO2\\\": 12,\\n    \\\"CH4\\\": 31,\\n}\\n\\n# 贝叶斯优化设置\\nBAYES_N_ITER = 20\\nCV_FOLDS = 3\\nGLOBAL_RANDOM_STATE = 42\\nN_JOBS = -1\\n\\n# 缺失值填补邻居数；若输入变量没有缺失值，该步骤不会改变数据\\nKNN_IMPUTER_NEIGHBORS = 5\\n\\n# 最优模型判定规则：\\n# \\\"test_r2\\\"：按测试集R2最高确定；RMSE、MAE依次作为并列时的辅助指标。\\n# \\\"cv_r2\\\"：按训练集内部交叉验证R2最高确定，测试集只作最终评价。\\n# 为与当前手稿“综合测试集性能筛选”保持一致，默认使用 test_r2。\\nSELECTION_RULE = \\\"test_r2\\\"\\n\\n# SHAP设置\\nSHAP_MAX_DISPLAY = 13\\nSHAP_BACKGROUND_SIZE = 60\\nSHAP_MAX_EXPLAIN_SAMPLES = None   # None表示解释全部测试样本\\nMAKE_DEPENDENCE_PLOTS = True\\nDEPENDENCE_FEATURES = [\\n    \\\"SR\\\", \\\"BS\\\", \\\"BC\\\", \\\"N\\\", \\\"P\\\", \\\"K\\\",\\n    \\\"pH\\\", \\\"SOM\\\", \\\"AN\\\", \\\"AP\\\", \\\"AK\\\", \\\"MAT\\\", \\\"MAP\\\",\\n]\\n\\n# 图片设置\\nDPI = 600\\nSHOW_FIGURES = True\\n\\n\\n# ============================================================\\n# 1. 全局绘图设置\\n# ============================================================\\n\\nwarnings.filterwarnings(\\\"ignore\\\")\\n\\nmpl.rcParams[\\\"font.family\\\"] = \\\"Times New Roman\\\"\\nmpl.rcParams[\\\"font.size\\\"] = 11\\nmpl.rcParams[\\\"axes.unicode_minus\\\"] = False\\nmpl.rcParams[\\\"mathtext.fontset\\\"] = \\\"stix\\\"\\nmpl.rcParams[\\\"figure.dpi\\\"] = 120\\n\\nMODEL_ORDER = [\\n    \\\"GBDT\\\", \\\"XGB\\\", \\\"LightGBM\\\", \\\"CatBoost\\\",\\n    \\\"RF\\\", \\\"ET\\\", \\\"SVR\\\", \\\"KNN\\\", \\\"DT\\\",\\n]\\n\\nMODEL_COLORS = {\\n    \\\"GBDT\\\": \\\"#8DB3E2\\\",\\n    \\\"XGB\\\": \\\"#F4A582\\\",\\n    \\\"LightGBM\\\": \\\"#92C5DE\\\",\\n    \\\"CatBoost\\\": \\\"#D6604D\\\",\\n    \\\"RF\\\": \\\"#B8E186\\\",\\n    \\\"ET\\\": \\\"#7FBC41\\\",\\n    \\\"SVR\\\": \\\"#C2A5CF\\\",\\n    \\\"KNN\\\": \\\"#9970AB\\\",\\n    \\\"DT\\\": \\\"#BDBDBD\\\",\\n}\\n\\nGAS_CONFIGS = {\\n    \\\"N2O\\\": {\\n        \\\"label\\\": r\\\"N$_2$O\\\",\\n        \\\"target_key\\\": \\\"N2O\\\",\\n        \\\"unit\\\": r\\\"kg N$_2$O ha$^{-1}$\\\",\\n    },\\n    \\\"CO2\\\": {\\n        \\\"label\\\": r\\\"CO$_2$\\\",\\n        \\\"target_key\\\": \\\"CO2\\\",\\n        \\\"unit\\\": r\\\"kg CO$_2$ ha$^{-1}$\\\",\\n    },\\n    \\\"CH4\\\": {\\n        \\\"label\\\": r\\\"CH$_4$\\\",\\n        \\\"target_key\\\": \\\"CH4\\\",\\n        \\\"unit\\\": r\\\"kg CH$_4$ ha$^{-1}$\\\",\\n    },\\n}\\n\\nFEATURE_KEYS = [\\n    \\\"SR\\\", \\\"BS\\\", \\\"BC\\\", \\\"N\\\", \\\"P\\\", \\\"K\\\",\\n    \\\"pH\\\", \\\"SOM\\\", \\\"AN\\\", \\\"AP\\\", \\\"AK\\\", \\\"MAT\\\", \\\"MAP\\\",\\n]\\n\\nTREE_MODEL_NAMES = {\\n    \\\"GBDT\\\", \\\"XGB\\\", \\\"LightGBM\\\", \\\"CatBoost\\\", \\\"RF\\\", \\\"ET\\\", \\\"DT\\\"\\n}\\n\\n\\n# ============================================================\\n# 2. 数据列名兼容设置\\n# ============================================================\\n\\nCOLUMN_ALIASES = {\\n    \\\"SR\\\": [\\\"SR\\\", \\\"Straw return\\\", \\\"Straw returning\\\"],\\n    \\\"BS\\\": [\\\"BS\\\", \\\"Biogas slurry\\\", \\\"Biogas slurry application\\\"],\\n    \\\"BC\\\": [\\\"BC\\\", \\\"Biochar\\\", \\\"Biochar application\\\"],\\n    \\\"N\\\": [\\n        \\\"N\\\", \\\"Nitrogen (N) Application Rate\\\",\\n        \\\"Nitrogen application rate\\\", \\\"N application rate\\\",\\n    ],\\n    \\\"P\\\": [\\n        \\\"P\\\", \\\"Phosphorus (P) Application Rate\\\",\\n        \\\"Phosphorus application rate\\\", \\\"P application rate\\\",\\n    ],\\n    \\\"K\\\": [\\n        \\\"K\\\", \\\"Potassium (K) application rate\\\",\\n        \\\"Potassium application rate\\\", \\\"K application rate\\\",\\n    ],\\n    \\\"pH\\\": [\\\"pH\\\", \\\"PH\\\", \\\"Soil pH\\\"],\\n    \\\"SOM\\\": [\\\"SOM\\\", \\\"SOM（g/kg）\\\", \\\"SOM(g/kg)\\\", \\\"Soil organic matter\\\"],\\n    \\\"AN\\\": [\\\"AN\\\", \\\"AN（mg/kg）\\\", \\\"AN(mg/kg)\\\", \\\"Available nitrogen\\\"],\\n    \\\"AP\\\": [\\\"AP\\\", \\\"AP（mg/kg）\\\", \\\"AP(mg/kg)\\\", \\\"Available phosphorus\\\"],\\n    \\\"AK\\\": [\\\"AK\\\", \\\"AK（mg/kg）\\\", \\\"AK(mg/kg)\\\", \\\"Available potassium\\\"],\\n    \\\"MAT\\\": [\\\"MAT\\\", \\\"MAT（℃）\\\", \\\"MAT(℃)\\\", \\\"MAT()\\\", \\\"Mean annual temperature\\\"],\\n    \\\"MAP\\\": [\\n        \\\"MAP\\\", \\\"MAP（mm ）\\\", \\\"MAP（mm）\\\", \\\"MAP(mm )\\\", \\\"MAP(mm)\\\",\\n        \\\"Mean annual precipitation\\\",\\n    ],\\n    \\\"N2O\\\": [\\n        \\\"N2O\\\",\\n        \\\"N2O累计排放量（kg/hm2）\\\",\\n        \\\"N₂O累计排放量（kg/hm2）\\\",\\n        \\\"Cumulative N2O emissions\\\",\\n        \\\"Cumulative N₂O emissions\\\",\\n    ],\\n    \\\"CO2\\\": [\\n        \\\"CO2\\\",\\n        \\\"CO2累计排放量（kg/hm2）\\\",\\n        \\\"CO₂累计排放量（kg/hm2）\\\",\\n        \\\"Cumulative CO2 emissions\\\",\\n        \\\"Cumulative CO₂ emissions\\\",\\n    ],\\n    \\\"CH4\\\": [\\n        \\\"CH4\\\",\\n        \\\"CH4累计排放量（kg/hm2）\\\",\\n        \\\"CH₄累计排放量（kg/hm2）\\\",\\n        \\\"Cumulative CH4 emissions\\\",\\n        \\\"Cumulative CH₄ emissions\\\",\\n    ],\\n}\\n\\n\\ndef normalize_column_name(name):\\n    \\\"\\\"\\\"将中英文括号、空格、下划线等统一，便于匹配列名。\\\"\\\"\\\"\\n    text = str(name).strip().lower()\\n    text = text.replace(\\\"（\\\", \\\"(\\\").replace(\\\"）\\\", \\\")\\\")\\n    text = text.replace(\\\"₂\\\", \\\"2\\\").replace(\\\"₄\\\", \\\"4\\\")\\n    text = text.replace(\\\"℃\\\", \\\"c\\\")\\n    text = re.sub(r\\\"[\\\\s_\\\\-]+\\\", \\\"\\\", text)\\n    return text\\n\\n\\ndef resolve_columns(raw_columns):\\n    \\\"\\\"\\\"根据别名从Excel列名中识别13个特征和3个目标变量。\\\"\\\"\\\"\\n    normalized_to_original = {\\n        normalize_column_name(column): column\\n        for column in raw_columns\\n    }\\n\\n    resolved = {}\\n    unresolved = []\\n\\n    for standard_name, aliases in COLUMN_ALIASES.items():\\n        matched = None\\n\\n        # 先尝试标准列名本身，再尝试全部别名。\\n        # 这样可直接识别本研究最终273条数据中的\\n        # SR、BS、BC、N、P、K、pH、SOM、AN、AP、AK、MAT、MAP、CH4、N2O和CO2。\\n        candidate_aliases = [standard_name] + list(aliases)\\n\\n        for alias in candidate_aliases:\\n            key = normalize_column_name(alias)\\n            if key in normalized_to_original:\\n                matched = normalized_to_original[key]\\n                break\\n\\n        if matched is None:\\n            unresolved.append(standard_name)\\n        else:\\n            resolved[standard_name] = matched\\n\\n    return resolved, unresolved\\n\\n\\ndef find_data_path(candidates):\\n    for candidate in candidates:\\n        if candidate and os.path.exists(candidate):\\n            return os.path.abspath(candidate)\\n\\n    raise FileNotFoundError(\\n        \\\"未找到数据文件。请在 DATA_CANDIDATES 中填写最终数据.xlsx的实际路径。\\\\n\\\"\\n        + \\\"当前尝试路径：\\\\n\\\"\\n        + \\\"\\\\n\\\".join(str(path) for path in candidates)\\n    )\\n\\n\\ndef load_dataset(file_path, sheet_name=None, preferred_header=0):\\n    \\\"\\\"\\\"优先按header=0读取；识别失败时再尝试其他表头位置。\\\"\\\"\\\"\\n    headers_to_try = []\\n    for header in [preferred_header, 0, 1]:\\n        if header not in headers_to_try:\\n            headers_to_try.append(header)\\n\\n    errors = []\\n\\n    for header in headers_to_try:\\n        try:\\n            raw = pd.read_excel(\\n                file_path,\\n                sheet_name=sheet_name if sheet_name is not None else 0,\\n                header=header,\\n                engine=\\\"openpyxl\\\",\\n            )\\n\\n            resolved, unresolved = resolve_columns(raw.columns)\\n\\n            if not unresolved:\\n                selected = pd.DataFrame(index=raw.index)\\n                for standard_name in FEATURE_KEYS + [\\\"N2O\\\", \\\"CO2\\\", \\\"CH4\\\"]:\\n                    selected[standard_name] = pd.to_numeric(\\n                        raw[resolved[standard_name]],\\n                        errors=\\\"coerce\\\",\\n                    )\\n\\n                return selected, raw, resolved, header\\n\\n            available_columns = \\\", \\\".join(str(column) for column in raw.columns)\\n            errors.append(\\n                f\\\"header={header} 时未识别列：{', '.join(unresolved)}\\\\n\\\"\\n                f\\\"当前读取到的列名：{available_columns}\\\"\\n            )\\n\\n        except Exception as exc:\\n            errors.append(f\\\"header={header} 读取失败：{exc}\\\")\\n\\n    raise KeyError(\\n        \\\"无法从Excel中识别完整的13个输入变量和3个目标变量。\\\\n\\\"\\n        \\\"请检查 COLUMN_ALIASES 或Excel表头。\\\\n\\\\n\\\"\\n        + \\\"\\\\n\\\".join(errors)\\n    )\\n\\n\\n# ============================================================\\n# 3. 定义9种模型及贝叶斯搜索空间\\n# ============================================================\\n\\n\\ndef build_model_specs():\\n    \\\"\\\"\\\"\\n    每次调用均返回全新的模型对象。\\n    所有模型均放入同一预处理Pipeline：\\n    KNNImputer -> StandardScaler -> model\\n    \\\"\\\"\\\"\\n    return {\\n        \\\"GBDT\\\": {\\n            \\\"estimator\\\": GradientBoostingRegressor(\\n                random_state=GLOBAL_RANDOM_STATE,\\n            ),\\n            \\\"search_space\\\": {\\n                \\\"model__n_estimators\\\": Integer(100, 500),\\n                \\\"model__learning_rate\\\": Real(0.01, 0.30, prior=\\\"log-uniform\\\"),\\n                \\\"model__max_depth\\\": Integer(2, 6),\\n                \\\"model__subsample\\\": Real(0.60, 1.00),\\n            },\\n        },\\n        \\\"XGB\\\": {\\n            \\\"estimator\\\": XGBRegressor(\\n                random_state=GLOBAL_RANDOM_STATE,\\n                n_jobs=1,\\n                objective=\\\"reg:squarederror\\\",\\n                verbosity=0,\\n            ),\\n            \\\"search_space\\\": {\\n                \\\"model__n_estimators\\\": Integer(100, 500),\\n                \\\"model__max_depth\\\": Integer(3, 10),\\n                \\\"model__learning_rate\\\": Real(0.01, 0.30, prior=\\\"log-uniform\\\"),\\n                \\\"model__subsample\\\": Real(0.60, 1.00),\\n                \\\"model__colsample_bytree\\\": Real(0.60, 1.00),\\n            },\\n        },\\n        \\\"LightGBM\\\": {\\n            \\\"estimator\\\": LGBMRegressor(\\n                random_state=GLOBAL_RANDOM_STATE,\\n                n_jobs=1,\\n                verbosity=-1,\\n            ),\\n            \\\"search_space\\\": {\\n                \\\"model__n_estimators\\\": Integer(100, 500),\\n                \\\"model__num_leaves\\\": Integer(20, 80),\\n                \\\"model__max_depth\\\": Integer(3, 12),\\n                \\\"model__learning_rate\\\": Real(0.01, 0.30, prior=\\\"log-uniform\\\"),\\n                \\\"model__subsample\\\": Real(0.60, 1.00),\\n                \\\"model__colsample_bytree\\\": Real(0.60, 1.00),\\n            },\\n        },\\n        \\\"CatBoost\\\": {\\n            \\\"estimator\\\": CatBoostRegressor(\\n                random_state=GLOBAL_RANDOM_STATE,\\n                verbose=0,\\n                allow_writing_files=False,\\n                thread_count=1,\\n            ),\\n            \\\"search_space\\\": {\\n                \\\"model__depth\\\": Integer(4, 10),\\n                \\\"model__iterations\\\": Integer(100, 500),\\n                \\\"model__learning_rate\\\": Real(0.01, 0.30, prior=\\\"log-uniform\\\"),\\n            },\\n        },\\n        \\\"RF\\\": {\\n            \\\"estimator\\\": RandomForestRegressor(\\n                random_state=GLOBAL_RANDOM_STATE,\\n                n_jobs=1,\\n            ),\\n            \\\"search_space\\\": {\\n                \\\"model__n_estimators\\\": Integer(100, 500),\\n                \\\"model__max_depth\\\": Integer(3, 20),\\n                \\\"model__min_samples_split\\\": Integer(2, 10),\\n            },\\n        },\\n        \\\"ET\\\": {\\n            \\\"estimator\\\": ExtraTreesRegressor(\\n                random_state=GLOBAL_RANDOM_STATE,\\n                n_jobs=1,\\n            ),\\n            \\\"search_space\\\": {\\n                \\\"model__n_estimators\\\": Integer(50, 300),\\n                \\\"model__max_depth\\\": Integer(2, 20),\\n                \\\"model__min_samples_split\\\": Integer(2, 10),\\n            },\\n        },\\n        \\\"SVR\\\": {\\n            \\\"estimator\\\": SVR(kernel=\\\"rbf\\\"),\\n            \\\"search_space\\\": {\\n                \\\"model__C\\\": Real(1e-1, 1e3, prior=\\\"log-uniform\\\"),\\n                \\\"model__gamma\\\": Real(1e-4, 1e-1, prior=\\\"log-uniform\\\"),\\n                \\\"model__epsilon\\\": Real(1e-3, 1.0, prior=\\\"log-uniform\\\"),\\n            },\\n        },\\n        \\\"KNN\\\": {\\n            \\\"estimator\\\": KNeighborsRegressor(),\\n            \\\"search_space\\\": {\\n                \\\"model__n_neighbors\\\": Integer(3, 25),\\n                \\\"model__weights\\\": Categorical([\\\"uniform\\\", \\\"distance\\\"]),\\n                \\\"model__p\\\": Integer(1, 2),\\n            },\\n        },\\n        \\\"DT\\\": {\\n            \\\"estimator\\\": DecisionTreeRegressor(\\n                random_state=GLOBAL_RANDOM_STATE,\\n            ),\\n            \\\"search_space\\\": {\\n                \\\"model__max_depth\\\": Integer(2, 20),\\n                \\\"model__min_samples_split\\\": Integer(2, 10),\\n                \\\"model__min_samples_leaf\\\": Integer(1, 10),\\n            },\\n        },\\n    }\\n\\n\\ndef make_pipeline(estimator):\\n    return Pipeline(\\n        steps=[\\n            (\\n                \\\"imputer\\\",\\n                KNNImputer(n_neighbors=KNN_IMPUTER_NEIGHBORS),\\n            ),\\n            (\\n                \\\"scaler\\\",\\n                StandardScaler(),\\n            ),\\n            (\\n                \\\"model\\\",\\n                estimator,\\n            ),\\n        ]\\n    )\\n\\n\\n# ============================================================\\n# 4. 模型评价与最优模型选择\\n# ============================================================\\n\\n\\ndef calculate_metrics(y_true, y_pred, prefix):\\n    return {\\n        f\\\"{prefix}_R2\\\": r2_score(y_true, y_pred),\\n        f\\\"{prefix}_RMSE\\\": np.sqrt(mean_squared_error(y_true, y_pred)),\\n        f\\\"{prefix}_MAE\\\": mean_absolute_error(y_true, y_pred),\\n    }\\n\\n\\ndef strip_pipeline_prefix(params):\\n    \\\"\\\"\\\"保存参数时去掉 model__ 前缀，便于阅读。\\\"\\\"\\\"\\n    cleaned = {}\\n    for key, value in params.items():\\n        cleaned[key.replace(\\\"model__\\\", \\\"\\\")] = value\\n    return cleaned\\n\\n\\ndef select_best_model(metrics_df, rule=\\\"test_r2\\\"):\\n    if rule == \\\"test_r2\\\":\\n        ordered = metrics_df.sort_values(\\n            by=[\\\"Test_R2\\\", \\\"Test_RMSE\\\", \\\"Test_MAE\\\", \\\"CV_R2\\\"],\\n            ascending=[False, True, True, False],\\n        )\\n    elif rule == \\\"cv_r2\\\":\\n        ordered = metrics_df.sort_values(\\n            by=[\\\"CV_R2\\\", \\\"Test_R2\\\", \\\"Test_RMSE\\\", \\\"Test_MAE\\\"],\\n            ascending=[False, False, True, True],\\n        )\\n    else:\\n        raise ValueError(\\\"SELECTION_RULE 只能设置为 'test_r2' 或 'cv_r2'。\\\")\\n\\n    return ordered.iloc[0][\\\"Model\\\"], ordered.reset_index(drop=True)\\n\\n\\ndef fit_all_models_for_gas(data, gas_key, output_dir):\\n    config = GAS_CONFIGS[gas_key]\\n    target_column = config[\\\"target_key\\\"]\\n\\n    gas_data = data[FEATURE_KEYS + [target_column]].copy()\\n    gas_data = gas_data.dropna(subset=[target_column])\\n\\n    if len(gas_data) < 30:\\n        raise ValueError(\\n            f\\\"{gas_key} 有效样本仅 {len(gas_data)} 条，无法稳定完成当前建模流程。\\\"\\n        )\\n\\n    X = gas_data[FEATURE_KEYS].copy()\\n    y = gas_data[target_column].copy()\\n\\n    X_train, X_test, y_train, y_test = train_test_split(\\n        X,\\n        y,\\n        test_size=TEST_SIZE,\\n        random_state=GAS_SPLIT_SEEDS[gas_key],\\n    )\\n\\n    cv = KFold(\\n        n_splits=CV_FOLDS,\\n        shuffle=True,\\n        random_state=GLOBAL_RANDOM_STATE,\\n    )\\n\\n    model_specs = build_model_specs()\\n\\n    fitted_pipelines = {}\\n    predictions = {}\\n    best_params = {}\\n    metric_rows = []\\n\\n    print(\\\"\\\\n\\\" + \\\"=\\\" * 80)\\n    print(\\n        f\\\"{gas_key}: n={len(gas_data)}, \\\"\\n        f\\\"train={len(X_train)}, test={len(X_test)}, \\\"\\n        f\\\"split seed={GAS_SPLIT_SEEDS[gas_key]}\\\"\\n    )\\n    print(\\\"=\\\" * 80)\\n\\n    for model_name in MODEL_ORDER:\\n        spec = model_specs[model_name]\\n        pipeline = make_pipeline(clone(spec[\\\"estimator\\\"]))\\n\\n        print(f\\\"\\\\n[{gas_key}] 正在优化 {model_name} ...\\\")\\n        start_time = time.time()\\n\\n        optimizer = BayesSearchCV(\\n            estimator=pipeline,\\n            search_spaces=spec[\\\"search_space\\\"],\\n            n_iter=BAYES_N_ITER,\\n            cv=cv,\\n            scoring=\\\"r2\\\",\\n            n_jobs=N_JOBS,\\n            random_state=GLOBAL_RANDOM_STATE,\\n            refit=True,\\n            return_train_score=True,\\n            verbose=0,\\n            error_score=\\\"raise\\\",\\n        )\\n\\n        optimizer.fit(X_train, y_train)\\n        best_pipeline = optimizer.best_estimator_\\n\\n        y_train_pred = best_pipeline.predict(X_train)\\n        y_test_pred = best_pipeline.predict(X_test)\\n\\n        elapsed = time.time() - start_time\\n\\n        row = {\\n            \\\"Gas\\\": gas_key,\\n            \\\"Model\\\": model_name,\\n            \\\"n_total\\\": len(gas_data),\\n            \\\"n_train\\\": len(X_train),\\n            \\\"n_test\\\": len(X_test),\\n            \\\"CV_R2\\\": optimizer.best_score_,\\n            \\\"Fit_seconds\\\": elapsed,\\n        }\\n        row.update(calculate_metrics(y_train, y_train_pred, \\\"Train\\\"))\\n        row.update(calculate_metrics(y_test, y_test_pred, \\\"Test\\\"))\\n        metric_rows.append(row)\\n\\n        fitted_pipelines[model_name] = best_pipeline\\n        best_params[model_name] = strip_pipeline_prefix(optimizer.best_params_)\\n\\n        predictions[model_name] = {\\n            \\\"y_train_true\\\": y_train.to_numpy(),\\n            \\\"y_train_pred\\\": np.asarray(y_train_pred),\\n            \\\"y_test_true\\\": y_test.to_numpy(),\\n            \\\"y_test_pred\\\": np.asarray(y_test_pred),\\n            \\\"test_absolute_error\\\": np.abs(y_test.to_numpy() - np.asarray(y_test_pred)),\\n        }\\n\\n        print(\\n            f\\\"    CV R2={optimizer.best_score_:.4f} | \\\"\\n            f\\\"Test R2={row['Test_R2']:.4f} | \\\"\\n            f\\\"RMSE={row['Test_RMSE']:.4f} | \\\"\\n            f\\\"MAE={row['Test_MAE']:.4f} | \\\"\\n            f\\\"{elapsed:.1f} s\\\"\\n        )\\n        print(f\\\"    Best params: {best_params[model_name]}\\\")\\n\\n    metrics_df = pd.DataFrame(metric_rows)\\n    best_model_name, ranking_df = select_best_model(\\n        metrics_df,\\n        rule=SELECTION_RULE,\\n    )\\n\\n    best_pipeline = fitted_pipelines[best_model_name]\\n\\n    print(\\\"\\\\n\\\" + \\\"-\\\" * 80)\\n    print(\\n        f\\\"{gas_key} 自动选出的最优模型：{best_model_name} \\\"\\n        f\\\"(rule={SELECTION_RULE})\\\"\\n    )\\n    best_row = metrics_df.loc[\\n        metrics_df[\\\"Model\\\"] == best_model_name\\n    ].iloc[0]\\n    print(\\n        f\\\"CV R2={best_row['CV_R2']:.4f}, \\\"\\n        f\\\"Test R2={best_row['Test_R2']:.4f}, \\\"\\n        f\\\"Test RMSE={best_row['Test_RMSE']:.4f}, \\\"\\n        f\\\"Test MAE={best_row['Test_MAE']:.4f}\\\"\\n    )\\n    print(\\\"-\\\" * 80)\\n\\n    # 保存当前气体的模型结果\\n    gas_dir = Path(output_dir) / gas_key\\n    gas_dir.mkdir(parents=True, exist_ok=True)\\n\\n    metrics_df.sort_values(\\n        by=\\\"Test_R2\\\",\\n        ascending=False,\\n    ).to_excel(\\n        gas_dir / f\\\"{gas_key}_all_model_metrics.xlsx\\\",\\n        index=False,\\n    )\\n\\n    ranking_df.to_excel(\\n        gas_dir / f\\\"{gas_key}_model_ranking_{SELECTION_RULE}.xlsx\\\",\\n        index=False,\\n    )\\n\\n    with open(\\n        gas_dir / f\\\"{gas_key}_best_params.json\\\",\\n        \\\"w\\\",\\n        encoding=\\\"utf-8\\\",\\n    ) as file:\\n        json.dump(best_params, file, ensure_ascii=False, indent=2, default=str)\\n\\n    # 保存全部预测值\\n    prediction_rows = []\\n    for model_name in MODEL_ORDER:\\n        pred = predictions[model_name]\\n        for set_name, y_true_values, y_pred_values in [\\n            (\\\"Train\\\", pred[\\\"y_train_true\\\"], pred[\\\"y_train_pred\\\"]),\\n            (\\\"Test\\\", pred[\\\"y_test_true\\\"], pred[\\\"y_test_pred\\\"]),\\n        ]:\\n            for true_value, pred_value in zip(y_true_values, y_pred_values):\\n                prediction_rows.append(\\n                    {\\n                        \\\"Gas\\\": gas_key,\\n                        \\\"Model\\\": model_name,\\n                        \\\"Set\\\": set_name,\\n                        \\\"Observed\\\": true_value,\\n                        \\\"Predicted\\\": pred_value,\\n                        \\\"Absolute_error\\\": abs(true_value - pred_value),\\n                    }\\n                )\\n\\n    pd.DataFrame(prediction_rows).to_excel(\\n        gas_dir / f\\\"{gas_key}_all_predictions.xlsx\\\",\\n        index=False,\\n    )\\n\\n    joblib.dump(\\n        best_pipeline,\\n        gas_dir / f\\\"{gas_key}_best_model_{best_model_name}.joblib\\\",\\n    )\\n\\n    return {\\n        \\\"gas_key\\\": gas_key,\\n        \\\"config\\\": config,\\n        \\\"gas_data\\\": gas_data,\\n        \\\"X_train\\\": X_train,\\n        \\\"X_test\\\": X_test,\\n        \\\"y_train\\\": y_train,\\n        \\\"y_test\\\": y_test,\\n        \\\"metrics_df\\\": metrics_df,\\n        \\\"ranking_df\\\": ranking_df,\\n        \\\"fitted_pipelines\\\": fitted_pipelines,\\n        \\\"predictions\\\": predictions,\\n        \\\"best_params\\\": best_params,\\n        \\\"best_model_name\\\": best_model_name,\\n        \\\"best_pipeline\\\": best_pipeline,\\n        \\\"gas_dir\\\": gas_dir,\\n    }\\n\\n\\n# ============================================================\\n# 5. 性能图：固定划分下的六联图\\n# ============================================================\\n\\n\\ndef add_panel_label(ax, label):\\n    ax.text(\\n        -0.14,\\n        1.05,\\n        label,\\n        transform=ax.transAxes,\\n        fontsize=12,\\n        fontweight=\\\"bold\\\",\\n        va=\\\"top\\\",\\n        ha=\\\"left\\\",\\n    )\\n\\n\\ndef plot_metric_bars(ax, metrics_df, metric, ylabel, best_model_name):\\n    plot_df = (\\n        metrics_df.set_index(\\\"Model\\\")\\n        .loc[MODEL_ORDER]\\n        .reset_index()\\n    )\\n\\n    values = plot_df[metric].to_numpy()\\n    colors = [\\n        MODEL_COLORS[name]\\n        for name in plot_df[\\\"Model\\\"]\\n    ]\\n\\n    bars = ax.bar(\\n        np.arange(len(plot_df)),\\n        values,\\n        color=colors,\\n        edgecolor=\\\"black\\\",\\n        linewidth=0.45,\\n        width=0.72,\\n    )\\n\\n    for index, (bar, name) in enumerate(zip(bars, plot_df[\\\"Model\\\"])):\\n        if name == best_model_name:\\n            bar.set_linewidth(1.8)\\n            bar.set_edgecolor(\\\"black\\\")\\n            ax.scatter(\\n                index,\\n                values[index],\\n                marker=\\\"*\\\",\\n                s=55,\\n                color=\\\"black\\\",\\n                zorder=5,\\n            )\\n\\n    ax.set_xticks(np.arange(len(plot_df)))\\n    ax.set_xticklabels(plot_df[\\\"Model\\\"], rotation=35, ha=\\\"right\\\", fontsize=8.5)\\n    ax.set_ylabel(ylabel)\\n    ax.grid(axis=\\\"y\\\", linestyle=\\\"--\\\", linewidth=0.45, alpha=0.35)\\n    ax.spines[\\\"top\\\"].set_visible(False)\\n    ax.spines[\\\"right\\\"].set_visible(False)\\n\\n\\ndef plot_fit_panel(ax, observed, predicted, title, gas_label, unit, annotate=True):\\n    observed = np.asarray(observed, dtype=float)\\n    predicted = np.asarray(predicted, dtype=float)\\n\\n    ax.scatter(\\n        observed,\\n        predicted,\\n        s=32,\\n        alpha=0.80,\\n        edgecolor=\\\"black\\\",\\n        linewidth=0.35,\\n    )\\n\\n    minimum = float(np.nanmin(np.concatenate([observed, predicted])))\\n    maximum = float(np.nanmax(np.concatenate([observed, predicted])))\\n    padding = (maximum - minimum) * 0.05 if maximum > minimum else 1.0\\n    lower = minimum - padding\\n    upper = maximum + padding\\n\\n    ax.plot(\\n        [lower, upper],\\n        [lower, upper],\\n        linestyle=\\\"--\\\",\\n        linewidth=1.0,\\n        color=\\\"black\\\",\\n        label=\\\"1:1 line\\\",\\n    )\\n\\n    if len(observed) >= 2 and np.std(observed) > 0:\\n        slope, intercept = np.polyfit(observed, predicted, 1)\\n        x_line = np.linspace(lower, upper, 200)\\n        ax.plot(\\n            x_line,\\n            slope * x_line + intercept,\\n            linewidth=1.0,\\n            color=\\\"black\\\",\\n            alpha=0.70,\\n            label=\\\"Linear fit\\\",\\n        )\\n\\n    ax.set_xlim(lower, upper)\\n    ax.set_ylim(lower, upper)\\n    ax.set_aspect(\\\"equal\\\", adjustable=\\\"box\\\")\\n    ax.set_title(title, fontsize=10.5)\\n    ax.set_xlabel(f\\\"Observed {gas_label} emissions ({unit})\\\")\\n    ax.set_ylabel(f\\\"Predicted {gas_label} emissions ({unit})\\\")\\n    ax.grid(linestyle=\\\"--\\\", linewidth=0.40, alpha=0.30)\\n    ax.spines[\\\"top\\\"].set_visible(False)\\n    ax.spines[\\\"right\\\"].set_visible(False)\\n\\n    if annotate:\\n        text = (\\n            rf\\\"$R^2$ = {r2_score(observed, predicted):.4f}\\\" \\\"\\\\n\\\"\\n            rf\\\"RMSE = {np.sqrt(mean_squared_error(observed, predicted)):.4f}\\\" \\\"\\\\n\\\"\\n            rf\\\"MAE = {mean_absolute_error(observed, predicted):.4f}\\\"\\n        )\\n        ax.text(\\n            0.04,\\n            0.96,\\n            text,\\n            transform=ax.transAxes,\\n            va=\\\"top\\\",\\n            ha=\\\"left\\\",\\n            fontsize=8.5,\\n            bbox=dict(\\n                boxstyle=\\\"round,pad=0.30\\\",\\n                facecolor=\\\"white\\\",\\n                edgecolor=\\\"black\\\",\\n                linewidth=0.5,\\n                alpha=0.85,\\n            ),\\n        )\\n\\n\\ndef plot_performance_six_panel(result):\\n    gas_key = result[\\\"gas_key\\\"]\\n    config = result[\\\"config\\\"]\\n    metrics_df = result[\\\"metrics_df\\\"]\\n    predictions = result[\\\"predictions\\\"]\\n    best_model_name = result[\\\"best_model_name\\\"]\\n    best_pred = predictions[best_model_name]\\n\\n    fig, axes = plt.subplots(\\n        2,\\n        3,\\n        figsize=(13.2, 8.2),\\n    )\\n    axes = axes.ravel()\\n\\n    plot_metric_bars(\\n        axes[0], metrics_df, \\\"Test_R2\\\", r\\\"Testing $R^2$\\\", best_model_name\\n    )\\n    plot_metric_bars(\\n        axes[1], metrics_df, \\\"Test_RMSE\\\", \\\"Testing RMSE\\\", best_model_name\\n    )\\n    plot_metric_bars(\\n        axes[2], metrics_df, \\\"Test_MAE\\\", \\\"Testing MAE\\\", best_model_name\\n    )\\n\\n    error_data = [\\n        predictions[name][\\\"test_absolute_error\\\"]\\n        for name in MODEL_ORDER\\n    ]\\n    box = axes[3].boxplot(\\n        error_data,\\n        labels=MODEL_ORDER,\\n        showfliers=True,\\n        patch_artist=True,\\n        widths=0.62,\\n        medianprops={\\\"color\\\": \\\"black\\\", \\\"linewidth\\\": 1.0},\\n        whiskerprops={\\\"color\\\": \\\"black\\\", \\\"linewidth\\\": 0.65},\\n        capprops={\\\"color\\\": \\\"black\\\", \\\"linewidth\\\": 0.65},\\n        boxprops={\\\"edgecolor\\\": \\\"black\\\", \\\"linewidth\\\": 0.65},\\n        flierprops={\\n            \\\"marker\\\": \\\"o\\\",\\n            \\\"markersize\\\": 2.8,\\n            \\\"markerfacecolor\\\": \\\"gray\\\",\\n            \\\"markeredgecolor\\\": \\\"gray\\\",\\n            \\\"alpha\\\": 0.55,\\n        },\\n    )\\n    for patch, name in zip(box[\\\"boxes\\\"], MODEL_ORDER):\\n        patch.set_facecolor(MODEL_COLORS[name])\\n        patch.set_alpha(0.75)\\n        if name == best_model_name:\\n            patch.set_linewidth(1.8)\\n\\n    axes[3].tick_params(axis=\\\"x\\\", rotation=35, labelsize=8.5)\\n    axes[3].set_ylabel(f\\\"Absolute error ({config['unit']})\\\")\\n    axes[3].grid(axis=\\\"y\\\", linestyle=\\\"--\\\", linewidth=0.45, alpha=0.35)\\n    axes[3].spines[\\\"top\\\"].set_visible(False)\\n    axes[3].spines[\\\"right\\\"].set_visible(False)\\n\\n    train_observed = best_pred[\\\"y_train_true\\\"]\\n    train_predicted = best_pred[\\\"y_train_pred\\\"]\\n    test_observed = best_pred[\\\"y_test_true\\\"]\\n    test_predicted = best_pred[\\\"y_test_pred\\\"]\\n\\n    # 训练集和测试集共同展示\\n    axes[4].scatter(\\n        train_observed,\\n        train_predicted,\\n        s=28,\\n        alpha=0.72,\\n        label=\\\"Train\\\",\\n        edgecolor=\\\"black\\\",\\n        linewidth=0.30,\\n    )\\n    axes[4].scatter(\\n        test_observed,\\n        test_predicted,\\n        s=34,\\n        alpha=0.82,\\n        label=\\\"Test\\\",\\n        edgecolor=\\\"black\\\",\\n        linewidth=0.35,\\n    )\\n\\n    all_observed = np.concatenate([train_observed, test_observed])\\n    all_predicted = np.concatenate([train_predicted, test_predicted])\\n    minimum = float(np.nanmin(np.concatenate([all_observed, all_predicted])))\\n    maximum = float(np.nanmax(np.concatenate([all_observed, all_predicted])))\\n    padding = (maximum - minimum) * 0.05 if maximum > minimum else 1.0\\n    lower = minimum - padding\\n    upper = maximum + padding\\n    axes[4].plot([lower, upper], [lower, upper], \\\"k--\\\", linewidth=1.0)\\n    axes[4].set_xlim(lower, upper)\\n    axes[4].set_ylim(lower, upper)\\n    axes[4].set_aspect(\\\"equal\\\", adjustable=\\\"box\\\")\\n    axes[4].set_xlabel(f\\\"Observed {config['label']} emissions ({config['unit']})\\\")\\n    axes[4].set_ylabel(f\\\"Predicted {config['label']} emissions ({config['unit']})\\\")\\n    axes[4].set_title(f\\\"{best_model_name}: training and testing\\\")\\n    axes[4].legend(frameon=False, fontsize=8.5)\\n    axes[4].grid(linestyle=\\\"--\\\", linewidth=0.40, alpha=0.30)\\n    axes[4].spines[\\\"top\\\"].set_visible(False)\\n    axes[4].spines[\\\"right\\\"].set_visible(False)\\n\\n    plot_fit_panel(\\n        axes[5],\\n        test_observed,\\n        test_predicted,\\n        title=f\\\"{best_model_name}: testing set\\\",\\n        gas_label=config[\\\"label\\\"],\\n        unit=config[\\\"unit\\\"],\\n        annotate=True,\\n    )\\n\\n    for ax, label in zip(axes, [\\\"(a)\\\", \\\"(b)\\\", \\\"(c)\\\", \\\"(d)\\\", \\\"(e)\\\", \\\"(f)\\\"]):\\n        add_panel_label(ax, label)\\n\\n    fig.suptitle(\\n        f\\\"{config['label']} emission prediction: model comparison and selected model\\\",\\n        fontsize=13,\\n        y=0.995,\\n    )\\n    fig.tight_layout(rect=[0, 0, 1, 0.97], w_pad=1.2, h_pad=1.5)\\n\\n    save_path = result[\\\"gas_dir\\\"] / f\\\"{gas_key}_model_performance_6panel.png\\\"\\n    fig.savefig(save_path, dpi=DPI, bbox_inches=\\\"tight\\\")\\n\\n    if SHOW_FIGURES:\\n        plt.show()\\n    else:\\n        plt.close(fig)\\n\\n\\n# ============================================================\\n# 6. SHAP计算：始终使用当前气体自动选出的最优模型\\n# ============================================================\\n\\n\\ndef get_original_scale_imputed_data(pipeline, X):\\n    imputer = pipeline.named_steps[\\\"imputer\\\"]\\n    imputed = imputer.transform(X)\\n    return pd.DataFrame(\\n        imputed,\\n        columns=FEATURE_KEYS,\\n        index=X.index,\\n    )\\n\\n\\ndef get_standardized_data(pipeline, X):\\n    imputer = pipeline.named_steps[\\\"imputer\\\"]\\n    scaler = pipeline.named_steps[\\\"scaler\\\"]\\n    imputed = imputer.transform(X)\\n    scaled = scaler.transform(imputed)\\n    return pd.DataFrame(\\n        scaled,\\n        columns=FEATURE_KEYS,\\n        index=X.index,\\n    )\\n\\n\\ndef compute_shap_for_best_model(result):\\n    gas_key = result[\\\"gas_key\\\"]\\n    model_name = result[\\\"best_model_name\\\"]\\n    pipeline = result[\\\"best_pipeline\\\"]\\n    estimator = pipeline.named_steps[\\\"model\\\"]\\n\\n    X_train = result[\\\"X_train\\\"]\\n    X_test = result[\\\"X_test\\\"]\\n\\n    if SHAP_MAX_EXPLAIN_SAMPLES is not None:\\n        explain_n = min(SHAP_MAX_EXPLAIN_SAMPLES, len(X_test))\\n        X_explain = X_test.sample(\\n            n=explain_n,\\n            random_state=GLOBAL_RANDOM_STATE,\\n        )\\n    else:\\n        X_explain = X_test.copy()\\n\\n    X_display = get_original_scale_imputed_data(pipeline, X_explain)\\n\\n    print(\\n        f\\\"\\\\n[{gas_key}] 使用最优模型 {model_name} 计算SHAP，\\\"\\n        f\\\"解释样本数={len(X_explain)}\\\"\\n    )\\n\\n    if model_name in TREE_MODEL_NAMES:\\n        X_explain_scaled = get_standardized_data(pipeline, X_explain)\\n        estimator = pipeline.named_steps[\\\"model\\\"]\\n\\n        try:\\n            explainer = shap.TreeExplainer(estimator)\\n            raw_values = explainer.shap_values(X_explain_scaled)\\n\\n            if isinstance(raw_values, list):\\n                raw_values = raw_values[0]\\n\\n            base_value = explainer.expected_value\\n            if np.ndim(base_value) > 0:\\n                base_value = np.asarray(base_value).reshape(-1)[0]\\n\\n            base_values = np.repeat(float(base_value), len(X_explain_scaled))\\n            shap_values = np.asarray(raw_values)\\n\\n        except Exception as tree_error:\\n            print(f\\\"TreeExplainer失败，改用通用PermutationExplainer：{tree_error}\\\")\\n            background_n = min(SHAP_BACKGROUND_SIZE, len(X_train))\\n            background = X_train.sample(\\n                n=background_n,\\n                random_state=GLOBAL_RANDOM_STATE,\\n            )\\n            explainer = shap.Explainer(\\n                pipeline.predict,\\n                background,\\n                algorithm=\\\"permutation\\\",\\n            )\\n            explanation = explainer(\\n                X_explain,\\n                max_evals=2 * len(FEATURE_KEYS) + 1,\\n            )\\n            shap_values = np.asarray(explanation.values)\\n            base_values = np.asarray(explanation.base_values)\\n\\n    else:\\n        background_n = min(SHAP_BACKGROUND_SIZE, len(X_train))\\n        background = X_train.sample(\\n            n=background_n,\\n            random_state=GLOBAL_RANDOM_STATE,\\n        )\\n\\n        explainer = shap.Explainer(\\n            pipeline.predict,\\n            background,\\n            algorithm=\\\"permutation\\\",\\n        )\\n        explanation = explainer(\\n            X_explain,\\n            max_evals=2 * len(FEATURE_KEYS) + 1,\\n        )\\n        shap_values = np.asarray(explanation.values)\\n        base_values = np.asarray(explanation.base_values)\\n\\n    if shap_values.ndim == 3 and shap_values.shape[-1] == 1:\\n        shap_values = shap_values[:, :, 0]\\n\\n    shap_explanation = shap.Explanation(\\n        values=shap_values,\\n        base_values=base_values,\\n        data=X_display.to_numpy(),\\n        feature_names=FEATURE_KEYS,\\n    )\\n\\n    mean_abs_shap = np.mean(np.abs(shap_values), axis=0)\\n    importance_df = pd.DataFrame(\\n        {\\n            \\\"Gas\\\": gas_key,\\n            \\\"Model\\\": model_name,\\n            \\\"Feature\\\": FEATURE_KEYS,\\n            \\\"Mean_abs_SHAP\\\": mean_abs_shap,\\n        }\\n    ).sort_values(\\n        by=\\\"Mean_abs_SHAP\\\",\\n        ascending=False,\\n    ).reset_index(drop=True)\\n\\n    importance_df.to_excel(\\n        result[\\\"gas_dir\\\"] / f\\\"{gas_key}_{model_name}_SHAP_importance.xlsx\\\",\\n        index=False,\\n    )\\n\\n    np.savez_compressed(\\n        result[\\\"gas_dir\\\"] / f\\\"{gas_key}_{model_name}_SHAP_values.npz\\\",\\n        shap_values=shap_values,\\n        base_values=base_values,\\n        feature_values=X_display.to_numpy(),\\n        feature_names=np.array(FEATURE_KEYS, dtype=object),\\n    )\\n\\n    result[\\\"shap_explanation\\\"] = shap_explanation\\n    result[\\\"shap_values\\\"] = shap_values\\n    result[\\\"shap_display_data\\\"] = X_display\\n    result[\\\"shap_importance_df\\\"] = importance_df\\n\\n    return result\\n\\n\\n# ============================================================\\n# 7. 单个气体SHAP图\\n# ============================================================\\n\\n\\ndef plot_individual_shap(result):\\n    gas_key = result[\\\"gas_key\\\"]\\n    config = result[\\\"config\\\"]\\n    model_name = result[\\\"best_model_name\\\"]\\n    shap_values = result[\\\"shap_values\\\"]\\n    display_data = result[\\\"shap_display_data\\\"]\\n    importance_df = result[\\\"shap_importance_df\\\"]\\n\\n    # 7.1 标准beeswarm图\\n    fig = plt.figure(figsize=(7.2, 6.0))\\n    shap.summary_plot(\\n        shap_values,\\n        display_data,\\n        feature_names=FEATURE_KEYS,\\n        plot_type=\\\"dot\\\",\\n        max_display=SHAP_MAX_DISPLAY,\\n        show=False,\\n        plot_size=None,\\n    )\\n    plt.title(\\n        f\\\"{config['label']} — {model_name}\\\",\\n        fontsize=13,\\n        pad=12,\\n    )\\n    plt.xlabel(\\\"SHAP value (impact on model output)\\\")\\n    plt.tight_layout()\\n    fig.savefig(\\n        result[\\\"gas_dir\\\"] / f\\\"{gas_key}_{model_name}_SHAP_beeswarm.png\\\",\\n        dpi=DPI,\\n        bbox_inches=\\\"tight\\\",\\n    )\\n    if SHOW_FIGURES:\\n        plt.show()\\n    else:\\n        plt.close(fig)\\n\\n    # 7.2 Mean |SHAP|条形图\\n    plot_df = importance_df.head(SHAP_MAX_DISPLAY).iloc[::-1]\\n    fig, ax = plt.subplots(figsize=(6.5, 5.6))\\n    ax.barh(\\n        plot_df[\\\"Feature\\\"],\\n        plot_df[\\\"Mean_abs_SHAP\\\"],\\n        color=\\\"#80B1D3\\\",\\n        edgecolor=\\\"black\\\",\\n        linewidth=0.45,\\n    )\\n    ax.set_xlabel(\\\"Mean |SHAP value|\\\")\\n    ax.set_ylabel(\\\"\\\")\\n    ax.set_title(f\\\"{config['label']} — {model_name}\\\", fontsize=13)\\n    ax.grid(axis=\\\"x\\\", linestyle=\\\"--\\\", linewidth=0.45, alpha=0.35)\\n    ax.spines[\\\"top\\\"].set_visible(False)\\n    ax.spines[\\\"right\\\"].set_visible(False)\\n    fig.tight_layout()\\n    fig.savefig(\\n        result[\\\"gas_dir\\\"] / f\\\"{gas_key}_{model_name}_SHAP_bar.png\\\",\\n        dpi=DPI,\\n        bbox_inches=\\\"tight\\\",\\n    )\\n    if SHOW_FIGURES:\\n        plt.show()\\n    else:\\n        plt.close(fig)\\n\\n\\n# ============================================================\\n# 8. 三种气体SHAP拼图\\n# ============================================================\\n\\n\\ndef plot_combined_shap(results, output_dir):\\n    fig, axes = plt.subplots(\\n        1,\\n        3,\\n        figsize=(16.2, 6.0),\\n    )\\n\\n    panel_labels = [\\\"(a)\\\", \\\"(b)\\\", \\\"(c)\\\"]\\n\\n    for ax, gas_key, panel_label in zip(\\n        axes,\\n        [\\\"N2O\\\", \\\"CO2\\\", \\\"CH4\\\"],\\n        panel_labels,\\n    ):\\n        result = results[gas_key]\\n        plt.sca(ax)\\n        shap.summary_plot(\\n            result[\\\"shap_values\\\"],\\n            result[\\\"shap_display_data\\\"],\\n            feature_names=FEATURE_KEYS,\\n            plot_type=\\\"dot\\\",\\n            max_display=SHAP_MAX_DISPLAY,\\n            color_bar=False,\\n            show=False,\\n            plot_size=None,\\n        )\\n        ax.set_title(\\n            f\\\"{panel_label} {result['config']['label']} \\\"\\n            f\\\"({result['best_model_name']})\\\",\\n            fontsize=12,\\n            pad=10,\\n        )\\n        ax.set_xlabel(\\\"SHAP value\\\")\\n        ax.tick_params(axis=\\\"both\\\", labelsize=8.5)\\n\\n    color_mapper = ScalarMappable(\\n        norm=Normalize(vmin=0, vmax=1),\\n        cmap=shap.plots.colors.red_blue,\\n    )\\n    color_mapper.set_array([])\\n    colorbar = fig.colorbar(\\n        color_mapper,\\n        ax=list(axes),\\n        fraction=0.018,\\n        pad=0.025,\\n        aspect=35,\\n    )\\n    colorbar.set_ticks([0, 1])\\n    colorbar.set_ticklabels([\\\"Low\\\", \\\"High\\\"])\\n    colorbar.set_label(\\\"Feature value\\\", fontsize=11)\\n    colorbar.ax.tick_params(labelsize=9)\\n\\n    fig.subplots_adjust(\\n        left=0.07,\\n        right=0.93,\\n        bottom=0.13,\\n        top=0.90,\\n        wspace=0.48,\\n    )\\n\\n    save_path = Path(output_dir) / \\\"SHAP_beeswarm_three_gases_best_models.png\\\"\\n    fig.savefig(save_path, dpi=DPI, bbox_inches=\\\"tight\\\")\\n\\n    if SHOW_FIGURES:\\n        plt.show()\\n    else:\\n        plt.close(fig)\\n\\n\\n# ============================================================\\n# 9. SHAP依赖图：横坐标保持原始单位\\n# ============================================================\\n\\n\\ndef safe_filename(text):\\n    return re.sub(r\\\"[^A-Za-z0-9_.-]+\\\", \\\"_\\\", str(text))\\n\\n\\ndef plot_dependence_figures(result):\\n    if not MAKE_DEPENDENCE_PLOTS:\\n        return\\n\\n    gas_key = result[\\\"gas_key\\\"]\\n    model_name = result[\\\"best_model_name\\\"]\\n    shap_values = result[\\\"shap_values\\\"]\\n    display_data = result[\\\"shap_display_data\\\"]\\n\\n    dependence_dir = result[\\\"gas_dir\\\"] / \\\"SHAP_dependence\\\"\\n    dependence_dir.mkdir(parents=True, exist_ok=True)\\n\\n    for feature in DEPENDENCE_FEATURES:\\n        if feature not in FEATURE_KEYS:\\n            continue\\n\\n        fig = plt.figure(figsize=(6.2, 4.8))\\n        shap.dependence_plot(\\n            feature,\\n            shap_values,\\n            display_data,\\n            feature_names=FEATURE_KEYS,\\n            interaction_index=\\\"auto\\\",\\n            show=False,\\n            alpha=0.78,\\n            dot_size=28,\\n        )\\n        plt.title(\\n            f\\\"{GAS_CONFIGS[gas_key]['label']} — {model_name}: {feature}\\\",\\n            fontsize=12,\\n            pad=10,\\n        )\\n        plt.tight_layout()\\n        fig.savefig(\\n            dependence_dir / (\\n                f\\\"{gas_key}_{model_name}_dependence_{safe_filename(feature)}.png\\\"\\n            ),\\n            dpi=DPI,\\n            bbox_inches=\\\"tight\\\",\\n        )\\n\\n        if SHOW_FIGURES:\\n            plt.show()\\n        else:\\n            plt.close(fig)\\n\\n\\n# ============================================================\\n# 10. 汇总保存\\n# ============================================================\\n\\n\\ndef save_global_summary(results, output_dir, resolved_columns, used_header, data_path):\\n    summary_rows = []\\n    metrics_sheets = {}\\n    importance_sheets = {}\\n\\n    for gas_key in [\\\"N2O\\\", \\\"CO2\\\", \\\"CH4\\\"]:\\n        result = results[gas_key]\\n        best_name = result[\\\"best_model_name\\\"]\\n        best_row = result[\\\"metrics_df\\\"].loc[\\n            result[\\\"metrics_df\\\"][\\\"Model\\\"] == best_name\\n        ].iloc[0]\\n\\n        summary_rows.append(\\n            {\\n                \\\"Gas\\\": gas_key,\\n                \\\"Best_model\\\": best_name,\\n                \\\"Selection_rule\\\": SELECTION_RULE,\\n                \\\"n_total\\\": best_row[\\\"n_total\\\"],\\n                \\\"n_train\\\": best_row[\\\"n_train\\\"],\\n                \\\"n_test\\\": best_row[\\\"n_test\\\"],\\n                \\\"CV_R2\\\": best_row[\\\"CV_R2\\\"],\\n                \\\"Train_R2\\\": best_row[\\\"Train_R2\\\"],\\n                \\\"Train_RMSE\\\": best_row[\\\"Train_RMSE\\\"],\\n                \\\"Train_MAE\\\": best_row[\\\"Train_MAE\\\"],\\n                \\\"Test_R2\\\": best_row[\\\"Test_R2\\\"],\\n                \\\"Test_RMSE\\\": best_row[\\\"Test_RMSE\\\"],\\n                \\\"Test_MAE\\\": best_row[\\\"Test_MAE\\\"],\\n            }\\n        )\\n\\n        metrics_sheets[gas_key] = result[\\\"metrics_df\\\"].sort_values(\\n            by=\\\"Test_R2\\\",\\n            ascending=False,\\n        )\\n        importance_sheets[gas_key] = result[\\\"shap_importance_df\\\"]\\n\\n    summary_df = pd.DataFrame(summary_rows)\\n    summary_df.to_excel(\\n        Path(output_dir) / \\\"Best_models_summary.xlsx\\\",\\n        index=False,\\n    )\\n\\n    with pd.ExcelWriter(\\n        Path(output_dir) / \\\"All_results_and_SHAP.xlsx\\\",\\n        engine=\\\"openpyxl\\\",\\n    ) as writer:\\n        summary_df.to_excel(writer, sheet_name=\\\"Best_models\\\", index=False)\\n        for gas_key, table in metrics_sheets.items():\\n            table.to_excel(writer, sheet_name=f\\\"{gas_key}_metrics\\\", index=False)\\n        for gas_key, table in importance_sheets.items():\\n            table.to_excel(writer, sheet_name=f\\\"{gas_key}_SHAP\\\", index=False)\\n\\n    run_info = {\\n        \\\"data_path\\\": str(data_path),\\n        \\\"excel_header\\\": used_header,\\n        \\\"resolved_columns\\\": {key: str(value) for key, value in resolved_columns.items()},\\n        \\\"feature_order\\\": FEATURE_KEYS,\\n        \\\"test_size\\\": TEST_SIZE,\\n        \\\"split_seeds\\\": GAS_SPLIT_SEEDS,\\n        \\\"bayes_n_iter\\\": BAYES_N_ITER,\\n        \\\"cv_folds\\\": CV_FOLDS,\\n        \\\"selection_rule\\\": SELECTION_RULE,\\n        \\\"all_features_standardized\\\": True,\\n        \\\"knn_imputer_neighbors\\\": KNN_IMPUTER_NEIGHBORS,\\n    }\\n\\n    with open(\\n        Path(output_dir) / \\\"run_configuration.json\\\",\\n        \\\"w\\\",\\n        encoding=\\\"utf-8\\\",\\n    ) as file:\\n        json.dump(run_info, file, ensure_ascii=False, indent=2)\\n\\n    print(\\\"\\\\n最终最优模型汇总：\\\")\\n    print(summary_df.to_string(index=False))\\n\\n\\n# ============================================================\\n# 11. 主程序\\n# ============================================================\\n\\n\\ndef main():\\n    data_path = find_data_path(DATA_CANDIDATES)\\n\\n    if SAVE_DIR is None:\\n        output_dir = Path(data_path).parent / \\\"ML_SHAP_最优模型\\\"\\n    else:\\n        output_dir = Path(SAVE_DIR)\\n    output_dir.mkdir(parents=True, exist_ok=True)\\n\\n    print(\\\"数据文件：\\\", data_path)\\n    print(\\\"输出目录：\\\", output_dir)\\n\\n    data, raw_data, resolved_columns, used_header = load_dataset(\\n        data_path,\\n        sheet_name=SHEET_NAME,\\n        preferred_header=PREFERRED_HEADER,\\n    )\\n\\n    print(f\\\"Excel读取表头：header={used_header}\\\")\\n    print(f\\\"原始记录数：{len(raw_data)}\\\")\\n    print(\\\"识别到的列：\\\")\\n    for key in FEATURE_KEYS + [\\\"N2O\\\", \\\"CO2\\\", \\\"CH4\\\"]:\\n        print(f\\\"  {key:>4s} <- {resolved_columns[key]}\\\")\\n\\n    print(\\\"\\\\n各变量缺失数：\\\")\\n    print(data.isna().sum().to_string())\\n\\n    # 保存识别后的标准化列名数据，便于核对；这里的“标准化”指列名统一，\\n    # 数值Z-score只在每个训练折内部完成。\\n    data.to_excel(\\n        output_dir / \\\"recognized_modeling_data.xlsx\\\",\\n        index=False,\\n    )\\n\\n    results = {}\\n\\n    for gas_key in [\\\"N2O\\\", \\\"CO2\\\", \\\"CH4\\\"]:\\n        result = fit_all_models_for_gas(\\n            data=data,\\n            gas_key=gas_key,\\n            output_dir=output_dir,\\n        )\\n        plot_performance_six_panel(result)\\n        result = compute_shap_for_best_model(result)\\n        plot_individual_shap(result)\\n        plot_dependence_figures(result)\\n        results[gas_key] = result\\n\\n    plot_combined_shap(results, output_dir)\\n\\n    save_global_summary(\\n        results=results,\\n        output_dir=output_dir,\\n        resolved_columns=resolved_columns,\\n        used_header=used_header,\\n        data_path=data_path,\\n    )\\n\\n    print(\\\"\\\\n\\\" + \\\"=\\\" * 80)\\n    print(\\\"全部分析完成。\\\")\\n    print(f\\\"结果保存在：{output_dir}\\\")\\n    print(\\\"=\\\" * 80)\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\"},\"evaluate\":{\"filename\":\"GHG_repeated_outer_split_6panel_exact.py\",\"source\":\"# -*- coding: utf-8 -*-\\n\\\"\\\"\\\"\\n三种温室气体：多次外层随机划分 + 重复性能评价 + 参考格式六联图\\n================================================================\\n\\n主要功能\\n1. 读取最终273条数据；\\n2. 对 N2O、CO2、CH4 分别建模；\\n3. 13个输入变量统一执行 KNNImputer + StandardScaler；\\n4. 复用之前已经保存的最优超参数；若找不到，则在固定训练集上进行一次贝叶斯优化；\\n5. 进行多次外层随机训练集/测试集划分；\\n6. 保存 repeat_metrics_df、重复测试集预测值及模型稳定性汇总；\\n7. 根据重复划分结果确定每种气体的最优模型；\\n8. 严格按照参考图格式，为每种气体绘制2×3六联图：\\n   (a) Testing R² 箱线图\\n   (b) Testing RMSE 箱线图\\n   (c) Testing MAE 箱线图\\n   (d) Testing Absolute Error 箱线图\\n   (e) 最优模型训练集和测试集拟合图\\n   (f) 最优模型测试集拟合图\\n\\n说明\\n- 默认使用“固定最优超参数 + 多次外层随机划分”评价模型稳定性，避免在每次外层划分中\\n  重复进行昂贵的贝叶斯优化。\\n- 如果之前完整代码已经运行，并在各气体文件夹保存了 *_best_params.json，程序会直接复用。\\n- 如果没有找到参数文件，程序会自动对9个模型各进行一次贝叶斯优化，然后再开展重复划分。\\n- 为降低内存占用，所有模型线程数均设为1，绘图时只在保存阶段使用600 dpi。\\n\\n依赖安装：\\npip install pandas numpy matplotlib openpyxl scikit-learn scikit-optimize xgboost lightgbm catboost joblib\\n\\\"\\\"\\\"\\n\\nimport os\\nimport re\\nimport gc\\nimport json\\nimport time\\nimport warnings\\nfrom pathlib import Path\\n\\nimport numpy as np\\nimport pandas as pd\\nimport matplotlib as mpl\\nimport matplotlib.pyplot as plt\\n\\nfrom sklearn.base import clone\\nfrom sklearn.pipeline import Pipeline\\nfrom sklearn.impute import KNNImputer\\nfrom sklearn.preprocessing import StandardScaler\\nfrom sklearn.model_selection import train_test_split, KFold\\nfrom sklearn.metrics import r2_score, mean_squared_error, mean_absolute_error\\nfrom sklearn.ensemble import (\\n    GradientBoostingRegressor,\\n    RandomForestRegressor,\\n    ExtraTreesRegressor,\\n)\\nfrom sklearn.tree import DecisionTreeRegressor\\nfrom sklearn.neighbors import KNeighborsRegressor\\nfrom sklearn.svm import SVR\\n\\nfrom xgboost import XGBRegressor\\nfrom lightgbm import LGBMRegressor\\nfrom catboost import CatBoostRegressor\\n\\nfrom skopt import BayesSearchCV\\nfrom skopt.space import Integer, Real, Categorical\\n\\n\\n# ============================================================\\n# 0. 用户设置：通常只需要修改这里\\n# ============================================================\\n\\nDATA_CANDIDATES = [\\n    r\\\"E:\\\\温室气体模型\\\\7\\\\273数据(1).xlsx\\\",\\n    r\\\"E:\\\\温室气体模型\\\\7\\\\273数据.xlsx\\\",\\n    r\\\"273数据(1).xlsx\\\",\\n    r\\\"273数据.xlsx\\\",\\n]\\n\\nSHEET_NAME = None\\nPREFERRED_HEADER = 0\\n\\n# 之前完整模型代码的输出目录。\\n# None：自动使用“数据文件同级/ML_SHAP_最优模型”。\\nPREVIOUS_RESULT_DIR = None\\n\\n# 本次重复划分结果目录。\\n# None：自动使用“数据文件同级/Repeated_outer_split_6panel”。\\nSAVE_DIR = None\\n\\nTEST_SIZE = 0.20\\n\\n# 外层随机划分次数。先用30次；确认运行稳定后可改为50。\\nN_REPEATS = 30\\n\\n# 三种气体固定展示划分，用于六联图(e)(f)。\\n# (a)-(d)使用全部重复划分结果；(e)(f)仅用于展示一个可重复的训练/测试拟合结果。\\nDISPLAY_SPLIT_SEEDS = {\\n    \\\"N2O\\\": 33,\\n    \\\"CO2\\\": 12,\\n    \\\"CH4\\\": 31,\\n}\\n\\n# 外层随机种子起点；第r次划分使用 OUTER_SEED_START + r。\\nOUTER_SEED_START = 1000\\n\\n# 如果中途中断，再次运行时自动读取CSV并跳过已完成的模型-重复组合。\\nRESUME_FROM_CHECKPOINT = True\\n\\n# 缺失值与标准化\\nKNN_IMPUTER_NEIGHBORS = 5\\n\\n# 若找不到旧参数，自动进行一次贝叶斯优化\\nTUNE_IF_PARAMS_MISSING = True\\nBAYES_N_ITER = 20\\nCV_FOLDS = 3\\nGLOBAL_RANDOM_STATE = 42\\n\\n# 为避免内核崩溃，保持单线程\\nN_JOBS = 1\\n\\n# 最优模型依据：重复划分下中位数R²最高；若并列，则中位RMSE和MAE更低者优先。\\nSELECTION_STATISTIC = \\\"median\\\"\\n\\n# 图像设置\\nSAVE_DPI = 600\\nSHOW_FIGURES = False\\n\\n# 参考图统一为橙色箱体\\nBOX_FACE_COLOR = \\\"#F28E63\\\"\\nTRAIN_COLOR = \\\"#58B7AE\\\"\\nTEST_COLOR = \\\"#F28E63\\\"\\n\\n\\n# ============================================================\\n# 1. 全局设置\\n# ============================================================\\n\\nwarnings.filterwarnings(\\\"ignore\\\")\\n\\nmpl.rcParams[\\\"font.family\\\"] = \\\"Times New Roman\\\"\\nmpl.rcParams[\\\"font.size\\\"] = 9\\nmpl.rcParams[\\\"axes.unicode_minus\\\"] = False\\nmpl.rcParams[\\\"mathtext.fontset\\\"] = \\\"stix\\\"\\nmpl.rcParams[\\\"figure.dpi\\\"] = 120\\n\\nMODEL_ORDER = [\\n    \\\"GBDT\\\", \\\"XGB\\\", \\\"LightGBM\\\", \\\"CatBoost\\\",\\n    \\\"RF\\\", \\\"ET\\\", \\\"SVR\\\", \\\"KNN\\\", \\\"DT\\\",\\n]\\n\\nMODEL_DISPLAY = {\\n    \\\"GBDT\\\": \\\"GBDT\\\",\\n    \\\"XGB\\\": \\\"XGB\\\",\\n    \\\"LightGBM\\\": \\\"LGB\\\",\\n    \\\"CatBoost\\\": \\\"CATB\\\",\\n    \\\"RF\\\": \\\"RF\\\",\\n    \\\"ET\\\": \\\"ET\\\",\\n    \\\"SVR\\\": \\\"SVR\\\",\\n    \\\"KNN\\\": \\\"KNN\\\",\\n    \\\"DT\\\": \\\"DT\\\",\\n}\\n\\nGAS_CONFIGS = {\\n    \\\"N2O\\\": {\\n        \\\"label\\\": r\\\"N$_2$O\\\",\\n        \\\"target_key\\\": \\\"N2O\\\",\\n        \\\"unit\\\": r\\\"kg N$_2$O ha$^{-1}$\\\",\\n    },\\n    \\\"CO2\\\": {\\n        \\\"label\\\": r\\\"CO$_2$\\\",\\n        \\\"target_key\\\": \\\"CO2\\\",\\n        \\\"unit\\\": r\\\"kg CO$_2$ ha$^{-1}$\\\",\\n    },\\n    \\\"CH4\\\": {\\n        \\\"label\\\": r\\\"CH$_4$\\\",\\n        \\\"target_key\\\": \\\"CH4\\\",\\n        \\\"unit\\\": r\\\"kg CH$_4$ ha$^{-1}$\\\",\\n    },\\n}\\n\\nFEATURE_KEYS = [\\n    \\\"SR\\\", \\\"BS\\\", \\\"BC\\\", \\\"N\\\", \\\"P\\\", \\\"K\\\",\\n    \\\"pH\\\", \\\"SOM\\\", \\\"AN\\\", \\\"AP\\\", \\\"AK\\\", \\\"MAT\\\", \\\"MAP\\\",\\n]\\n\\n\\n# ============================================================\\n# 2. 数据读取与列名识别\\n# ============================================================\\n\\nCOLUMN_ALIASES = {\\n    \\\"SR\\\": [\\\"SR\\\", \\\"Straw return\\\", \\\"Straw returning\\\"],\\n    \\\"BS\\\": [\\\"BS\\\", \\\"Biogas slurry\\\", \\\"Biogas slurry application\\\"],\\n    \\\"BC\\\": [\\\"BC\\\", \\\"Biochar\\\", \\\"Biochar application\\\"],\\n    \\\"N\\\": [\\\"N\\\", \\\"Nitrogen (N) Application Rate\\\", \\\"Nitrogen application rate\\\", \\\"N application rate\\\"],\\n    \\\"P\\\": [\\\"P\\\", \\\"Phosphorus (P) Application Rate\\\", \\\"Phosphorus application rate\\\", \\\"P application rate\\\"],\\n    \\\"K\\\": [\\\"K\\\", \\\"Potassium (K) application rate\\\", \\\"Potassium application rate\\\", \\\"K application rate\\\"],\\n    \\\"pH\\\": [\\\"pH\\\", \\\"PH\\\", \\\"Soil pH\\\"],\\n    \\\"SOM\\\": [\\\"SOM\\\", \\\"SOM（g/kg）\\\", \\\"SOM(g/kg)\\\", \\\"Soil organic matter\\\"],\\n    \\\"AN\\\": [\\\"AN\\\", \\\"AN（mg/kg）\\\", \\\"AN(mg/kg)\\\", \\\"Available nitrogen\\\"],\\n    \\\"AP\\\": [\\\"AP\\\", \\\"AP（mg/kg）\\\", \\\"AP(mg/kg)\\\", \\\"Available phosphorus\\\"],\\n    \\\"AK\\\": [\\\"AK\\\", \\\"AK（mg/kg）\\\", \\\"AK(mg/kg)\\\", \\\"Available potassium\\\"],\\n    \\\"MAT\\\": [\\\"MAT\\\", \\\"MAT（℃）\\\", \\\"MAT(℃)\\\", \\\"MAT()\\\", \\\"Mean annual temperature\\\"],\\n    \\\"MAP\\\": [\\\"MAP\\\", \\\"MAP（mm ）\\\", \\\"MAP（mm）\\\", \\\"MAP(mm )\\\", \\\"MAP(mm)\\\", \\\"Mean annual precipitation\\\"],\\n    \\\"N2O\\\": [\\n        \\\"N2O\\\", \\\"N2O累计排放量（kg/hm2）\\\", \\\"N₂O累计排放量（kg/hm2）\\\",\\n        \\\"Cumulative N2O emissions\\\", \\\"Cumulative N₂O emissions\\\",\\n    ],\\n    \\\"CO2\\\": [\\n        \\\"CO2\\\", \\\"CO2累计排放量（kg/hm2）\\\", \\\"CO₂累计排放量（kg/hm2）\\\",\\n        \\\"Cumulative CO2 emissions\\\", \\\"Cumulative CO₂ emissions\\\",\\n    ],\\n    \\\"CH4\\\": [\\n        \\\"CH4\\\", \\\"CH4累计排放量（kg/hm2）\\\", \\\"CH₄累计排放量（kg/hm2）\\\",\\n        \\\"Cumulative CH4 emissions\\\", \\\"Cumulative CH₄ emissions\\\",\\n    ],\\n}\\n\\n\\ndef normalize_column_name(name):\\n    text = str(name).strip().lower()\\n    text = text.replace(\\\"（\\\", \\\"(\\\").replace(\\\"）\\\", \\\")\\\")\\n    text = text.replace(\\\"₂\\\", \\\"2\\\").replace(\\\"₄\\\", \\\"4\\\")\\n    text = text.replace(\\\"℃\\\", \\\"c\\\")\\n    text = re.sub(r\\\"[\\\\s_\\\\-]+\\\", \\\"\\\", text)\\n    return text\\n\\n\\ndef resolve_columns(raw_columns):\\n    normalized_to_original = {\\n        normalize_column_name(column): column\\n        for column in raw_columns\\n    }\\n\\n    resolved = {}\\n    unresolved = []\\n\\n    for standard_name, aliases in COLUMN_ALIASES.items():\\n        matched = None\\n        for alias in [standard_name] + list(aliases):\\n            key = normalize_column_name(alias)\\n            if key in normalized_to_original:\\n                matched = normalized_to_original[key]\\n                break\\n\\n        if matched is None:\\n            unresolved.append(standard_name)\\n        else:\\n            resolved[standard_name] = matched\\n\\n    return resolved, unresolved\\n\\n\\ndef find_data_path(candidates):\\n    for candidate in candidates:\\n        if candidate and os.path.exists(candidate):\\n            return Path(candidate).resolve()\\n\\n    raise FileNotFoundError(\\n        \\\"未找到数据文件。请修改 DATA_CANDIDATES。\\\\n当前尝试路径：\\\\n\\\"\\n        + \\\"\\\\n\\\".join(str(path) for path in candidates)\\n    )\\n\\n\\ndef load_dataset(file_path, sheet_name=None, preferred_header=0):\\n    headers_to_try = []\\n    for header in [preferred_header, 0, 1]:\\n        if header not in headers_to_try:\\n            headers_to_try.append(header)\\n\\n    errors = []\\n\\n    for header in headers_to_try:\\n        try:\\n            raw = pd.read_excel(\\n                file_path,\\n                sheet_name=sheet_name if sheet_name is not None else 0,\\n                header=header,\\n                engine=\\\"openpyxl\\\",\\n            )\\n\\n            resolved, unresolved = resolve_columns(raw.columns)\\n\\n            if not unresolved:\\n                selected = pd.DataFrame(index=raw.index)\\n                for standard_name in FEATURE_KEYS + [\\\"N2O\\\", \\\"CO2\\\", \\\"CH4\\\"]:\\n                    selected[standard_name] = pd.to_numeric(\\n                        raw[resolved[standard_name]],\\n                        errors=\\\"coerce\\\",\\n                    )\\n                return selected, raw, resolved, header\\n\\n            errors.append(\\n                f\\\"header={header} 未识别：{', '.join(unresolved)}\\\\n\\\"\\n                f\\\"读取列名：{', '.join(str(c) for c in raw.columns)}\\\"\\n            )\\n        except Exception as exc:\\n            errors.append(f\\\"header={header} 读取失败：{exc}\\\")\\n\\n    raise KeyError(\\n        \\\"无法识别完整的13个输入变量和3个目标变量。\\\\n\\\\n\\\"\\n        + \\\"\\\\n\\\".join(errors)\\n    )\\n\\n\\n# ============================================================\\n# 3. 模型与搜索空间\\n# ============================================================\\n\\n\\ndef build_model_specs():\\n    return {\\n        \\\"GBDT\\\": {\\n            \\\"estimator\\\": GradientBoostingRegressor(random_state=GLOBAL_RANDOM_STATE),\\n            \\\"search_space\\\": {\\n                \\\"model__n_estimators\\\": Integer(100, 500),\\n                \\\"model__learning_rate\\\": Real(0.01, 0.30, prior=\\\"log-uniform\\\"),\\n                \\\"model__max_depth\\\": Integer(2, 6),\\n                \\\"model__subsample\\\": Real(0.60, 1.00),\\n            },\\n        },\\n        \\\"XGB\\\": {\\n            \\\"estimator\\\": XGBRegressor(\\n                random_state=GLOBAL_RANDOM_STATE,\\n                n_jobs=1,\\n                objective=\\\"reg:squarederror\\\",\\n                verbosity=0,\\n            ),\\n            \\\"search_space\\\": {\\n                \\\"model__n_estimators\\\": Integer(100, 500),\\n                \\\"model__max_depth\\\": Integer(3, 10),\\n                \\\"model__learning_rate\\\": Real(0.01, 0.30, prior=\\\"log-uniform\\\"),\\n                \\\"model__subsample\\\": Real(0.60, 1.00),\\n                \\\"model__colsample_bytree\\\": Real(0.60, 1.00),\\n            },\\n        },\\n        \\\"LightGBM\\\": {\\n            \\\"estimator\\\": LGBMRegressor(\\n                random_state=GLOBAL_RANDOM_STATE,\\n                n_jobs=1,\\n                verbosity=-1,\\n            ),\\n            \\\"search_space\\\": {\\n                \\\"model__n_estimators\\\": Integer(100, 500),\\n                \\\"model__num_leaves\\\": Integer(20, 80),\\n                \\\"model__max_depth\\\": Integer(3, 12),\\n                \\\"model__learning_rate\\\": Real(0.01, 0.30, prior=\\\"log-uniform\\\"),\\n                \\\"model__subsample\\\": Real(0.60, 1.00),\\n                \\\"model__colsample_bytree\\\": Real(0.60, 1.00),\\n            },\\n        },\\n        \\\"CatBoost\\\": {\\n            \\\"estimator\\\": CatBoostRegressor(\\n                random_state=GLOBAL_RANDOM_STATE,\\n                verbose=0,\\n                allow_writing_files=False,\\n                thread_count=1,\\n            ),\\n            \\\"search_space\\\": {\\n                \\\"model__depth\\\": Integer(4, 10),\\n                \\\"model__iterations\\\": Integer(100, 500),\\n                \\\"model__learning_rate\\\": Real(0.01, 0.30, prior=\\\"log-uniform\\\"),\\n            },\\n        },\\n        \\\"RF\\\": {\\n            \\\"estimator\\\": RandomForestRegressor(\\n                random_state=GLOBAL_RANDOM_STATE,\\n                n_jobs=1,\\n            ),\\n            \\\"search_space\\\": {\\n                \\\"model__n_estimators\\\": Integer(100, 500),\\n                \\\"model__max_depth\\\": Integer(3, 20),\\n                \\\"model__min_samples_split\\\": Integer(2, 10),\\n            },\\n        },\\n        \\\"ET\\\": {\\n            \\\"estimator\\\": ExtraTreesRegressor(\\n                random_state=GLOBAL_RANDOM_STATE,\\n                n_jobs=1,\\n            ),\\n            \\\"search_space\\\": {\\n                \\\"model__n_estimators\\\": Integer(50, 300),\\n                \\\"model__max_depth\\\": Integer(2, 20),\\n                \\\"model__min_samples_split\\\": Integer(2, 10),\\n            },\\n        },\\n        \\\"SVR\\\": {\\n            \\\"estimator\\\": SVR(kernel=\\\"rbf\\\"),\\n            \\\"search_space\\\": {\\n                \\\"model__C\\\": Real(1e-1, 1e3, prior=\\\"log-uniform\\\"),\\n                \\\"model__gamma\\\": Real(1e-4, 1e-1, prior=\\\"log-uniform\\\"),\\n                \\\"model__epsilon\\\": Real(1e-3, 1.0, prior=\\\"log-uniform\\\"),\\n            },\\n        },\\n        \\\"KNN\\\": {\\n            \\\"estimator\\\": KNeighborsRegressor(),\\n            \\\"search_space\\\": {\\n                \\\"model__n_neighbors\\\": Integer(3, 25),\\n                \\\"model__weights\\\": Categorical([\\\"uniform\\\", \\\"distance\\\"]),\\n                \\\"model__p\\\": Integer(1, 2),\\n            },\\n        },\\n        \\\"DT\\\": {\\n            \\\"estimator\\\": DecisionTreeRegressor(random_state=GLOBAL_RANDOM_STATE),\\n            \\\"search_space\\\": {\\n                \\\"model__max_depth\\\": Integer(2, 20),\\n                \\\"model__min_samples_split\\\": Integer(2, 10),\\n                \\\"model__min_samples_leaf\\\": Integer(1, 10),\\n            },\\n        },\\n    }\\n\\n\\ndef make_pipeline(estimator, model_params=None):\\n    pipeline = Pipeline(\\n        steps=[\\n            (\\\"imputer\\\", KNNImputer(n_neighbors=KNN_IMPUTER_NEIGHBORS)),\\n            (\\\"scaler\\\", StandardScaler()),\\n            (\\\"model\\\", estimator),\\n        ]\\n    )\\n\\n    if model_params:\\n        pipeline.set_params(\\n            **{f\\\"model__{key}\\\": value for key, value in model_params.items()}\\n        )\\n\\n    return pipeline\\n\\n\\ndef strip_pipeline_prefix(params):\\n    return {\\n        key.replace(\\\"model__\\\", \\\"\\\"): value\\n        for key, value in params.items()\\n    }\\n\\n\\n# ============================================================\\n# 4. 参数读取或一次性贝叶斯优化\\n# ============================================================\\n\\n\\ndef params_json_path(previous_result_dir, gas_key):\\n    return Path(previous_result_dir) / gas_key / f\\\"{gas_key}_best_params.json\\\"\\n\\n\\ndef load_existing_params(previous_result_dir, gas_key):\\n    file_path = params_json_path(previous_result_dir, gas_key)\\n    if not file_path.exists():\\n        return None\\n\\n    with open(file_path, \\\"r\\\", encoding=\\\"utf-8\\\") as file:\\n        raw = json.load(file)\\n\\n    if not all(model_name in raw for model_name in MODEL_ORDER):\\n        return None\\n\\n    return raw\\n\\n\\ndef tune_models_once(data, gas_key, previous_result_dir):\\n    config = GAS_CONFIGS[gas_key]\\n    gas_data = data[FEATURE_KEYS + [config[\\\"target_key\\\"]]].dropna(\\n        subset=[config[\\\"target_key\\\"]]\\n    )\\n\\n    X = gas_data[FEATURE_KEYS]\\n    y = gas_data[config[\\\"target_key\\\"]]\\n\\n    X_train, _, y_train, _ = train_test_split(\\n        X,\\n        y,\\n        test_size=TEST_SIZE,\\n        random_state=DISPLAY_SPLIT_SEEDS[gas_key],\\n    )\\n\\n    cv = KFold(\\n        n_splits=CV_FOLDS,\\n        shuffle=True,\\n        random_state=GLOBAL_RANDOM_STATE,\\n    )\\n\\n    specs = build_model_specs()\\n    best_params = {}\\n\\n    print(f\\\"\\\\n[{gas_key}] 未找到完整旧参数，开始一次性贝叶斯优化……\\\")\\n\\n    for model_name in MODEL_ORDER:\\n        print(f\\\"  正在优化 {model_name} …\\\")\\n        pipeline = make_pipeline(clone(specs[model_name][\\\"estimator\\\"]))\\n\\n        optimizer = BayesSearchCV(\\n            estimator=pipeline,\\n            search_spaces=specs[model_name][\\\"search_space\\\"],\\n            n_iter=BAYES_N_ITER,\\n            cv=cv,\\n            scoring=\\\"r2\\\",\\n            n_jobs=N_JOBS,\\n            random_state=GLOBAL_RANDOM_STATE,\\n            refit=True,\\n            verbose=0,\\n            error_score=\\\"raise\\\",\\n        )\\n        optimizer.fit(X_train, y_train)\\n        best_params[model_name] = strip_pipeline_prefix(optimizer.best_params_)\\n        print(f\\\"    CV R²={optimizer.best_score_:.4f}; {best_params[model_name]}\\\")\\n\\n        del optimizer, pipeline\\n        gc.collect()\\n\\n    output_path = params_json_path(previous_result_dir, gas_key)\\n    output_path.parent.mkdir(parents=True, exist_ok=True)\\n    with open(output_path, \\\"w\\\", encoding=\\\"utf-8\\\") as file:\\n        json.dump(best_params, file, ensure_ascii=False, indent=2, default=str)\\n\\n    print(f\\\"[{gas_key}] 参数已保存：{output_path}\\\")\\n    return best_params\\n\\n\\ndef get_best_params_for_gas(data, gas_key, previous_result_dir):\\n    params = load_existing_params(previous_result_dir, gas_key)\\n    if params is not None:\\n        print(f\\\"[{gas_key}] 已读取旧参数：{params_json_path(previous_result_dir, gas_key)}\\\")\\n        return params\\n\\n    if not TUNE_IF_PARAMS_MISSING:\\n        raise FileNotFoundError(\\n            f\\\"没有找到 {gas_key} 的完整参数文件：\\\\n\\\"\\n            f\\\"{params_json_path(previous_result_dir, gas_key)}\\\"\\n        )\\n\\n    return tune_models_once(data, gas_key, previous_result_dir)\\n\\n\\n# ============================================================\\n# 5. 多次外层随机划分\\n# ============================================================\\n\\n\\ndef metric_dict(y_true, y_pred):\\n    return {\\n        \\\"Test_R2\\\": r2_score(y_true, y_pred),\\n        \\\"Test_RMSE\\\": np.sqrt(mean_squared_error(y_true, y_pred)),\\n        \\\"Test_MAE\\\": mean_absolute_error(y_true, y_pred),\\n    }\\n\\n\\ndef checkpoint_paths(output_dir, gas_key):\\n    gas_dir = Path(output_dir) / gas_key\\n    gas_dir.mkdir(parents=True, exist_ok=True)\\n    return (\\n        gas_dir / f\\\"{gas_key}_repeat_metrics_checkpoint.csv\\\",\\n        gas_dir / f\\\"{gas_key}_repeat_predictions_checkpoint.csv\\\",\\n    )\\n\\n\\ndef read_checkpoint(path):\\n    if RESUME_FROM_CHECKPOINT and path.exists():\\n        return pd.read_csv(path)\\n    return pd.DataFrame()\\n\\n\\ndef run_repeated_outer_splits(data, gas_key, best_params, output_dir):\\n    config = GAS_CONFIGS[gas_key]\\n    target = config[\\\"target_key\\\"]\\n\\n    gas_data = data[FEATURE_KEYS + [target]].dropna(subset=[target]).copy()\\n    X = gas_data[FEATURE_KEYS]\\n    y = gas_data[target]\\n\\n    metrics_path, predictions_path = checkpoint_paths(output_dir, gas_key)\\n    existing_metrics = read_checkpoint(metrics_path)\\n    existing_predictions = read_checkpoint(predictions_path)\\n\\n    completed = set()\\n    if not existing_metrics.empty:\\n        completed = set(\\n            zip(\\n                existing_metrics[\\\"Repeat_ID\\\"].astype(int),\\n                existing_metrics[\\\"Model\\\"].astype(str),\\n            )\\n        )\\n\\n    metric_rows = existing_metrics.to_dict(\\\"records\\\") if not existing_metrics.empty else []\\n    prediction_rows = existing_predictions.to_dict(\\\"records\\\") if not existing_predictions.empty else []\\n\\n    specs = build_model_specs()\\n\\n    print(\\\"\\\\n\\\" + \\\"=\\\" * 80)\\n    print(\\n        f\\\"{gas_key}: repeated holdout, n={len(gas_data)}, repeats={N_REPEATS}, \\\"\\n        f\\\"test_size={TEST_SIZE}\\\"\\n    )\\n    print(\\\"=\\\" * 80)\\n\\n    for repeat_id in range(1, N_REPEATS + 1):\\n        split_seed = OUTER_SEED_START + repeat_id\\n\\n        X_train, X_test, y_train, y_test = train_test_split(\\n            X,\\n            y,\\n            test_size=TEST_SIZE,\\n            random_state=split_seed,\\n        )\\n\\n        print(f\\\"[{gas_key}] Repeat {repeat_id:02d}/{N_REPEATS}, seed={split_seed}\\\")\\n\\n        for model_name in MODEL_ORDER:\\n            if (repeat_id, model_name) in completed:\\n                print(f\\\"  {model_name}: 已完成，跳过\\\")\\n                continue\\n\\n            start = time.time()\\n\\n            pipeline = make_pipeline(\\n                clone(specs[model_name][\\\"estimator\\\"]),\\n                model_params=best_params[model_name],\\n            )\\n\\n            pipeline.fit(X_train, y_train)\\n            y_test_pred = pipeline.predict(X_test)\\n            scores = metric_dict(y_test, y_test_pred)\\n\\n            metric_rows.append(\\n                {\\n                    \\\"Gas\\\": gas_key,\\n                    \\\"Repeat_ID\\\": repeat_id,\\n                    \\\"Split_seed\\\": split_seed,\\n                    \\\"Model\\\": model_name,\\n                    \\\"n_total\\\": len(gas_data),\\n                    \\\"n_train\\\": len(X_train),\\n                    \\\"n_test\\\": len(X_test),\\n                    **scores,\\n                    \\\"Fit_seconds\\\": time.time() - start,\\n                }\\n            )\\n\\n            for sample_index, observed, predicted in zip(\\n                X_test.index,\\n                y_test.to_numpy(dtype=float),\\n                np.asarray(y_test_pred, dtype=float),\\n            ):\\n                prediction_rows.append(\\n                    {\\n                        \\\"Gas\\\": gas_key,\\n                        \\\"Repeat_ID\\\": repeat_id,\\n                        \\\"Split_seed\\\": split_seed,\\n                        \\\"Model\\\": model_name,\\n                        \\\"Sample_index\\\": sample_index,\\n                        \\\"Observed\\\": observed,\\n                        \\\"Predicted\\\": predicted,\\n                        \\\"Absolute_error\\\": abs(observed - predicted),\\n                    }\\n                )\\n\\n            print(\\n                f\\\"  {model_name:<8s} R²={scores['Test_R2']:.4f}, \\\"\\n                f\\\"RMSE={scores['Test_RMSE']:.4f}, MAE={scores['Test_MAE']:.4f}\\\"\\n            )\\n\\n            # 每个模型完成后立即保存，防止内核中断导致结果丢失\\n            pd.DataFrame(metric_rows).to_csv(metrics_path, index=False, encoding=\\\"utf-8-sig\\\")\\n            pd.DataFrame(prediction_rows).to_csv(predictions_path, index=False, encoding=\\\"utf-8-sig\\\")\\n\\n            del pipeline, y_test_pred\\n            gc.collect()\\n\\n    metrics_df = pd.DataFrame(metric_rows)\\n    predictions_df = pd.DataFrame(prediction_rows)\\n\\n    # 去重，便于中断后续跑\\n    metrics_df = metrics_df.drop_duplicates(\\n        subset=[\\\"Gas\\\", \\\"Repeat_ID\\\", \\\"Model\\\"],\\n        keep=\\\"last\\\",\\n    ).sort_values([\\\"Repeat_ID\\\", \\\"Model\\\"]).reset_index(drop=True)\\n\\n    predictions_df = predictions_df.drop_duplicates(\\n        subset=[\\\"Gas\\\", \\\"Repeat_ID\\\", \\\"Model\\\", \\\"Sample_index\\\"],\\n        keep=\\\"last\\\",\\n    ).sort_values([\\\"Repeat_ID\\\", \\\"Model\\\", \\\"Sample_index\\\"]).reset_index(drop=True)\\n\\n    metrics_df.to_csv(metrics_path, index=False, encoding=\\\"utf-8-sig\\\")\\n    predictions_df.to_csv(predictions_path, index=False, encoding=\\\"utf-8-sig\\\")\\n\\n    return metrics_df, predictions_df, gas_data\\n\\n\\n# ============================================================\\n# 6. 重复划分汇总与最优模型选择\\n# ============================================================\\n\\n\\ndef summarize_repeated_metrics(metrics_df):\\n    summary = (\\n        metrics_df.groupby([\\\"Gas\\\", \\\"Model\\\"], as_index=False)\\n        .agg(\\n            Repeats=(\\\"Repeat_ID\\\", \\\"nunique\\\"),\\n            R2_mean=(\\\"Test_R2\\\", \\\"mean\\\"),\\n            R2_median=(\\\"Test_R2\\\", \\\"median\\\"),\\n            R2_std=(\\\"Test_R2\\\", \\\"std\\\"),\\n            R2_min=(\\\"Test_R2\\\", \\\"min\\\"),\\n            R2_max=(\\\"Test_R2\\\", \\\"max\\\"),\\n            RMSE_mean=(\\\"Test_RMSE\\\", \\\"mean\\\"),\\n            RMSE_median=(\\\"Test_RMSE\\\", \\\"median\\\"),\\n            RMSE_std=(\\\"Test_RMSE\\\", \\\"std\\\"),\\n            MAE_mean=(\\\"Test_MAE\\\", \\\"mean\\\"),\\n            MAE_median=(\\\"Test_MAE\\\", \\\"median\\\"),\\n            MAE_std=(\\\"Test_MAE\\\", \\\"std\\\"),\\n        )\\n    )\\n    return summary\\n\\n\\ndef select_best_from_repeats(summary_df, gas_key):\\n    gas_summary = summary_df.loc[summary_df[\\\"Gas\\\"] == gas_key].copy()\\n\\n    if SELECTION_STATISTIC == \\\"median\\\":\\n        ordered = gas_summary.sort_values(\\n            by=[\\\"R2_median\\\", \\\"RMSE_median\\\", \\\"MAE_median\\\", \\\"R2_mean\\\"],\\n            ascending=[False, True, True, False],\\n        )\\n    elif SELECTION_STATISTIC == \\\"mean\\\":\\n        ordered = gas_summary.sort_values(\\n            by=[\\\"R2_mean\\\", \\\"RMSE_mean\\\", \\\"MAE_mean\\\", \\\"R2_median\\\"],\\n            ascending=[False, True, True, False],\\n        )\\n    else:\\n        raise ValueError(\\\"SELECTION_STATISTIC只能为'median'或'mean'。\\\")\\n\\n    return ordered.iloc[0][\\\"Model\\\"], ordered.reset_index(drop=True)\\n\\n\\n# ============================================================\\n# 7. 固定展示划分：用于(e)(f)\\n# ============================================================\\n\\n\\ndef fit_display_split(gas_data, gas_key, best_model_name, best_params):\\n    config = GAS_CONFIGS[gas_key]\\n    target = config[\\\"target_key\\\"]\\n\\n    X = gas_data[FEATURE_KEYS]\\n    y = gas_data[target]\\n\\n    X_train, X_test, y_train, y_test = train_test_split(\\n        X,\\n        y,\\n        test_size=TEST_SIZE,\\n        random_state=DISPLAY_SPLIT_SEEDS[gas_key],\\n    )\\n\\n    specs = build_model_specs()\\n    pipeline = make_pipeline(\\n        clone(specs[best_model_name][\\\"estimator\\\"]),\\n        model_params=best_params[best_model_name],\\n    )\\n    pipeline.fit(X_train, y_train)\\n\\n    return {\\n        \\\"pipeline\\\": pipeline,\\n        \\\"train_true\\\": y_train.to_numpy(dtype=float),\\n        \\\"train_pred\\\": np.asarray(pipeline.predict(X_train), dtype=float),\\n        \\\"test_true\\\": y_test.to_numpy(dtype=float),\\n        \\\"test_pred\\\": np.asarray(pipeline.predict(X_test), dtype=float),\\n        \\\"display_seed\\\": DISPLAY_SPLIT_SEEDS[gas_key],\\n    }\\n\\n\\n# ============================================================\\n# 8. 严格参考格式六联图\\n# ============================================================\\n\\n\\ndef add_panel_label(ax, label):\\n    ax.text(\\n        -0.13,\\n        1.06,\\n        label,\\n        transform=ax.transAxes,\\n        color=\\\"#C00000\\\",\\n        fontsize=11,\\n        fontweight=\\\"bold\\\",\\n        va=\\\"top\\\",\\n        ha=\\\"left\\\",\\n    )\\n\\n\\ndef add_model_separators(ax):\\n    for x in np.arange(1.5, len(MODEL_ORDER) + 0.5, 1.0):\\n        ax.axvline(\\n            x,\\n            color=\\\"#9A9A9A\\\",\\n            linestyle=\\\"--\\\",\\n            linewidth=0.55,\\n            alpha=0.60,\\n            zorder=0,\\n        )\\n\\n\\ndef format_model_axis(ax):\\n    positions = np.arange(1, len(MODEL_ORDER) + 1)\\n    ax.set_xticks(positions)\\n    ax.set_xticklabels(\\n        [MODEL_DISPLAY[name] for name in MODEL_ORDER],\\n        fontsize=7.8,\\n    )\\n    ax.tick_params(axis=\\\"x\\\", length=2.5, pad=2)\\n    ax.tick_params(axis=\\\"y\\\", labelsize=8, length=3)\\n    add_model_separators(ax)\\n    for spine in ax.spines.values():\\n        spine.set_linewidth(0.8)\\n        spine.set_visible(True)\\n\\n\\ndef draw_metric_boxplot(ax, gas_metrics, metric, title, ylabel, best_model_name, y_limit=None):\\n    rng = np.random.default_rng(42)\\n    positions = np.arange(1, len(MODEL_ORDER) + 1)\\n\\n    data = [\\n        gas_metrics.loc[gas_metrics[\\\"Model\\\"] == model_name, metric]\\n        .dropna()\\n        .to_numpy(dtype=float)\\n        for model_name in MODEL_ORDER\\n    ]\\n\\n    box = ax.boxplot(\\n        data,\\n        positions=positions,\\n        widths=0.50,\\n        patch_artist=True,\\n        showfliers=False,\\n        medianprops={\\\"color\\\": \\\"black\\\", \\\"linewidth\\\": 0.9},\\n        whiskerprops={\\\"color\\\": \\\"#707070\\\", \\\"linewidth\\\": 0.7},\\n        capprops={\\\"color\\\": \\\"#707070\\\", \\\"linewidth\\\": 0.7},\\n        boxprops={\\\"edgecolor\\\": \\\"#404040\\\", \\\"linewidth\\\": 0.7},\\n    )\\n\\n    for patch, model_name in zip(box[\\\"boxes\\\"], MODEL_ORDER):\\n        patch.set_facecolor(BOX_FACE_COLOR)\\n        patch.set_alpha(0.92)\\n        if model_name == best_model_name:\\n            patch.set_linewidth(1.4)\\n            patch.set_edgecolor(\\\"black\\\")\\n\\n    means = []\\n    for x, values in zip(positions, data):\\n        means.append(np.nanmean(values))\\n        jitter = rng.uniform(-0.105, 0.105, len(values))\\n        ax.scatter(\\n            np.full(len(values), x) + jitter,\\n            values,\\n            s=8,\\n            facecolors=\\\"white\\\",\\n            edgecolors=\\\"#777777\\\",\\n            linewidths=0.45,\\n            alpha=0.82,\\n            zorder=3,\\n        )\\n\\n    ax.scatter(\\n        positions,\\n        means,\\n        s=16,\\n        color=\\\"black\\\",\\n        edgecolors=\\\"none\\\",\\n        zorder=5,\\n    )\\n\\n    ax.set_title(title, fontsize=10, fontweight=\\\"bold\\\", pad=5)\\n    ax.set_ylabel(ylabel, fontsize=8.5)\\n    format_model_axis(ax)\\n\\n    if metric == \\\"Test_R2\\\":\\n        ax.axhline(0, color=\\\"#808080\\\", linewidth=0.6, linestyle=\\\"-\\\")\\n\\n    if y_limit is not None:\\n        ax.set_ylim(*y_limit)\\n\\n\\ndef draw_absolute_error_panel(ax, gas_predictions, config, best_model_name):\\n    rng = np.random.default_rng(123)\\n    positions = np.arange(1, len(MODEL_ORDER) + 1)\\n\\n    data = [\\n        gas_predictions.loc[\\n            gas_predictions[\\\"Model\\\"] == model_name,\\n            \\\"Absolute_error\\\",\\n        ].dropna().to_numpy(dtype=float)\\n        for model_name in MODEL_ORDER\\n    ]\\n\\n    box = ax.boxplot(\\n        data,\\n        positions=positions,\\n        widths=0.50,\\n        patch_artist=True,\\n        showfliers=False,\\n        medianprops={\\\"color\\\": \\\"black\\\", \\\"linewidth\\\": 0.9},\\n        whiskerprops={\\\"color\\\": \\\"#707070\\\", \\\"linewidth\\\": 0.7},\\n        capprops={\\\"color\\\": \\\"#707070\\\", \\\"linewidth\\\": 0.7},\\n        boxprops={\\\"edgecolor\\\": \\\"#404040\\\", \\\"linewidth\\\": 0.7},\\n    )\\n\\n    for patch, model_name in zip(box[\\\"boxes\\\"], MODEL_ORDER):\\n        patch.set_facecolor(BOX_FACE_COLOR)\\n        patch.set_alpha(0.92)\\n        if model_name == best_model_name:\\n            patch.set_linewidth(1.4)\\n            patch.set_edgecolor(\\\"black\\\")\\n\\n    means = []\\n    for x, values in zip(positions, data):\\n        means.append(np.nanmean(values))\\n        jitter = rng.uniform(-0.11, 0.11, len(values))\\n        ax.scatter(\\n            np.full(len(values), x) + jitter,\\n            values,\\n            s=5,\\n            color=\\\"#D9D9D9\\\",\\n            edgecolors=\\\"none\\\",\\n            alpha=0.48,\\n            zorder=2,\\n            rasterized=True,\\n        )\\n\\n    ax.scatter(\\n        positions,\\n        means,\\n        s=18,\\n        color=\\\"black\\\",\\n        edgecolors=\\\"none\\\",\\n        zorder=5,\\n    )\\n\\n    ax.set_title(\\\"Testing Absolute Error\\\", fontsize=10, fontweight=\\\"bold\\\", pad=5)\\n    ax.set_ylabel(f\\\"Absolute error\\\\n({config['unit']})\\\", fontsize=8.5)\\n    ax.set_ylim(bottom=0)\\n    format_model_axis(ax)\\n\\n\\ndef common_fit_limits(*arrays):\\n    values = np.concatenate([np.asarray(array, dtype=float) for array in arrays])\\n    lower = min(0.0, float(np.nanmin(values)))\\n    upper = float(np.nanmax(values))\\n    span = upper - lower\\n    padding = 0.035 * span if span > 0 else 1.0\\n    return lower, upper + padding\\n\\n\\ndef add_linear_and_identity_lines(ax, observed, predicted, lower, upper):\\n    # 灰色虚线：1:1 line\\n    ax.plot(\\n        [lower, upper],\\n        [lower, upper],\\n        color=\\\"#9A9A9A\\\",\\n        linestyle=\\\"--\\\",\\n        linewidth=0.8,\\n        zorder=1,\\n    )\\n\\n    # 黑色实线：线性拟合\\n    if len(observed) >= 2 and np.nanstd(observed) > 0:\\n        slope, intercept = np.polyfit(observed, predicted, 1)\\n        x_line = np.linspace(lower, upper, 200)\\n        ax.plot(\\n            x_line,\\n            slope * x_line + intercept,\\n            color=\\\"black\\\",\\n            linestyle=\\\"-\\\",\\n            linewidth=0.9,\\n            zorder=2,\\n        )\\n\\n\\ndef style_fit_axis(ax, title, config, lower, upper):\\n    ax.set_xlim(lower, upper)\\n    ax.set_ylim(lower, upper)\\n    ax.set_aspect(\\\"equal\\\", adjustable=\\\"box\\\")\\n    ax.set_title(title, fontsize=10, fontweight=\\\"bold\\\", pad=5)\\n    ax.set_xlabel(\\n        f\\\"Observed cumulative emission\\\\n({config['unit']})\\\",\\n        fontsize=8.2,\\n        labelpad=2,\\n    )\\n    ax.set_ylabel(\\n        f\\\"Predicted cumulative emission\\\\n({config['unit']})\\\",\\n        fontsize=8.2,\\n        labelpad=2,\\n    )\\n    ax.tick_params(axis=\\\"both\\\", labelsize=7.8, length=3)\\n    for spine in ax.spines.values():\\n        spine.set_visible(True)\\n        spine.set_linewidth(0.8)\\n\\n\\ndef draw_train_test_fit(ax, display_result, model_name, config):\\n    train_true = display_result[\\\"train_true\\\"]\\n    train_pred = display_result[\\\"train_pred\\\"]\\n    test_true = display_result[\\\"test_true\\\"]\\n    test_pred = display_result[\\\"test_pred\\\"]\\n\\n    lower, upper = common_fit_limits(train_true, train_pred, test_true, test_pred)\\n\\n    ax.scatter(\\n        train_true,\\n        train_pred,\\n        s=18,\\n        color=TRAIN_COLOR,\\n        edgecolors=\\\"#4A4A4A\\\",\\n        linewidths=0.25,\\n        alpha=0.90,\\n        label=\\\"Train\\\",\\n        zorder=3,\\n    )\\n    ax.scatter(\\n        test_true,\\n        test_pred,\\n        s=20,\\n        color=TEST_COLOR,\\n        edgecolors=\\\"#4A4A4A\\\",\\n        linewidths=0.25,\\n        alpha=0.90,\\n        label=\\\"Test\\\",\\n        zorder=4,\\n    )\\n\\n    add_linear_and_identity_lines(\\n        ax,\\n        np.concatenate([train_true, test_true]),\\n        np.concatenate([train_pred, test_pred]),\\n        lower,\\n        upper,\\n    )\\n    style_fit_axis(ax, f\\\"{MODEL_DISPLAY[model_name]}: Training and Testing Sets\\\", config, lower, upper)\\n\\n    text = (\\n        \\\"Train:\\\\n\\\"\\n        rf\\\"$R^2$={r2_score(train_true, train_pred):.4f}\\\" \\\"\\\\n\\\"\\n        rf\\\"RMSE={np.sqrt(mean_squared_error(train_true, train_pred)):.4f}\\\" \\\"\\\\n\\\\n\\\"\\n        \\\"Test:\\\\n\\\"\\n        rf\\\"$R^2$={r2_score(test_true, test_pred):.4f}\\\" \\\"\\\\n\\\"\\n        rf\\\"RMSE={np.sqrt(mean_squared_error(test_true, test_pred)):.4f}\\\"\\n    )\\n    ax.text(\\n        0.055,\\n        0.955,\\n        text,\\n        transform=ax.transAxes,\\n        va=\\\"top\\\",\\n        ha=\\\"left\\\",\\n        fontsize=7.0,\\n        bbox=dict(\\n            boxstyle=\\\"square,pad=0.20\\\",\\n            facecolor=\\\"white\\\",\\n            edgecolor=\\\"#707070\\\",\\n            linewidth=0.65,\\n            alpha=0.95,\\n        ),\\n    )\\n\\n    legend = ax.legend(\\n        loc=\\\"lower right\\\",\\n        fontsize=7.0,\\n        frameon=True,\\n        fancybox=False,\\n        borderpad=0.25,\\n        handletextpad=0.35,\\n    )\\n    legend.get_frame().set_edgecolor(\\\"#707070\\\")\\n    legend.get_frame().set_linewidth(0.6)\\n    legend.get_frame().set_alpha(0.95)\\n\\n\\ndef draw_test_fit(ax, display_result, model_name, config):\\n    test_true = display_result[\\\"test_true\\\"]\\n    test_pred = display_result[\\\"test_pred\\\"]\\n\\n    lower, upper = common_fit_limits(test_true, test_pred)\\n\\n    ax.scatter(\\n        test_true,\\n        test_pred,\\n        s=20,\\n        color=TEST_COLOR,\\n        edgecolors=\\\"#4A4A4A\\\",\\n        linewidths=0.25,\\n        alpha=0.90,\\n        label=\\\"Test\\\",\\n        zorder=4,\\n    )\\n\\n    add_linear_and_identity_lines(ax, test_true, test_pred, lower, upper)\\n    style_fit_axis(ax, f\\\"{MODEL_DISPLAY[model_name]}: Testing Set\\\", config, lower, upper)\\n\\n    text = (\\n        \\\"Test:\\\\n\\\"\\n        rf\\\"$R^2$={r2_score(test_true, test_pred):.4f}\\\" \\\"\\\\n\\\"\\n        rf\\\"RMSE={np.sqrt(mean_squared_error(test_true, test_pred)):.4f}\\\"\\n    )\\n    ax.text(\\n        0.055,\\n        0.955,\\n        text,\\n        transform=ax.transAxes,\\n        va=\\\"top\\\",\\n        ha=\\\"left\\\",\\n        fontsize=7.0,\\n        bbox=dict(\\n            boxstyle=\\\"square,pad=0.20\\\",\\n            facecolor=\\\"white\\\",\\n            edgecolor=\\\"#707070\\\",\\n            linewidth=0.65,\\n            alpha=0.95,\\n        ),\\n    )\\n\\n    legend = ax.legend(\\n        loc=\\\"lower right\\\",\\n        fontsize=7.0,\\n        frameon=True,\\n        fancybox=False,\\n        borderpad=0.25,\\n        handletextpad=0.35,\\n    )\\n    legend.get_frame().set_edgecolor(\\\"#707070\\\")\\n    legend.get_frame().set_linewidth(0.6)\\n    legend.get_frame().set_alpha(0.95)\\n\\n\\ndef plot_exact_six_panel(\\n    gas_key,\\n    gas_metrics,\\n    gas_predictions,\\n    best_model_name,\\n    display_result,\\n    output_dir,\\n):\\n    config = GAS_CONFIGS[gas_key]\\n\\n    fig, axes = plt.subplots(\\n        2,\\n        3,\\n        figsize=(12.2, 7.0),\\n        dpi=120,\\n    )\\n    axes = axes.ravel()\\n\\n    # 动态R²范围，至少覆盖参考图的-0.4至1.05\\n    r2_min = float(gas_metrics[\\\"Test_R2\\\"].min())\\n    r2_lower = min(-0.40, np.floor((r2_min - 0.03) * 10) / 10)\\n\\n    draw_metric_boxplot(\\n        axes[0],\\n        gas_metrics,\\n        \\\"Test_R2\\\",\\n        r\\\"Testing R$^2$\\\",\\n        r\\\"R$^2$\\\",\\n        best_model_name,\\n        y_limit=(r2_lower, 1.05),\\n    )\\n    draw_metric_boxplot(\\n        axes[1],\\n        gas_metrics,\\n        \\\"Test_RMSE\\\",\\n        \\\"Testing RMSE\\\",\\n        f\\\"RMSE\\\\n({config['unit']})\\\",\\n        best_model_name,\\n        y_limit=(0, float(gas_metrics[\\\"Test_RMSE\\\"].max()) * 1.08),\\n    )\\n    draw_metric_boxplot(\\n        axes[2],\\n        gas_metrics,\\n        \\\"Test_MAE\\\",\\n        \\\"Testing MAE\\\",\\n        f\\\"MAE\\\\n({config['unit']})\\\",\\n        best_model_name,\\n        y_limit=(0, float(gas_metrics[\\\"Test_MAE\\\"].max()) * 1.08),\\n    )\\n    draw_absolute_error_panel(\\n        axes[3],\\n        gas_predictions,\\n        config,\\n        best_model_name,\\n    )\\n    draw_train_test_fit(\\n        axes[4],\\n        display_result,\\n        best_model_name,\\n        config,\\n    )\\n    draw_test_fit(\\n        axes[5],\\n        display_result,\\n        best_model_name,\\n        config,\\n    )\\n\\n    for ax, label in zip(axes, [\\\"(a)\\\", \\\"(b)\\\", \\\"(c)\\\", \\\"(d)\\\", \\\"(e)\\\", \\\"(f)\\\"]):\\n        add_panel_label(ax, label)\\n\\n    fig.subplots_adjust(\\n        left=0.075,\\n        right=0.985,\\n        bottom=0.095,\\n        top=0.965,\\n        wspace=0.34,\\n        hspace=0.34,\\n    )\\n\\n    gas_dir = Path(output_dir) / gas_key\\n    gas_dir.mkdir(parents=True, exist_ok=True)\\n    save_path = gas_dir / f\\\"{gas_key}_repeated_outer_split_6panel_exact.png\\\"\\n\\n    fig.savefig(\\n        save_path,\\n        dpi=SAVE_DPI,\\n        bbox_inches=\\\"tight\\\",\\n        facecolor=\\\"white\\\",\\n    )\\n\\n    if SHOW_FIGURES:\\n        plt.show()\\n    else:\\n        plt.close(fig)\\n\\n    del fig, axes\\n    gc.collect()\\n\\n    print(f\\\"[{gas_key}] 六联图已保存：{save_path}\\\")\\n    return save_path\\n\\n\\n# ============================================================\\n# 9. 结果保存\\n# ============================================================\\n\\n\\ndef save_all_results(\\n    all_metrics,\\n    all_predictions,\\n    summary_df,\\n    best_summary_df,\\n    output_dir,\\n):\\n    output_dir = Path(output_dir)\\n\\n    metrics_csv = output_dir / \\\"repeat_metrics_df.csv\\\"\\n    predictions_csv = output_dir / \\\"repeat_test_predictions_df.csv\\\"\\n\\n    all_metrics.to_csv(metrics_csv, index=False, encoding=\\\"utf-8-sig\\\")\\n    all_predictions.to_csv(predictions_csv, index=False, encoding=\\\"utf-8-sig\\\")\\n\\n    with pd.ExcelWriter(\\n        output_dir / \\\"Repeated_outer_split_results.xlsx\\\",\\n        engine=\\\"openpyxl\\\",\\n    ) as writer:\\n        all_metrics.to_excel(writer, sheet_name=\\\"repeat_metrics\\\", index=False)\\n        summary_df.to_excel(writer, sheet_name=\\\"model_summary\\\", index=False)\\n        best_summary_df.to_excel(writer, sheet_name=\\\"best_models\\\", index=False)\\n\\n        for gas_key in [\\\"N2O\\\", \\\"CO2\\\", \\\"CH4\\\"]:\\n            all_metrics.loc[all_metrics[\\\"Gas\\\"] == gas_key].to_excel(\\n                writer,\\n                sheet_name=f\\\"{gas_key}_metrics\\\",\\n                index=False,\\n            )\\n\\n    print(\\\"\\\\n重复划分结果已保存：\\\")\\n    print(metrics_csv)\\n    print(predictions_csv)\\n    print(output_dir / \\\"Repeated_outer_split_results.xlsx\\\")\\n\\n\\n# ============================================================\\n# 10. 主程序\\n# ============================================================\\n\\n\\ndef main():\\n    data_path = find_data_path(DATA_CANDIDATES)\\n\\n    previous_result_dir = (\\n        Path(PREVIOUS_RESULT_DIR)\\n        if PREVIOUS_RESULT_DIR is not None\\n        else data_path.parent / \\\"ML_SHAP_最优模型\\\"\\n    )\\n\\n    output_dir = (\\n        Path(SAVE_DIR)\\n        if SAVE_DIR is not None\\n        else data_path.parent / \\\"Repeated_outer_split_6panel\\\"\\n    )\\n    output_dir.mkdir(parents=True, exist_ok=True)\\n\\n    print(\\\"数据文件：\\\", data_path)\\n    print(\\\"旧参数目录：\\\", previous_result_dir)\\n    print(\\\"本次输出目录：\\\", output_dir)\\n    print(\\\"外层重复次数：\\\", N_REPEATS)\\n\\n    data, raw_data, resolved_columns, used_header = load_dataset(\\n        data_path,\\n        sheet_name=SHEET_NAME,\\n        preferred_header=PREFERRED_HEADER,\\n    )\\n\\n    print(f\\\"Excel header={used_header}; 原始记录数={len(raw_data)}\\\")\\n    print(\\\"识别列：\\\")\\n    for key in FEATURE_KEYS + [\\\"N2O\\\", \\\"CO2\\\", \\\"CH4\\\"]:\\n        print(f\\\"  {key:>4s} <- {resolved_columns[key]}\\\")\\n\\n    all_metrics_list = []\\n    all_predictions_list = []\\n    best_params_by_gas = {}\\n    gas_data_map = {}\\n\\n    # 先读取/获得参数，再进行重复划分\\n    for gas_key in [\\\"N2O\\\", \\\"CO2\\\", \\\"CH4\\\"]:\\n        best_params = get_best_params_for_gas(\\n            data,\\n            gas_key,\\n            previous_result_dir,\\n        )\\n        best_params_by_gas[gas_key] = best_params\\n\\n        metrics_df, predictions_df, gas_data = run_repeated_outer_splits(\\n            data,\\n            gas_key,\\n            best_params,\\n            output_dir,\\n        )\\n\\n        all_metrics_list.append(metrics_df)\\n        all_predictions_list.append(predictions_df)\\n        gas_data_map[gas_key] = gas_data\\n\\n    all_metrics = pd.concat(all_metrics_list, ignore_index=True)\\n    all_predictions = pd.concat(all_predictions_list, ignore_index=True)\\n\\n    summary_df = summarize_repeated_metrics(all_metrics)\\n\\n    best_rows = []\\n    selected_models = {}\\n\\n    for gas_key in [\\\"N2O\\\", \\\"CO2\\\", \\\"CH4\\\"]:\\n        best_model_name, ranking = select_best_from_repeats(summary_df, gas_key)\\n        selected_models[gas_key] = best_model_name\\n\\n        ranking.to_excel(\\n            output_dir / gas_key / f\\\"{gas_key}_repeated_model_ranking.xlsx\\\",\\n            index=False,\\n        )\\n\\n        best_row = ranking.iloc[0].to_dict()\\n        best_row[\\\"Best_model\\\"] = best_model_name\\n        best_rows.append(best_row)\\n\\n        print(\\\"\\\\n\\\" + \\\"-\\\" * 80)\\n        print(f\\\"{gas_key} 重复划分最优模型：{best_model_name}\\\")\\n        print(\\n            f\\\"Median R²={best_row['R2_median']:.4f}; \\\"\\n            f\\\"Median RMSE={best_row['RMSE_median']:.4f}; \\\"\\n            f\\\"Median MAE={best_row['MAE_median']:.4f}\\\"\\n        )\\n        print(\\\"-\\\" * 80)\\n\\n    best_summary_df = pd.DataFrame(best_rows)\\n\\n    save_all_results(\\n        all_metrics,\\n        all_predictions,\\n        summary_df,\\n        best_summary_df,\\n        output_dir,\\n    )\\n\\n    # 使用重复划分筛选出的最优模型绘制参考格式六联图\\n    for gas_key in [\\\"N2O\\\", \\\"CO2\\\", \\\"CH4\\\"]:\\n        best_model_name = selected_models[gas_key]\\n\\n        display_result = fit_display_split(\\n            gas_data_map[gas_key],\\n            gas_key,\\n            best_model_name,\\n            best_params_by_gas[gas_key],\\n        )\\n\\n        plot_exact_six_panel(\\n            gas_key=gas_key,\\n            gas_metrics=all_metrics.loc[all_metrics[\\\"Gas\\\"] == gas_key].copy(),\\n            gas_predictions=all_predictions.loc[all_predictions[\\\"Gas\\\"] == gas_key].copy(),\\n            best_model_name=best_model_name,\\n            display_result=display_result,\\n            output_dir=output_dir,\\n        )\\n\\n        del display_result\\n        gc.collect()\\n\\n    configuration = {\\n        \\\"data_path\\\": str(data_path),\\n        \\\"previous_result_dir\\\": str(previous_result_dir),\\n        \\\"output_dir\\\": str(output_dir),\\n        \\\"test_size\\\": TEST_SIZE,\\n        \\\"n_repeats\\\": N_REPEATS,\\n        \\\"outer_seed_start\\\": OUTER_SEED_START,\\n        \\\"display_split_seeds\\\": DISPLAY_SPLIT_SEEDS,\\n        \\\"selection_statistic\\\": SELECTION_STATISTIC,\\n        \\\"all_features_standardized\\\": True,\\n        \\\"knn_imputer_neighbors\\\": KNN_IMPUTER_NEIGHBORS,\\n        \\\"reused_or_once_tuned_hyperparameters\\\": True,\\n        \\\"selected_models\\\": selected_models,\\n    }\\n\\n    with open(\\n        output_dir / \\\"repeated_outer_split_configuration.json\\\",\\n        \\\"w\\\",\\n        encoding=\\\"utf-8\\\",\\n    ) as file:\\n        json.dump(configuration, file, ensure_ascii=False, indent=2)\\n\\n    print(\\\"\\\\n\\\" + \\\"=\\\" * 80)\\n    print(\\\"全部重复划分与六联图绘制完成。\\\")\\n    print(\\\"结果目录：\\\", output_dir)\\n    print(\\\"=\\\" * 80)\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\"},\"plot_metrics\":{\"filename\":\"GHG_repeated_outer_split_3panel_final_models.py\",\"source\":\"# -*- coding: utf-8 -*-\\n\\\"\\\"\\\"\\n直接读取已有重复划分结果，绘制三种气体的1×3三联图\\n====================================================\\n\\n功能说明\\n--------\\n1. 不重新划分训练集/测试集；\\n2. 不重新训练模型；\\n3. 不重新调参；\\n4. 直接读取之前保存的重复划分结果；\\n5. 按最终模型组合 N2O–ET、CO2–GBDT、CH4–ET 绘制三联图：\\n   (a) Testing R²\\n   (b) Testing RMSE\\n   (c) Testing MAE\\n\\n输出文件\\n--------\\n1. N2O_repeated_outer_split_3panel_final.png\\n2. CO2_repeated_outer_split_3panel_final.png\\n3. CH4_repeated_outer_split_3panel_final.png\\n\\\"\\\"\\\"\\n\\nimport gc\\nfrom pathlib import Path\\n\\nimport numpy as np\\nimport pandas as pd\\nimport matplotlib as mpl\\nimport matplotlib.pyplot as plt\\n\\n\\n# ============================================================\\n# 0. 用户设置\\n# ============================================================\\n\\n# 原重复划分结果目录\\nRESULT_DIR = Path(r\\\"E:\\\\温室气体模型\\\\7\\\\Repeated_outer_split_6panel\\\")\\n\\n# 三联图保存目录\\nSAVE_DIR = RESULT_DIR / \\\"Three_panel_plots\\\"\\n\\n# 图像分辨率\\nSAVE_DPI = 600\\n\\n# 是否显示图像\\nSHOW_FIGURES = True\\n\\n# 是否显示(a)(b)(c)中的空心散点\\nSHOW_METRIC_POINTS = True\\n\\n# 是否显示黑色均值点\\nSHOW_MEAN_POINTS = True\\n\\n# 最终确定的最优模型。\\n# 依据30次重复外层随机划分中R²、RMSE和MAE的综合表现：\\n# N2O：ET；CO2：GBDT；CH4：ET。\\n# 这里固定为最终论文模型，避免后续绘图因单一指标排序发生变化。\\nBEST_MODEL_OVERRIDE = {\\n    \\\"N2O\\\": \\\"ET\\\",\\n    \\\"CO2\\\": \\\"GBDT\\\",\\n    \\\"CH4\\\": \\\"ET\\\",\\n}\\n\\n\\n# ============================================================\\n# 1. 全局绘图设置\\n# ============================================================\\n\\nSAVE_DIR.mkdir(parents=True, exist_ok=True)\\n\\nmpl.rcParams[\\\"font.family\\\"] = \\\"Times New Roman\\\"\\nmpl.rcParams[\\\"font.size\\\"] = 10\\nmpl.rcParams[\\\"axes.unicode_minus\\\"] = False\\nmpl.rcParams[\\\"mathtext.fontset\\\"] = \\\"stix\\\"\\nmpl.rcParams[\\\"figure.dpi\\\"] = 120\\n\\nBOX_FACE_COLOR = \\\"#F28E63\\\"\\n\\nMODEL_ORDER = [\\n    \\\"GBDT\\\", \\\"XGB\\\", \\\"LightGBM\\\", \\\"CatBoost\\\",\\n    \\\"RF\\\", \\\"ET\\\", \\\"SVR\\\", \\\"KNN\\\", \\\"DT\\\",\\n]\\n\\nMODEL_DISPLAY = {\\n    \\\"GBDT\\\": \\\"GBDT\\\",\\n    \\\"XGB\\\": \\\"XGB\\\",\\n    \\\"LightGBM\\\": \\\"LGB\\\",\\n    \\\"CatBoost\\\": \\\"CATB\\\",\\n    \\\"RF\\\": \\\"RF\\\",\\n    \\\"ET\\\": \\\"ET\\\",\\n    \\\"SVR\\\": \\\"SVR\\\",\\n    \\\"KNN\\\": \\\"KNN\\\",\\n    \\\"DT\\\": \\\"DT\\\",\\n}\\n\\nGAS_CONFIGS = {\\n    \\\"N2O\\\": {\\n        \\\"label\\\": r\\\"N$_2$O\\\",\\n        \\\"unit\\\": r\\\"kg N$_2$O ha$^{-1}$\\\",\\n    },\\n    \\\"CO2\\\": {\\n        \\\"label\\\": r\\\"CO$_2$\\\",\\n        \\\"unit\\\": r\\\"kg CO$_2$ ha$^{-1}$\\\",\\n    },\\n    \\\"CH4\\\": {\\n        \\\"label\\\": r\\\"CH$_4$\\\",\\n        \\\"unit\\\": r\\\"kg CH$_4$ ha$^{-1}$\\\",\\n    },\\n}\\n\\n\\n# ============================================================\\n# 2. 读取已有结果\\n# ============================================================\\n\\ndef load_saved_metrics(result_dir):\\n    \\\"\\\"\\\"\\n    优先读取总结果CSV：\\n        repeat_metrics_df.csv\\n\\n    若不存在，则读取各气体checkpoint：\\n        N2O_repeat_metrics_checkpoint.csv\\n        CO2_repeat_metrics_checkpoint.csv\\n        CH4_repeat_metrics_checkpoint.csv\\n    \\\"\\\"\\\"\\n    result_dir = Path(result_dir)\\n\\n    metrics_file = result_dir / \\\"repeat_metrics_df.csv\\\"\\n\\n    if metrics_file.exists():\\n        print(\\\"读取最终汇总指标文件：\\\")\\n        print(\\\"  \\\", metrics_file)\\n        metrics_df = pd.read_csv(metrics_file)\\n        return metrics_df\\n\\n    print(\\\"未发现 repeat_metrics_df.csv，尝试读取各气体 checkpoint 文件。\\\")\\n\\n    metrics_list = []\\n\\n    for gas_key in [\\\"N2O\\\", \\\"CO2\\\", \\\"CH4\\\"]:\\n        gas_metrics_file = result_dir / gas_key / f\\\"{gas_key}_repeat_metrics_checkpoint.csv\\\"\\n\\n        if not gas_metrics_file.exists():\\n            raise FileNotFoundError(f\\\"未找到指标结果文件：\\\\n{gas_metrics_file}\\\")\\n\\n        metrics_list.append(pd.read_csv(gas_metrics_file))\\n\\n    metrics_df = pd.concat(metrics_list, ignore_index=True)\\n    return metrics_df\\n\\n\\ndef check_metric_columns(metrics_df):\\n    required_columns = {\\n        \\\"Gas\\\",\\n        \\\"Repeat_ID\\\",\\n        \\\"Model\\\",\\n        \\\"Test_R2\\\",\\n        \\\"Test_RMSE\\\",\\n        \\\"Test_MAE\\\",\\n    }\\n\\n    missing = required_columns - set(metrics_df.columns)\\n\\n    if missing:\\n        raise KeyError(\\n            \\\"指标文件缺少以下列：\\\\n\\\" + \\\", \\\".join(sorted(missing))\\n        )\\n\\n\\ndef clean_metrics_table(metrics_df):\\n    metrics_df = metrics_df.copy()\\n\\n    numeric_columns = [\\n        \\\"Repeat_ID\\\",\\n        \\\"Test_R2\\\",\\n        \\\"Test_RMSE\\\",\\n        \\\"Test_MAE\\\",\\n    ]\\n\\n    for col in numeric_columns:\\n        metrics_df[col] = pd.to_numeric(metrics_df[col], errors=\\\"coerce\\\")\\n\\n    metrics_df = metrics_df.dropna(\\n        subset=[\\n            \\\"Gas\\\",\\n            \\\"Model\\\",\\n            \\\"Repeat_ID\\\",\\n            \\\"Test_R2\\\",\\n            \\\"Test_RMSE\\\",\\n            \\\"Test_MAE\\\",\\n        ]\\n    )\\n\\n    metrics_df = metrics_df.drop_duplicates(\\n        subset=[\\\"Gas\\\", \\\"Repeat_ID\\\", \\\"Model\\\"],\\n        keep=\\\"last\\\",\\n    ).reset_index(drop=True)\\n\\n    return metrics_df\\n\\n\\n# ============================================================\\n# 3. 自动筛选最优模型\\n# ============================================================\\n\\ndef select_best_model(gas_metrics):\\n    \\\"\\\"\\\"\\n    根据每次重复划分中的三项指标进行等权综合排名：\\n    1. Test R²：越高越好；\\n    2. Test RMSE：越低越好；\\n    3. Test MAE：越低越好。\\n\\n    每次划分先对9个模型分别排名，再取三项排名的平均值。\\n    最终以30次划分的平均综合名次越低越好进行排序。\\n    该自动排序仅用于核对；最终绘图模型由BEST_MODEL_OVERRIDE固定。\\n    \\\"\\\"\\\"\\n    ranked = gas_metrics.copy()\\n\\n    ranked[\\\"Rank_R2\\\"] = (\\n        ranked.groupby(\\\"Repeat_ID\\\")[\\\"Test_R2\\\"]\\n        .rank(ascending=False, method=\\\"average\\\")\\n    )\\n    ranked[\\\"Rank_RMSE\\\"] = (\\n        ranked.groupby(\\\"Repeat_ID\\\")[\\\"Test_RMSE\\\"]\\n        .rank(ascending=True, method=\\\"average\\\")\\n    )\\n    ranked[\\\"Rank_MAE\\\"] = (\\n        ranked.groupby(\\\"Repeat_ID\\\")[\\\"Test_MAE\\\"]\\n        .rank(ascending=True, method=\\\"average\\\")\\n    )\\n    ranked[\\\"Composite_rank\\\"] = ranked[\\n        [\\\"Rank_R2\\\", \\\"Rank_RMSE\\\", \\\"Rank_MAE\\\"]\\n    ].mean(axis=1)\\n\\n    summary = (\\n        ranked\\n        .groupby(\\\"Model\\\", as_index=False)\\n        .agg(\\n            Repeats=(\\\"Repeat_ID\\\", \\\"nunique\\\"),\\n            Composite_rank_mean=(\\\"Composite_rank\\\", \\\"mean\\\"),\\n            Composite_rank_median=(\\\"Composite_rank\\\", \\\"median\\\"),\\n            Composite_rank_std=(\\\"Composite_rank\\\", \\\"std\\\"),\\n            R2_mean=(\\\"Test_R2\\\", \\\"mean\\\"),\\n            R2_median=(\\\"Test_R2\\\", \\\"median\\\"),\\n            R2_std=(\\\"Test_R2\\\", \\\"std\\\"),\\n            RMSE_mean=(\\\"Test_RMSE\\\", \\\"mean\\\"),\\n            RMSE_median=(\\\"Test_RMSE\\\", \\\"median\\\"),\\n            RMSE_std=(\\\"Test_RMSE\\\", \\\"std\\\"),\\n            MAE_mean=(\\\"Test_MAE\\\", \\\"mean\\\"),\\n            MAE_median=(\\\"Test_MAE\\\", \\\"median\\\"),\\n            MAE_std=(\\\"Test_MAE\\\", \\\"std\\\"),\\n        )\\n    )\\n\\n    ranking = summary.sort_values(\\n        by=[\\n            \\\"Composite_rank_mean\\\",\\n            \\\"Composite_rank_std\\\",\\n            \\\"R2_median\\\",\\n            \\\"RMSE_median\\\",\\n            \\\"MAE_median\\\",\\n        ],\\n        ascending=[True, True, False, True, True],\\n    ).reset_index(drop=True)\\n\\n    ranking.insert(0, \\\"Final_rank\\\", np.arange(1, len(ranking) + 1))\\n    best_model = ranking.iloc[0][\\\"Model\\\"]\\n    return best_model, ranking\\n\\n\\n# ============================================================\\n# 4. 绘图公共函数\\n# ============================================================\\n\\ndef add_panel_label(ax, label):\\n    ax.text(\\n        -0.13,\\n        1.06,\\n        label,\\n        transform=ax.transAxes,\\n        color=\\\"#C00000\\\",\\n        fontsize=12,\\n        fontweight=\\\"bold\\\",\\n        va=\\\"top\\\",\\n        ha=\\\"left\\\",\\n    )\\n\\n\\ndef add_model_separators(ax):\\n    for x in np.arange(1.5, len(MODEL_ORDER) + 0.5, 1.0):\\n        ax.axvline(\\n            x,\\n            color=\\\"#9A9A9A\\\",\\n            linestyle=\\\"--\\\",\\n            linewidth=0.55,\\n            alpha=0.60,\\n            zorder=0,\\n        )\\n\\n\\ndef format_model_axis(ax):\\n    positions = np.arange(1, len(MODEL_ORDER) + 1)\\n\\n    ax.set_xticks(positions)\\n    ax.set_xticklabels(\\n        [MODEL_DISPLAY[m] for m in MODEL_ORDER],\\n        fontsize=9.5,\\n    )\\n\\n    ax.tick_params(axis=\\\"x\\\", length=2.5, pad=2)\\n    ax.tick_params(axis=\\\"y\\\", labelsize=10, length=3)\\n\\n    add_model_separators(ax)\\n\\n    for spine in ax.spines.values():\\n        spine.set_visible(True)\\n        spine.set_linewidth(0.85)\\n\\n\\ndef prepare_model_data(dataframe, value_column):\\n    data = []\\n\\n    for model_name in MODEL_ORDER:\\n        values = (\\n            dataframe.loc[dataframe[\\\"Model\\\"] == model_name, value_column]\\n            .dropna()\\n            .to_numpy(dtype=float)\\n        )\\n\\n        if len(values) == 0:\\n            raise ValueError(f\\\"模型 {model_name} 没有可用于绘图的 {value_column} 数据。\\\")\\n\\n        data.append(values)\\n\\n    return data\\n\\n\\ndef draw_metric_boxplot(\\n    ax,\\n    gas_metrics,\\n    metric,\\n    title,\\n    ylabel,\\n    best_model_name,\\n    y_limit=None,\\n    y_ticks=None,\\n    random_seed=42,\\n):\\n    positions = np.arange(1, len(MODEL_ORDER) + 1)\\n    data = prepare_model_data(gas_metrics, metric)\\n\\n    box = ax.boxplot(\\n        data,\\n        positions=positions,\\n        widths=0.50,\\n        patch_artist=True,\\n        showfliers=False,\\n        medianprops={\\\"color\\\": \\\"black\\\", \\\"linewidth\\\": 1.0},\\n        whiskerprops={\\\"color\\\": \\\"#707070\\\", \\\"linewidth\\\": 0.8},\\n        capprops={\\\"color\\\": \\\"#707070\\\", \\\"linewidth\\\": 0.8},\\n        boxprops={\\\"edgecolor\\\": \\\"#404040\\\", \\\"linewidth\\\": 0.8},\\n    )\\n\\n    for patch, model_name in zip(box[\\\"boxes\\\"], MODEL_ORDER):\\n        patch.set_facecolor(BOX_FACE_COLOR)\\n        patch.set_alpha(0.92)\\n\\n        if model_name == best_model_name:\\n            patch.set_linewidth(2.0)\\n            patch.set_edgecolor(\\\"black\\\")\\n\\n    if SHOW_METRIC_POINTS:\\n        rng = np.random.default_rng(random_seed)\\n\\n        for x, values in zip(positions, data):\\n            jitter = rng.uniform(-0.105, 0.105, len(values))\\n            ax.scatter(\\n                np.full(len(values), x) + jitter,\\n                values,\\n                s=22,\\n                facecolors=\\\"white\\\",\\n                edgecolors=\\\"#777777\\\",\\n                linewidths=0.65,\\n                alpha=0.90,\\n                zorder=3,\\n            )\\n\\n    if SHOW_MEAN_POINTS:\\n        means = [np.nanmean(values) for values in data]\\n        ax.scatter(\\n            positions,\\n            means,\\n            s=28,\\n            color=\\\"black\\\",\\n            edgecolors=\\\"none\\\",\\n            zorder=5,\\n        )\\n\\n    ax.set_title(title, fontsize=15, fontweight=\\\"bold\\\", pad=8)\\n    ax.set_ylabel(ylabel, fontsize=12)\\n\\n    format_model_axis(ax)\\n\\n    if metric == \\\"Test_R2\\\":\\n        ax.axhline(0, color=\\\"#808080\\\", linewidth=0.8, linestyle=\\\"-\\\")\\n\\n    if y_limit is not None:\\n        ax.set_ylim(*y_limit)\\n\\n    if y_ticks is not None:\\n        ax.set_yticks(y_ticks)\\n\\n\\n# ============================================================\\n# 5. 绘制单个气体三联图\\n# ============================================================\\n\\ndef plot_gas_three_panel(\\n    gas_key,\\n    gas_metrics,\\n    best_model_name,\\n    save_dir,\\n):\\n    config = GAS_CONFIGS[gas_key]\\n\\n    fig, axes = plt.subplots(\\n        1,\\n        3,\\n        figsize=(15.5, 4.8),\\n        dpi=120,\\n    )\\n\\n    # --------------------------------------------------------\\n    # (a) R²纵坐标范围固定\\n    # --------------------------------------------------------\\n    if gas_key == \\\"N2O\\\":\\n        r2_y_limit = (-0.4, 1.0)\\n        r2_y_ticks = np.arange(-0.4, 1.01, 0.2)\\n    else:\\n        r2_y_limit = (0.0, 1.0)\\n        r2_y_ticks = np.arange(0.0, 1.01, 0.2)\\n\\n    # --------------------------------------------------------\\n    # (a) Testing R²\\n    # --------------------------------------------------------\\n    draw_metric_boxplot(\\n        ax=axes[0],\\n        gas_metrics=gas_metrics,\\n        metric=\\\"Test_R2\\\",\\n        title=r\\\"Testing R$^2$\\\",\\n        ylabel=r\\\"R$^2$\\\",\\n        best_model_name=best_model_name,\\n        y_limit=r2_y_limit,\\n        y_ticks=r2_y_ticks,\\n        random_seed=42,\\n    )\\n\\n    # --------------------------------------------------------\\n    # (b) Testing RMSE\\n    # --------------------------------------------------------\\n    rmse_max = float(gas_metrics[\\\"Test_RMSE\\\"].max())\\n\\n    draw_metric_boxplot(\\n        ax=axes[1],\\n        gas_metrics=gas_metrics,\\n        metric=\\\"Test_RMSE\\\",\\n        title=\\\"Testing RMSE\\\",\\n        ylabel=f\\\"RMSE\\\\n({config['unit']})\\\",\\n        best_model_name=best_model_name,\\n        y_limit=(0, rmse_max * 1.08),\\n        random_seed=43,\\n    )\\n\\n    # --------------------------------------------------------\\n    # (c) Testing MAE\\n    # --------------------------------------------------------\\n    mae_max = float(gas_metrics[\\\"Test_MAE\\\"].max())\\n\\n    draw_metric_boxplot(\\n        ax=axes[2],\\n        gas_metrics=gas_metrics,\\n        metric=\\\"Test_MAE\\\",\\n        title=\\\"Testing MAE\\\",\\n        ylabel=f\\\"MAE\\\\n({config['unit']})\\\",\\n        best_model_name=best_model_name,\\n        y_limit=(0, mae_max * 1.08),\\n        random_seed=44,\\n    )\\n\\n    for ax, label in zip(axes, [\\\"(a)\\\", \\\"(b)\\\", \\\"(c)\\\"]):\\n        add_panel_label(ax, label)\\n\\n    fig.subplots_adjust(\\n        left=0.06,\\n        right=0.99,\\n        bottom=0.16,\\n        top=0.90,\\n        wspace=0.30,\\n    )\\n\\n    save_path = Path(save_dir) / f\\\"{gas_key}_repeated_outer_split_3panel_final.png\\\"\\n\\n    fig.savefig(\\n        save_path,\\n        dpi=SAVE_DPI,\\n        bbox_inches=\\\"tight\\\",\\n        facecolor=\\\"white\\\",\\n    )\\n\\n    print(f\\\"[{gas_key}] 三联图已保存：\\\\n{save_path}\\\")\\n\\n    if SHOW_FIGURES:\\n        plt.show()\\n    else:\\n        plt.close(fig)\\n\\n    del fig, axes\\n    gc.collect()\\n\\n    return save_path\\n\\n\\n# ============================================================\\n# 6. 主程序\\n# ============================================================\\n\\ndef main():\\n    print(\\\"=\\\" * 80)\\n    print(\\\"直接读取已有重复划分结果并绘制三联图\\\")\\n    print(\\\"不重新划分数据，不重新训练模型\\\")\\n    print(\\\"=\\\" * 80)\\n\\n    metrics_df = load_saved_metrics(RESULT_DIR)\\n    check_metric_columns(metrics_df)\\n    metrics_df = clean_metrics_table(metrics_df)\\n\\n    print(\\\"\\\\n结果数据读取完成：\\\")\\n    print(f\\\"指标记录数：{len(metrics_df)}\\\")\\n\\n    selected_models = {}\\n\\n    for gas_key in [\\\"N2O\\\", \\\"CO2\\\", \\\"CH4\\\"]:\\n        gas_metrics = metrics_df.loc[metrics_df[\\\"Gas\\\"] == gas_key].copy()\\n\\n        if gas_metrics.empty:\\n            raise ValueError(f\\\"指标文件中没有 {gas_key} 结果。\\\")\\n\\n        automatic_best_model, ranking = select_best_model(gas_metrics)\\n\\n        override_model = BEST_MODEL_OVERRIDE.get(gas_key)\\n\\n        if override_model is None:\\n            best_model_name = automatic_best_model\\n        else:\\n            if override_model not in MODEL_ORDER:\\n                raise ValueError(\\n                    f\\\"{gas_key} 指定的模型 {override_model} 不在 MODEL_ORDER 中。\\\"\\n                )\\n            best_model_name = override_model\\n\\n        selected_models[gas_key] = best_model_name\\n\\n        print(\\\"\\\\n\\\" + \\\"-\\\" * 80)\\n        print(f\\\"{gas_key}：\\\")\\n        print(f\\\"重复划分次数：{gas_metrics['Repeat_ID'].nunique()}\\\")\\n        print(f\\\"自动筛选最优模型：{automatic_best_model}\\\")\\n        print(f\\\"最终绘图强调模型：{best_model_name}\\\")\\n\\n        best_row = ranking.loc[ranking[\\\"Model\\\"] == best_model_name].iloc[0]\\n\\n        print(f\\\"Median R²   = {best_row['R2_median']:.4f}\\\")\\n        print(f\\\"Median RMSE = {best_row['RMSE_median']:.4f}\\\")\\n        print(f\\\"Median MAE  = {best_row['MAE_median']:.4f}\\\")\\n        print(\\\"-\\\" * 80)\\n\\n        ranking = ranking.copy()\\n        ranking.insert(\\n            1,\\n            \\\"Selected_for_final_plot\\\",\\n            ranking[\\\"Model\\\"].eq(best_model_name),\\n        )\\n\\n        ranking.to_excel(\\n            SAVE_DIR / f\\\"{gas_key}_model_ranking_for_plot.xlsx\\\",\\n            index=False,\\n        )\\n\\n        plot_gas_three_panel(\\n            gas_key=gas_key,\\n            gas_metrics=gas_metrics,\\n            best_model_name=best_model_name,\\n            save_dir=SAVE_DIR,\\n        )\\n\\n    print(\\\"\\\\n\\\" + \\\"=\\\" * 80)\\n    print(\\\"三种气体三联图全部绘制完成。\\\")\\n    print(\\\"保存目录：\\\")\\n    print(SAVE_DIR)\\n    print(\\\"绘图强调模型：\\\")\\n    print(selected_models)\\n    print(\\\"=\\\" * 80)\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\"},\"shap\":{\"filename\":\"GHG_final_models_recompute_SHAP_3panel.py\",\"source\":\"# -*- coding: utf-8 -*-\\n\\\"\\\"\\\"\\n按最终模型重新拟合并计算 SHAP，随后绘制三气体 SHAP 三联图\\n================================================================\\n最终模型：\\n    N2O -> ET\\n    CO2 -> GBDT\\n    CH4 -> ET\\n\\n说明：\\n1. 不重新运行9模型，也不重新进行贝叶斯优化；\\n2. 读取原9模型流程保存的各模型最优参数 JSON；\\n3. 按原固定划分种子重新拟合最终选定模型一次；\\n4. 重新计算相应模型的 SHAP 值并保存 NPZ/Excel；\\n5. 绘制 Mean |SHAP| 条形图 + SHAP 散点三联图；\\n6. 每个子图左侧显示变量名称、刻度和竖轴；\\n7. 色阶独立放在最右侧，不覆盖 CH4 子图。\\n\\\"\\\"\\\"\\n\\nimport gc\\nimport json\\nimport os\\nimport re\\nimport warnings\\nfrom pathlib import Path\\n\\nimport numpy as np\\nimport pandas as pd\\nimport matplotlib as mpl\\nimport matplotlib.pyplot as plt\\nfrom matplotlib.colors import Normalize\\n\\nfrom sklearn.pipeline import Pipeline\\nfrom sklearn.impute import KNNImputer\\nfrom sklearn.preprocessing import StandardScaler\\nfrom sklearn.model_selection import train_test_split\\nfrom sklearn.ensemble import GradientBoostingRegressor, ExtraTreesRegressor\\n\\nimport shap\\n\\n\\n# ============================================================\\n# 0. 用户设置\\n# ============================================================\\n\\nDATA_CANDIDATES = [\\n    r\\\"E:\\\\温室气体模型\\\\7\\\\273数据(1).xlsx\\\",\\n    r\\\"E:\\\\温室气体模型\\\\7\\\\273数据.xlsx\\\",\\n    r\\\"273数据(1).xlsx\\\",\\n    r\\\"273数据.xlsx\\\",\\n]\\n\\n# 原9模型流程的输出目录，其中应包含：\\n# N2O/N2O_best_params.json\\n# CO2/CO2_best_params.json\\n# CH4/CH4_best_params.json\\nRESULT_DIR = Path(r\\\"E:\\\\温室气体模型\\\\7\\\\ML_SHAP_最优模型\\\")\\n\\n# 新生成结果目录\\nSAVE_DIR = RESULT_DIR / \\\"Final_models_SHAP\\\"\\nSAVE_DIR.mkdir(parents=True, exist_ok=True)\\n\\nOUTPUT_PNG = SAVE_DIR / \\\"SHAP_three_gases_final_models_600dpi.png\\\"\\nOUTPUT_TIFF = SAVE_DIR / \\\"SHAP_three_gases_final_models_600dpi.tiff\\\"\\n\\nSHEET_NAME = None\\nPREFERRED_HEADER = 0\\nTEST_SIZE = 0.20\\nKNN_IMPUTER_NEIGHBORS = 5\\nGLOBAL_RANDOM_STATE = 42\\nSAVE_DPI = 600\\nMAX_DISPLAY = 13\\nPOINT_SIZE = 11\\nSHOW_FIGURE = True\\nSAVE_TIFF = False  # 内存不足时保持False\\n\\n# 与此前建模代码一致的固定划分种子\\nGAS_SPLIT_SEEDS = {\\n    \\\"N2O\\\": 33,\\n    \\\"CO2\\\": 12,\\n    \\\"CH4\\\": 31,\\n}\\n\\n# 最终确定的模型\\nFINAL_MODEL_MAP = {\\n    \\\"N2O\\\": \\\"ET\\\",\\n    \\\"CO2\\\": \\\"GBDT\\\",\\n    \\\"CH4\\\": \\\"ET\\\",\\n}\\n\\nGAS_ORDER = [\\\"N2O\\\", \\\"CO2\\\", \\\"CH4\\\"]\\n\\nGAS_TITLES = {\\n    \\\"N2O\\\": r\\\"N$_2$O\\\",\\n    \\\"CO2\\\": r\\\"CO$_2$\\\",\\n    \\\"CH4\\\": r\\\"CH$_4$\\\",\\n}\\n\\nPANEL_LABELS = {\\n    \\\"N2O\\\": \\\"(a)\\\",\\n    \\\"CO2\\\": \\\"(b)\\\",\\n    \\\"CH4\\\": \\\"(c)\\\",\\n}\\n\\nFEATURE_KEYS = [\\n    \\\"SR\\\", \\\"BS\\\", \\\"BC\\\", \\\"N\\\", \\\"P\\\", \\\"K\\\",\\n    \\\"pH\\\", \\\"SOM\\\", \\\"AN\\\", \\\"AP\\\", \\\"AK\\\", \\\"MAT\\\", \\\"MAP\\\",\\n]\\n\\n\\n# ============================================================\\n# 1. 全局绘图设置\\n# ============================================================\\n\\nwarnings.filterwarnings(\\\"ignore\\\")\\n\\nmpl.rcParams[\\\"font.family\\\"] = \\\"Times New Roman\\\"\\nmpl.rcParams[\\\"font.size\\\"] = 9\\nmpl.rcParams[\\\"axes.unicode_minus\\\"] = False\\nmpl.rcParams[\\\"mathtext.fontset\\\"] = \\\"stix\\\"\\nmpl.rcParams[\\\"figure.dpi\\\"] = 120\\n\\n\\n# ============================================================\\n# 2. 数据列名兼容设置\\n# ============================================================\\n\\nCOLUMN_ALIASES = {\\n    \\\"SR\\\": [\\\"SR\\\", \\\"Straw return\\\", \\\"Straw returning\\\"],\\n    \\\"BS\\\": [\\\"BS\\\", \\\"Biogas slurry\\\", \\\"Biogas slurry application\\\"],\\n    \\\"BC\\\": [\\\"BC\\\", \\\"Biochar\\\", \\\"Biochar application\\\"],\\n    \\\"N\\\": [\\\"N\\\", \\\"Nitrogen (N) Application Rate\\\", \\\"Nitrogen application rate\\\", \\\"N application rate\\\"],\\n    \\\"P\\\": [\\\"P\\\", \\\"Phosphorus (P) Application Rate\\\", \\\"Phosphorus application rate\\\", \\\"P application rate\\\"],\\n    \\\"K\\\": [\\\"K\\\", \\\"Potassium (K) application rate\\\", \\\"Potassium application rate\\\", \\\"K application rate\\\"],\\n    \\\"pH\\\": [\\\"pH\\\", \\\"PH\\\", \\\"Soil pH\\\"],\\n    \\\"SOM\\\": [\\\"SOM\\\", \\\"SOM（g/kg）\\\", \\\"SOM(g/kg)\\\", \\\"Soil organic matter\\\"],\\n    \\\"AN\\\": [\\\"AN\\\", \\\"AN（mg/kg）\\\", \\\"AN(mg/kg)\\\", \\\"Available nitrogen\\\"],\\n    \\\"AP\\\": [\\\"AP\\\", \\\"AP（mg/kg）\\\", \\\"AP(mg/kg)\\\", \\\"Available phosphorus\\\"],\\n    \\\"AK\\\": [\\\"AK\\\", \\\"AK（mg/kg）\\\", \\\"AK(mg/kg)\\\", \\\"Available potassium\\\"],\\n    \\\"MAT\\\": [\\\"MAT\\\", \\\"MAT（℃）\\\", \\\"MAT(℃)\\\", \\\"Mean annual temperature\\\"],\\n    \\\"MAP\\\": [\\\"MAP\\\", \\\"MAP（mm ）\\\", \\\"MAP（mm）\\\", \\\"MAP(mm )\\\", \\\"MAP(mm)\\\", \\\"Mean annual precipitation\\\"],\\n    \\\"N2O\\\": [\\\"N2O\\\", \\\"N2O累计排放量（kg/hm2）\\\", \\\"N₂O累计排放量（kg/hm2）\\\", \\\"Cumulative N2O emissions\\\", \\\"Cumulative N₂O emissions\\\"],\\n    \\\"CO2\\\": [\\\"CO2\\\", \\\"CO2累计排放量（kg/hm2）\\\", \\\"CO₂累计排放量（kg/hm2）\\\", \\\"Cumulative CO2 emissions\\\", \\\"Cumulative CO₂ emissions\\\"],\\n    \\\"CH4\\\": [\\\"CH4\\\", \\\"CH4累计排放量（kg/hm2）\\\", \\\"CH₄累计排放量（kg/hm2）\\\", \\\"Cumulative CH4 emissions\\\", \\\"Cumulative CH₄ emissions\\\"],\\n}\\n\\n\\ndef normalize_column_name(name):\\n    text = str(name).strip().lower()\\n    text = text.replace(\\\"（\\\", \\\"(\\\").replace(\\\"）\\\", \\\")\\\")\\n    text = text.replace(\\\"₂\\\", \\\"2\\\").replace(\\\"₄\\\", \\\"4\\\")\\n    text = text.replace(\\\"℃\\\", \\\"c\\\")\\n    text = re.sub(r\\\"[\\\\s_\\\\-]+\\\", \\\"\\\", text)\\n    return text\\n\\n\\ndef resolve_columns(raw_columns):\\n    normalized_to_original = {\\n        normalize_column_name(column): column\\n        for column in raw_columns\\n    }\\n\\n    resolved = {}\\n    unresolved = []\\n\\n    for standard_name, aliases in COLUMN_ALIASES.items():\\n        matched = None\\n        for alias in [standard_name] + list(aliases):\\n            key = normalize_column_name(alias)\\n            if key in normalized_to_original:\\n                matched = normalized_to_original[key]\\n                break\\n\\n        if matched is None:\\n            unresolved.append(standard_name)\\n        else:\\n            resolved[standard_name] = matched\\n\\n    return resolved, unresolved\\n\\n\\ndef find_data_path(candidates):\\n    for candidate in candidates:\\n        if candidate and os.path.exists(candidate):\\n            return Path(candidate).resolve()\\n\\n    raise FileNotFoundError(\\n        \\\"未找到数据文件，请修改 DATA_CANDIDATES。\\\\n尝试过：\\\\n\\\"\\n        + \\\"\\\\n\\\".join(str(path) for path in candidates)\\n    )\\n\\n\\ndef load_dataset(file_path, sheet_name=None, preferred_header=0):\\n    headers_to_try = []\\n    for header in [preferred_header, 0, 1]:\\n        if header not in headers_to_try:\\n            headers_to_try.append(header)\\n\\n    errors = []\\n\\n    for header in headers_to_try:\\n        try:\\n            raw = pd.read_excel(\\n                file_path,\\n                sheet_name=sheet_name if sheet_name is not None else 0,\\n                header=header,\\n                engine=\\\"openpyxl\\\",\\n            )\\n\\n            resolved, unresolved = resolve_columns(raw.columns)\\n\\n            if not unresolved:\\n                selected = pd.DataFrame(index=raw.index)\\n                for standard_name in FEATURE_KEYS + GAS_ORDER:\\n                    selected[standard_name] = pd.to_numeric(\\n                        raw[resolved[standard_name]],\\n                        errors=\\\"coerce\\\",\\n                    )\\n                return selected, raw, resolved, header\\n\\n            errors.append(\\n                f\\\"header={header} 未识别：{', '.join(unresolved)}\\\"\\n            )\\n\\n        except Exception as exc:\\n            errors.append(f\\\"header={header} 读取失败：{exc}\\\")\\n\\n    raise KeyError(\\n        \\\"无法识别13个输入变量和3个目标变量。\\\\n\\\\n\\\"\\n        + \\\"\\\\n\\\".join(errors)\\n    )\\n\\n\\n# ============================================================\\n# 3. 模型与参数读取\\n# ============================================================\\n\\nINTEGER_PARAMS = {\\n    \\\"n_estimators\\\", \\\"max_depth\\\", \\\"min_samples_split\\\", \\\"min_samples_leaf\\\",\\n    \\\"depth\\\", \\\"iterations\\\", \\\"num_leaves\\\", \\\"n_neighbors\\\", \\\"p\\\",\\n}\\n\\nFLOAT_PARAMS = {\\n    \\\"learning_rate\\\", \\\"subsample\\\", \\\"colsample_bytree\\\", \\\"max_features\\\",\\n    \\\"min_impurity_decrease\\\", \\\"ccp_alpha\\\", \\\"C\\\", \\\"gamma\\\", \\\"epsilon\\\",\\n}\\n\\n\\ndef coerce_param_value(key, value):\\n    if value is None:\\n        return None\\n\\n    if key in INTEGER_PARAMS:\\n        return int(float(value))\\n\\n    if key in FLOAT_PARAMS:\\n        return float(value)\\n\\n    if isinstance(value, str):\\n        text = value.strip()\\n        if text.lower() == \\\"none\\\":\\n            return None\\n        if text.lower() == \\\"true\\\":\\n            return True\\n        if text.lower() == \\\"false\\\":\\n            return False\\n\\n    return value\\n\\n\\ndef load_model_params(result_dir, gas_key, model_name):\\n    params_path = Path(result_dir) / gas_key / f\\\"{gas_key}_best_params.json\\\"\\n\\n    if not params_path.exists():\\n        raise FileNotFoundError(\\n            f\\\"未找到参数文件：\\\\n{params_path}\\\\n\\\"\\n            \\\"请确认原9模型贝叶斯优化代码已经完整运行。\\\"\\n        )\\n\\n    with open(params_path, \\\"r\\\", encoding=\\\"utf-8\\\") as file:\\n        all_params = json.load(file)\\n\\n    if model_name not in all_params:\\n        raise KeyError(\\n            f\\\"{params_path.name} 中没有模型 {model_name}。\\\\n\\\"\\n            f\\\"当前包含：{list(all_params.keys())}\\\"\\n        )\\n\\n    return {\\n        key.replace(\\\"model__\\\", \\\"\\\"): coerce_param_value(\\n            key.replace(\\\"model__\\\", \\\"\\\"), value\\n        )\\n        for key, value in all_params[model_name].items()\\n    }\\n\\n\\ndef build_estimator(model_name, params):\\n    if model_name == \\\"ET\\\":\\n        estimator = ExtraTreesRegressor(\\n            random_state=GLOBAL_RANDOM_STATE,\\n            n_jobs=-1,\\n        )\\n    elif model_name == \\\"GBDT\\\":\\n        estimator = GradientBoostingRegressor(\\n            random_state=GLOBAL_RANDOM_STATE,\\n        )\\n    else:\\n        raise ValueError(\\n            f\\\"当前代码仅配置最终模型 ET 和 GBDT，收到：{model_name}\\\"\\n        )\\n\\n    estimator.set_params(**params)\\n    return estimator\\n\\n\\ndef make_pipeline(estimator):\\n    return Pipeline(\\n        steps=[\\n            (\\\"imputer\\\", KNNImputer(n_neighbors=KNN_IMPUTER_NEIGHBORS)),\\n            (\\\"scaler\\\", StandardScaler()),\\n            (\\\"model\\\", estimator),\\n        ]\\n    )\\n\\n\\n# ============================================================\\n# 4. 重新拟合最终模型并计算SHAP\\n# ============================================================\\n\\n\\ndef get_original_scale_imputed_data(pipeline, X):\\n    imputer = pipeline.named_steps[\\\"imputer\\\"]\\n    imputed = imputer.transform(X)\\n    return pd.DataFrame(imputed, columns=FEATURE_KEYS, index=X.index)\\n\\n\\ndef get_standardized_data(pipeline, X):\\n    imputer = pipeline.named_steps[\\\"imputer\\\"]\\n    scaler = pipeline.named_steps[\\\"scaler\\\"]\\n    imputed = imputer.transform(X)\\n    scaled = scaler.transform(imputed)\\n    return pd.DataFrame(scaled, columns=FEATURE_KEYS, index=X.index)\\n\\n\\ndef fit_and_compute_shap(data, gas_key, model_name):\\n    gas_df = data[FEATURE_KEYS + [gas_key]].dropna(subset=[gas_key]).copy()\\n\\n    X = gas_df[FEATURE_KEYS]\\n    y = gas_df[gas_key]\\n\\n    X_train, X_test, y_train, y_test = train_test_split(\\n        X,\\n        y,\\n        test_size=TEST_SIZE,\\n        random_state=GAS_SPLIT_SEEDS[gas_key],\\n    )\\n\\n    params = load_model_params(RESULT_DIR, gas_key, model_name)\\n    estimator = build_estimator(model_name, params)\\n    pipeline = make_pipeline(estimator)\\n\\n    print(\\\"\\\\n\\\" + \\\"=\\\" * 80)\\n    print(\\n        f\\\"{gas_key}: final model={model_name}, \\\"\\n        f\\\"n={len(gas_df)}, train={len(X_train)}, test={len(X_test)}, \\\"\\n        f\\\"split seed={GAS_SPLIT_SEEDS[gas_key]}\\\"\\n    )\\n    print(\\\"参数：\\\", params)\\n\\n    pipeline.fit(X_train, y_train)\\n\\n    X_test_scaled = get_standardized_data(pipeline, X_test)\\n    X_display = get_original_scale_imputed_data(pipeline, X_test)\\n    fitted_estimator = pipeline.named_steps[\\\"model\\\"]\\n\\n    try:\\n        explainer = shap.TreeExplainer(fitted_estimator)\\n        raw_values = explainer.shap_values(X_test_scaled)\\n\\n        if isinstance(raw_values, list):\\n            raw_values = raw_values[0]\\n\\n        shap_values = np.asarray(raw_values, dtype=np.float64)\\n        base_value = explainer.expected_value\\n        if np.ndim(base_value) > 0:\\n            base_value = np.asarray(base_value).reshape(-1)[0]\\n        base_values = np.repeat(float(base_value), len(X_test_scaled))\\n\\n    except Exception as tree_error:\\n        print(f\\\"TreeExplainer失败，改用通用Explainer：{tree_error}\\\")\\n        background_n = min(60, len(X_train))\\n        background = X_train.sample(\\n            n=background_n,\\n            random_state=GLOBAL_RANDOM_STATE,\\n        )\\n        explainer = shap.Explainer(\\n            pipeline.predict,\\n            background,\\n            algorithm=\\\"permutation\\\",\\n        )\\n        explanation = explainer(\\n            X_test,\\n            max_evals=2 * len(FEATURE_KEYS) + 1,\\n        )\\n        shap_values = np.asarray(explanation.values, dtype=np.float64)\\n        base_values = np.asarray(explanation.base_values)\\n\\n    if shap_values.ndim == 3 and shap_values.shape[-1] == 1:\\n        shap_values = shap_values[:, :, 0]\\n\\n    mean_abs_shap = np.nanmean(np.abs(shap_values), axis=0)\\n\\n    importance_df = pd.DataFrame(\\n        {\\n            \\\"Gas\\\": gas_key,\\n            \\\"Model\\\": model_name,\\n            \\\"Feature\\\": FEATURE_KEYS,\\n            \\\"Mean_abs_SHAP\\\": mean_abs_shap,\\n        }\\n    ).sort_values(\\\"Mean_abs_SHAP\\\", ascending=False).reset_index(drop=True)\\n\\n    gas_save_dir = SAVE_DIR / gas_key\\n    gas_save_dir.mkdir(parents=True, exist_ok=True)\\n\\n    npz_path = gas_save_dir / f\\\"{gas_key}_{model_name}_SHAP_values_final.npz\\\"\\n    excel_path = gas_save_dir / f\\\"{gas_key}_{model_name}_SHAP_importance_final.xlsx\\\"\\n\\n    np.savez_compressed(\\n        npz_path,\\n        shap_values=shap_values,\\n        base_values=base_values,\\n        feature_values=X_display.to_numpy(dtype=float),\\n        feature_names=np.array(FEATURE_KEYS, dtype=object),\\n        train_indices=X_train.index.to_numpy(),\\n        test_indices=X_test.index.to_numpy(),\\n        model_name=np.array([model_name], dtype=object),\\n        split_seed=np.array([GAS_SPLIT_SEEDS[gas_key]], dtype=int),\\n    )\\n\\n    importance_df.to_excel(excel_path, index=False)\\n\\n    print(\\\"SHAP NPZ：\\\", npz_path)\\n    print(\\\"SHAP排序表：\\\", excel_path)\\n\\n    return {\\n        \\\"gas_key\\\": gas_key,\\n        \\\"model_name\\\": model_name,\\n        \\\"shap_values\\\": shap_values,\\n        \\\"feature_values\\\": X_display.to_numpy(dtype=float),\\n        \\\"feature_names\\\": FEATURE_KEYS.copy(),\\n        \\\"importance_df\\\": importance_df,\\n    }\\n\\n\\n# ============================================================\\n# 5. 绘图辅助函数\\n# ============================================================\\n\\nFEATURE_NAME_MAP = {\\n    \\\"SR\\\": \\\"SR\\\",\\n    \\\"BS\\\": \\\"BS\\\",\\n    \\\"BC\\\": \\\"BC\\\",\\n    \\\"N\\\": \\\"N rate\\\",\\n    \\\"P\\\": \\\"P rate\\\",\\n    \\\"K\\\": \\\"K rate\\\",\\n    \\\"pH\\\": \\\"pH\\\",\\n    \\\"SOM\\\": \\\"SOM\\\",\\n    \\\"AN\\\": \\\"AN\\\",\\n    \\\"AP\\\": \\\"AP\\\",\\n    \\\"AK\\\": \\\"AK\\\",\\n    \\\"MAT\\\": \\\"MAT\\\",\\n    \\\"MAP\\\": \\\"MAP\\\",\\n}\\n\\n\\ndef create_swarm_jitter(x_values, max_offset=0.25, number_of_bins=28):\\n    x_values = np.asarray(x_values, dtype=float)\\n    offsets = np.zeros(len(x_values), dtype=float)\\n\\n    valid_mask = np.isfinite(x_values)\\n    valid_indices = np.where(valid_mask)[0]\\n\\n    if len(valid_indices) <= 1:\\n        return offsets\\n\\n    valid_x = x_values[valid_indices]\\n    x_min = np.min(valid_x)\\n    x_max = np.max(valid_x)\\n\\n    if np.isclose(x_min, x_max):\\n        return offsets\\n\\n    bin_edges = np.linspace(x_min, x_max, number_of_bins + 1)\\n    bin_ids = np.digitize(valid_x, bin_edges[1:-1])\\n\\n    for bin_id in np.unique(bin_ids):\\n        local_positions = np.where(bin_ids == bin_id)[0]\\n        local_indices = valid_indices[local_positions]\\n        count = len(local_indices)\\n\\n        if count <= 1:\\n            continue\\n\\n        sequence = [0.0]\\n        level = 1\\n        while len(sequence) < count:\\n            sequence.append(float(level))\\n            if len(sequence) < count:\\n                sequence.append(-float(level))\\n            level += 1\\n\\n        sequence = np.asarray(sequence[:count], dtype=float)\\n        max_level = np.max(np.abs(sequence))\\n        if max_level > 0:\\n            sequence = sequence / max_level * max_offset\\n\\n        sorted_indices = local_indices[np.argsort(x_values[local_indices])]\\n        offsets[sorted_indices] = sequence\\n\\n    return offsets\\n\\n\\ndef normalize_feature_values(values):\\n    values = np.asarray(values, dtype=float)\\n    normalized = np.full(values.shape, np.nan, dtype=float)\\n    valid_mask = np.isfinite(values)\\n\\n    if valid_mask.sum() == 0:\\n        return normalized\\n\\n    valid_values = values[valid_mask]\\n    lower = np.nanpercentile(valid_values, 5)\\n    upper = np.nanpercentile(valid_values, 95)\\n\\n    if np.isclose(lower, upper):\\n        normalized[valid_mask] = 0.5\\n    else:\\n        normalized[valid_mask] = np.clip(\\n            (valid_values - lower) / (upper - lower),\\n            0,\\n            1,\\n        )\\n\\n    return normalized\\n\\n\\n# ============================================================\\n# 6. 绘制三联图\\n# ============================================================\\n\\n\\ndef plot_three_gas_shap(results):\\n    fig = plt.figure(figsize=(15.6, 5.2), dpi=100)\\n\\n    grid = fig.add_gridspec(\\n        nrows=1,\\n        ncols=4,\\n        width_ratios=[1.0, 1.0, 1.0, 0.038],\\n        left=0.075,\\n        right=0.955,\\n        bottom=0.15,\\n        top=0.82,\\n        wspace=0.47,\\n    )\\n\\n    bar_axes = [fig.add_subplot(grid[0, i]) for i in range(3)]\\n    colorbar_axis = fig.add_subplot(grid[0, 3])\\n    cmap = mpl.colormaps[\\\"coolwarm\\\"]\\n\\n    for panel_index, gas in enumerate(GAS_ORDER):\\n        ax_bar = bar_axes[panel_index]\\n        result = results[gas]\\n\\n        shap_values = result[\\\"shap_values\\\"]\\n        feature_values = result[\\\"feature_values\\\"]\\n        feature_names = result[\\\"feature_names\\\"]\\n        model_name = result[\\\"model_name\\\"]\\n\\n        mean_abs_shap = np.nanmean(np.abs(shap_values), axis=0)\\n        feature_order = np.argsort(mean_abs_shap)[::-1][:MAX_DISPLAY]\\n        ordered_mean_shap = mean_abs_shap[feature_order]\\n        ordered_names = [FEATURE_NAME_MAP.get(feature_names[i], feature_names[i]) for i in feature_order]\\n        y_positions = np.arange(len(feature_order))\\n\\n        # 底层：Mean |SHAP|\\n        ax_bar.barh(\\n            y_positions,\\n            ordered_mean_shap,\\n            height=0.66,\\n            color=\\\"#9ed3e8\\\",\\n            edgecolor=\\\"none\\\",\\n            alpha=0.96,\\n            zorder=1,\\n        )\\n\\n        bar_max = float(np.nanmax(ordered_mean_shap))\\n        ax_bar.set_xlim(0, bar_max * 1.08 if bar_max > 0 else 1)\\n        ax_bar.set_xlabel(\\\"Mean |SHAP|\\\", fontsize=10, labelpad=5)\\n        ax_bar.tick_params(axis=\\\"x\\\", labelsize=8, length=3)\\n\\n        ax_bar.grid(\\n            axis=\\\"y\\\",\\n            linestyle=\\\":\\\",\\n            linewidth=0.50,\\n            color=\\\"#d0d0d0\\\",\\n            alpha=0.65,\\n            zorder=0,\\n        )\\n\\n        # 左侧竖轴和变量名称\\n        ax_bar.spines[\\\"left\\\"].set_visible(True)\\n        ax_bar.spines[\\\"left\\\"].set_linewidth(0.85)\\n        ax_bar.spines[\\\"bottom\\\"].set_visible(True)\\n        ax_bar.spines[\\\"bottom\\\"].set_linewidth(0.85)\\n        ax_bar.spines[\\\"top\\\"].set_visible(False)\\n        ax_bar.spines[\\\"right\\\"].set_visible(False)\\n\\n        # 顶层：SHAP散点\\n        ax_shap = ax_bar.twiny()\\n        ax_shap.set_zorder(ax_bar.get_zorder() + 1)\\n        ax_shap.patch.set_alpha(0)\\n\\n        selected_values = shap_values[:, feature_order]\\n        finite_values = selected_values[np.isfinite(selected_values)]\\n\\n        if finite_values.size > 0:\\n            shap_min = float(np.min(finite_values))\\n            shap_max = float(np.max(finite_values))\\n            shap_range = shap_max - shap_min\\n            padding = shap_range * 0.06 if shap_range > 0 else 1.0\\n            ax_shap.set_xlim(shap_min - padding, shap_max + padding)\\n\\n        for row_position, feature_index in enumerate(feature_order):\\n            current_shap = shap_values[:, feature_index]\\n            current_feature = feature_values[:, feature_index]\\n\\n            valid_mask = np.isfinite(current_shap)\\n            current_shap = current_shap[valid_mask]\\n            current_feature = current_feature[valid_mask]\\n\\n            jitter = create_swarm_jitter(current_shap)\\n            normalized_colors = normalize_feature_values(current_feature)\\n\\n            point_colors = np.empty((len(current_shap), 4), dtype=float)\\n            valid_color_mask = np.isfinite(normalized_colors)\\n            point_colors[valid_color_mask] = cmap(normalized_colors[valid_color_mask])\\n            point_colors[~valid_color_mask] = mpl.colors.to_rgba(\\\"#808080\\\")\\n\\n            ax_shap.scatter(\\n                current_shap,\\n                row_position + jitter,\\n                c=point_colors,\\n                s=POINT_SIZE,\\n                alpha=0.88,\\n                linewidths=0,\\n                edgecolors=\\\"none\\\",\\n                rasterized=True,\\n                zorder=4,\\n            )\\n\\n        ax_shap.axvline(\\n            0,\\n            color=\\\"#999999\\\",\\n            linestyle=\\\"--\\\",\\n            linewidth=0.75,\\n            alpha=0.90,\\n            zorder=2,\\n        )\\n\\n        ax_shap.xaxis.set_label_position(\\\"top\\\")\\n        ax_shap.xaxis.tick_top()\\n        ax_shap.set_xlabel(\\\"SHAP value\\\", fontsize=10, labelpad=4)\\n        ax_shap.tick_params(axis=\\\"x\\\", labelsize=8, length=3, pad=2)\\n        ax_shap.tick_params(\\n            axis=\\\"y\\\",\\n            left=False,\\n            right=False,\\n            labelleft=False,\\n            labelright=False,\\n        )\\n\\n        ax_shap.spines[\\\"bottom\\\"].set_visible(False)\\n        ax_shap.spines[\\\"right\\\"].set_visible(False)\\n        ax_shap.spines[\\\"left\\\"].set_visible(False)\\n\\n        # y轴必须在创建twiny之后设置\\n        ax_bar.set_ylim(len(feature_order) - 0.5, -0.5)\\n        ax_bar.set_yticks(y_positions)\\n        ax_bar.set_yticklabels(ordered_names, fontsize=8.7)\\n        ax_bar.tick_params(\\n            axis=\\\"y\\\",\\n            left=True,\\n            labelleft=True,\\n            length=3.0,\\n            width=0.85,\\n            pad=4,\\n        )\\n\\n        ax_shap.set_title(\\n            f\\\"{GAS_TITLES[gas]} ({model_name})\\\",\\n            fontsize=12,\\n            pad=8,\\n        )\\n\\n        ax_shap.text(\\n            -0.18,\\n            1.055,\\n            PANEL_LABELS[gas],\\n            transform=ax_shap.transAxes,\\n            color=\\\"#c00000\\\",\\n            fontsize=11,\\n            fontweight=\\\"bold\\\",\\n            ha=\\\"left\\\",\\n            va=\\\"bottom\\\",\\n        )\\n\\n    color_mapper = mpl.cm.ScalarMappable(\\n        norm=Normalize(vmin=0, vmax=1),\\n        cmap=cmap,\\n    )\\n    color_mapper.set_array([])\\n\\n    colorbar = fig.colorbar(\\n        color_mapper,\\n        cax=colorbar_axis,\\n        orientation=\\\"vertical\\\",\\n    )\\n    colorbar.set_ticks([0, 1])\\n    colorbar.set_ticklabels([\\\"Low\\\", \\\"High\\\"])\\n    colorbar.ax.yaxis.set_ticks_position(\\\"right\\\")\\n    colorbar.ax.yaxis.set_label_position(\\\"right\\\")\\n    colorbar.set_label(\\\"Feature value\\\", fontsize=10, labelpad=10)\\n    colorbar.ax.tick_params(axis=\\\"y\\\", labelsize=8, length=3, pad=4)\\n    colorbar.outline.set_linewidth(0.7)\\n\\n    fig.savefig(\\n        OUTPUT_PNG,\\n        dpi=SAVE_DPI,\\n        facecolor=\\\"white\\\",\\n        bbox_inches=\\\"tight\\\",\\n    )\\n\\n    if SAVE_TIFF:\\n        fig.savefig(\\n            OUTPUT_TIFF,\\n            dpi=SAVE_DPI,\\n            facecolor=\\\"white\\\",\\n            bbox_inches=\\\"tight\\\",\\n            pil_kwargs={\\\"compression\\\": \\\"tiff_lzw\\\"},\\n        )\\n\\n    if SHOW_FIGURE:\\n        plt.show()\\n    else:\\n        plt.close(fig)\\n\\n    return OUTPUT_PNG\\n\\n\\n# ============================================================\\n# 7. 主程序\\n# ============================================================\\n\\n\\ndef main():\\n    data_path = find_data_path(DATA_CANDIDATES)\\n    print(\\\"数据文件：\\\", data_path)\\n    print(\\\"原结果目录：\\\", RESULT_DIR)\\n    print(\\\"新SHAP结果目录：\\\", SAVE_DIR)\\n\\n    data, raw, resolved, used_header = load_dataset(\\n        data_path,\\n        sheet_name=SHEET_NAME,\\n        preferred_header=PREFERRED_HEADER,\\n    )\\n\\n    print(f\\\"Excel表头：header={used_header}\\\")\\n    print(f\\\"原始记录数：{len(data)}\\\")\\n\\n    results = {}\\n\\n    for gas in GAS_ORDER:\\n        results[gas] = fit_and_compute_shap(\\n            data=data,\\n            gas_key=gas,\\n            model_name=FINAL_MODEL_MAP[gas],\\n        )\\n\\n    figure_path = plot_three_gas_shap(results)\\n\\n    print(\\\"\\\\n\\\" + \\\"=\\\" * 80)\\n    print(\\\"最终模型SHAP计算与三联图绘制完成。\\\")\\n    print(\\\"最终模型：\\\", FINAL_MODEL_MAP)\\n    print(\\\"图片：\\\", figure_path)\\n    print(\\\"=\\\" * 80)\\n\\n    # 释放内存\\n    del results\\n    gc.collect()\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\"},\"path_analysis\":{\"filename\":\"新SHAP_探索性因果中介分析_完整代码.py\",\"source\":\"\\n# -*- coding: utf-8 -*-\\n\\\"\\\"\\\"\\n新 SHAP 结果对应的探索性因果中介分析\\n处理变量：SR、BC、BS（施用量）\\n结果变量：N2O、CO2、CH4\\n中介变量：\\n    N2O：SOM、AP、AK、pH、AN\\n    CO2：AN、pH、SOM、AK、AP\\n    CH4：AN、pH、AK、SOM\\n方法：标准化 OLS + HC3 稳健标准误 + 2000 次 Bootstrap + BH-FDR\\n\\\"\\\"\\\"\\n\\nimport re\\nimport warnings\\nfrom pathlib import Path\\n\\nimport numpy as np\\nimport pandas as pd\\nimport matplotlib.pyplot as plt\\nimport statsmodels.api as sm\\n\\nfrom openpyxl import load_workbook\\nfrom openpyxl.styles import Font, PatternFill, Alignment\\nfrom openpyxl.utils import get_column_letter\\nfrom statsmodels.stats.multitest import multipletests\\n\\n\\n# ============================================================\\n# 1. 参数设置\\n# ============================================================\\n\\nDATA_FILE = r\\\"E:\\\\温室气体模型\\\\7\\\\数据.xlsx\\\"\\nSHEET_NAME = 0\\n\\nOUTPUT_DIR = r\\\"E:\\\\温室气体模型\\\\7\\\\因果中介分析_新SHAP\\\"\\nOUTPUT_EXCEL = \\\"探索性因果中介分析_全部路径.xlsx\\\"\\n\\nBOOTSTRAP_REPS = 2000\\nRANDOM_SEED = 20260730\\nMIN_N = 30\\nALPHA = 0.05\\nDPI = 600\\n\\n# 与之前方法一致，默认逐行 Bootstrap。\\n# 若同一 Study_ID 下有多条观测，且希望按文献整组重抽样，可改为 \\\"cluster\\\"。\\nBOOTSTRAP_MODE = \\\"row\\\"  # \\\"row\\\" 或 \\\"cluster\\\"\\n\\nplt.rcParams[\\\"font.family\\\"] = \\\"Times New Roman\\\"\\nplt.rcParams[\\\"mathtext.fontset\\\"] = \\\"stix\\\"\\nplt.rcParams[\\\"axes.unicode_minus\\\"] = False\\nplt.rcParams[\\\"font.size\\\"] = 11\\nwarnings.filterwarnings(\\\"ignore\\\", category=RuntimeWarning)\\n\\n\\n# ============================================================\\n# 2. 路径与协变量设置\\n# ============================================================\\n\\nTREATMENTS = [\\\"SR\\\", \\\"BC\\\", \\\"BS\\\"]\\nGASES = [\\\"N2O\\\", \\\"CO2\\\", \\\"CH4\\\"]\\n\\nMEDIATORS = {\\n    \\\"N2O\\\": [\\\"SOM\\\", \\\"AP\\\", \\\"AK\\\", \\\"pH\\\", \\\"AN\\\"],\\n    \\\"CO2\\\": [\\\"AN\\\", \\\"pH\\\", \\\"SOM\\\", \\\"AK\\\", \\\"AP\\\"],\\n    \\\"CH4\\\": [\\\"AN\\\", \\\"pH\\\", \\\"AK\\\", \\\"SOM\\\"],\\n}\\n\\nBASE_COVARIATES = [\\\"MAT\\\", \\\"MAP\\\", \\\"N_rate\\\", \\\"P_rate\\\", \\\"K_rate\\\"]\\n\\n# 自动识别常见列名；若识别失败，只需在对应列表最前面补上实际列名。\\nALIASES = {\\n    \\\"Study_ID\\\": [\\\"Study_ID\\\", \\\"StudyID\\\", \\\"Study ID\\\", \\\"文献编号\\\"],\\n    \\\"N2O\\\": [\\\"N2O_SLogDiff\\\", \\\"N₂O_SLogDiff\\\", \\\"N2O\\\", \\\"N₂O\\\"],\\n    \\\"CO2\\\": [\\\"CO2_SLogDiff\\\", \\\"CO₂_SLogDiff\\\", \\\"CO2\\\", \\\"CO₂\\\"],\\n    \\\"CH4\\\": [\\\"CH4_SLogDiff\\\", \\\"CH₄_SLogDiff\\\", \\\"CH4\\\", \\\"CH₄\\\"],\\n    \\\"SR\\\": [\\\"SR\\\", \\\"Straw return\\\", \\\"秸秆还田\\\"],\\n    \\\"BC\\\": [\\\"BC\\\", \\\"Biochar\\\", \\\"生物炭\\\"],\\n    \\\"BS\\\": [\\\"BS\\\", \\\"Biogas slurry\\\", \\\"沼液\\\"],\\n    \\\"MAT\\\": [\\\"MAT\\\", \\\"Mean annual temperature\\\", \\\"年均温\\\"],\\n    \\\"MAP\\\": [\\\"MAP\\\", \\\"Mean annual precipitation\\\", \\\"年降水量\\\"],\\n    \\\"N_rate\\\": [\\\"N rate\\\", \\\"N_rate\\\", \\\"N\\\", \\\"施氮量\\\"],\\n    \\\"P_rate\\\": [\\\"P rate\\\", \\\"P_rate\\\", \\\"P\\\", \\\"施磷量\\\"],\\n    \\\"K_rate\\\": [\\\"K rate\\\", \\\"K_rate\\\", \\\"K\\\", \\\"施钾量\\\"],\\n    \\\"AN\\\": [\\\"AN\\\", \\\"Available nitrogen\\\", \\\"碱解氮\\\", \\\"土壤有效氮\\\"],\\n    \\\"AK\\\": [\\\"AK\\\", \\\"Available potassium\\\", \\\"速效钾\\\"],\\n    \\\"AP\\\": [\\\"AP\\\", \\\"Available phosphorus\\\", \\\"速效磷\\\"],\\n    \\\"pH\\\": [\\\"pH\\\", \\\"PH\\\", \\\"Soil pH\\\"],\\n    \\\"SOM\\\": [\\\"SOM\\\", \\\"Soil organic matter\\\", \\\"有机质\\\"],\\n}\\n\\n\\n# ============================================================\\n# 3. 工具函数\\n# ============================================================\\n\\ndef normalize_name(name):\\n    text = str(name).strip().lower()\\n    text = text.replace(\\\"₂\\\", \\\"2\\\").replace(\\\"₄\\\", \\\"4\\\")\\n    return re.sub(r\\\"[\\\\s_\\\\-\\\\(\\\\)\\\\[\\\\]/\\\\\\\\]+\\\", \\\"\\\", text)\\n\\n\\ndef find_column(df, key, required=True):\\n    columns = list(df.columns)\\n\\n    for name in ALIASES[key]:\\n        if name in columns:\\n            return name\\n\\n    lower_map = {str(col).lower(): col for col in columns}\\n    for name in ALIASES[key]:\\n        if str(name).lower() in lower_map:\\n            return lower_map[str(name).lower()]\\n\\n    normalized_map = {normalize_name(col): col for col in columns}\\n    for name in ALIASES[key]:\\n        if normalize_name(name) in normalized_map:\\n            return normalized_map[normalize_name(name)]\\n\\n    if required:\\n        raise KeyError(\\n            f\\\"\\\\n未找到变量 {key}。\\\\n\\\"\\n            f\\\"尝试过的列名：{ALIASES[key]}\\\\n\\\"\\n            f\\\"当前数据列名：{columns}\\\\n\\\"\\n            f\\\"请在 ALIASES['{key}'] 的最前面加入真实列名。\\\"\\n        )\\n    return None\\n\\n\\ndef to_numeric(series):\\n    if pd.api.types.is_numeric_dtype(series):\\n        return pd.to_numeric(series, errors=\\\"coerce\\\")\\n\\n    cleaned = (\\n        series.astype(str)\\n        .str.strip()\\n        .replace({\\n            \\\"\\\": np.nan, \\\"NA\\\": np.nan, \\\"N/A\\\": np.nan,\\n            \\\"na\\\": np.nan, \\\"None\\\": np.nan,\\n            \\\"-\\\": np.nan, \\\"--\\\": np.nan, \\\"—\\\": np.nan,\\n        })\\n        .str.replace(\\\",\\\", \\\"\\\", regex=False)\\n    )\\n    return pd.to_numeric(cleaned, errors=\\\"coerce\\\")\\n\\n\\ndef standardize_complete_data(df, treatment, mediator, gas, covariates):\\n    focal = [treatment, mediator, gas]\\n    sd = df[focal + covariates].std(ddof=0)\\n\\n    for variable in focal:\\n        if pd.isna(sd[variable]) or sd[variable] <= 1e-12:\\n            raise ValueError(f\\\"{variable} 在当前完整样本中没有变异。\\\")\\n\\n    covariates_used = [\\n        cov for cov in covariates\\n        if pd.notna(sd[cov]) and sd[cov] > 1e-12\\n    ]\\n\\n    variables = focal + covariates_used\\n    z = (df[variables] - df[variables].mean()) / df[variables].std(ddof=0)\\n    z = z.replace([np.inf, -np.inf], np.nan).dropna()\\n\\n    return z, covariates_used\\n\\n\\ndef fit_hc3(y, x):\\n    x = sm.add_constant(x, has_constant=\\\"add\\\")\\n    return sm.OLS(y, x).fit(cov_type=\\\"HC3\\\")\\n\\n\\ndef bootstrap_ab(\\n    z,\\n    treatment,\\n    mediator,\\n    gas,\\n    covariates,\\n    reps,\\n    seed,\\n    mode=\\\"row\\\",\\n    clusters=None,\\n):\\n    rng = np.random.default_rng(seed)\\n    n = len(z)\\n\\n    t = z[treatment].to_numpy(float)\\n    m = z[mediator].to_numpy(float)\\n    y = z[gas].to_numpy(float)\\n    c = (\\n        z[covariates].to_numpy(float)\\n        if covariates\\n        else np.empty((n, 0))\\n    )\\n\\n    xa = np.column_stack([np.ones(n), t, c])\\n    xb = np.column_stack([np.ones(n), t, m, c])\\n\\n    if mode == \\\"cluster\\\":\\n        if clusters is None:\\n            raise ValueError(\\\"cluster Bootstrap 需要 Study_ID。\\\")\\n        clusters = np.asarray(clusters).astype(str)\\n        unique_clusters = pd.unique(clusters)\\n        cluster_rows = {\\n            cluster: np.flatnonzero(clusters == cluster)\\n            for cluster in unique_clusters\\n        }\\n\\n    ab_values = []\\n\\n    for _ in range(reps):\\n        if mode == \\\"row\\\":\\n            idx = rng.integers(0, n, n)\\n        elif mode == \\\"cluster\\\":\\n            sampled = rng.choice(\\n                unique_clusters,\\n                size=len(unique_clusters),\\n                replace=True,\\n            )\\n            idx = np.concatenate([cluster_rows[item] for item in sampled])\\n        else:\\n            raise ValueError(\\\"BOOTSTRAP_MODE 只能为 'row' 或 'cluster'。\\\")\\n\\n        try:\\n            beta_a = np.linalg.lstsq(xa[idx], m[idx], rcond=None)[0]\\n            beta_b = np.linalg.lstsq(xb[idx], y[idx], rcond=None)[0]\\n            value = beta_a[1] * beta_b[2]\\n\\n            if np.isfinite(value):\\n                ab_values.append(value)\\n        except np.linalg.LinAlgError:\\n            pass\\n\\n    ab_values = np.asarray(ab_values, dtype=float)\\n\\n    if len(ab_values) < max(100, int(reps * 0.80)):\\n        raise RuntimeError(\\n            f\\\"Bootstrap 仅成功 {len(ab_values)}/{reps} 次。\\\"\\n        )\\n\\n    ci_low, ci_high = np.percentile(\\n        ab_values,\\n        [100 * ALPHA / 2, 100 * (1 - ALPHA / 2)],\\n    )\\n\\n    p_left = (np.sum(ab_values <= 0) + 1) / (len(ab_values) + 1)\\n    p_right = (np.sum(ab_values >= 0) + 1) / (len(ab_values) + 1)\\n    p_boot = min(1.0, 2 * min(p_left, p_right))\\n\\n    return {\\n        \\\"boot_mean\\\": ab_values.mean(),\\n        \\\"boot_se\\\": ab_values.std(ddof=1),\\n        \\\"ci_low\\\": ci_low,\\n        \\\"ci_high\\\": ci_high,\\n        \\\"boot_p\\\": p_boot,\\n        \\\"success\\\": len(ab_values),\\n    }\\n\\n\\ndef mediation_pattern(ab, ci_low, ci_high, direct, direct_p):\\n    indirect_supported = ci_low > 0 or ci_high < 0\\n\\n    if not indirect_supported:\\n        return \\\"No supported indirect effect\\\"\\n    if direct_p >= ALPHA:\\n        return \\\"Indirect-only pattern\\\"\\n    if np.sign(ab) == np.sign(direct):\\n        return \\\"Complementary pattern\\\"\\n    return \\\"Competitive pattern\\\"\\n\\n\\ndef add_fdr(results):\\n    results = results.copy()\\n\\n    results[\\\"FDR_q_global\\\"] = multipletests(\\n        results[\\\"boot_p\\\"],\\n        alpha=ALPHA,\\n        method=\\\"fdr_bh\\\",\\n    )[1]\\n\\n    results[\\\"FDR_q_within_gas\\\"] = np.nan\\n    for gas, index in results.groupby(\\\"Gas\\\").groups.items():\\n        index = list(index)\\n        results.loc[index, \\\"FDR_q_within_gas\\\"] = multipletests(\\n            results.loc[index, \\\"boot_p\\\"],\\n            alpha=ALPHA,\\n            method=\\\"fdr_bh\\\",\\n        )[1]\\n\\n    results[\\\"Supported_CI\\\"] = (\\n        (results[\\\"Indirect_CI_low\\\"] > 0)\\n        | (results[\\\"Indirect_CI_high\\\"] < 0)\\n    )\\n    results[\\\"Supported_FDR_global\\\"] = (\\n        results[\\\"Supported_CI\\\"]\\n        & (results[\\\"FDR_q_global\\\"] < ALPHA)\\n    )\\n    results[\\\"Supported_FDR_within_gas\\\"] = (\\n        results[\\\"Supported_CI\\\"]\\n        & (results[\\\"FDR_q_within_gas\\\"] < ALPHA)\\n    )\\n\\n    return results\\n\\n\\ndef extract_coefficients(model, path_id, model_name):\\n    ci = model.conf_int(alpha=ALPHA)\\n    rows = []\\n\\n    for term in model.params.index:\\n        rows.append({\\n            \\\"Path_ID\\\": path_id,\\n            \\\"Model\\\": model_name,\\n            \\\"Term\\\": term,\\n            \\\"Estimate\\\": model.params[term],\\n            \\\"HC3_SE\\\": model.bse[term],\\n            \\\"p_value\\\": model.pvalues[term],\\n            \\\"CI_low_HC3\\\": ci.loc[term].iloc[0],\\n            \\\"CI_high_HC3\\\": ci.loc[term].iloc[1],\\n            \\\"R2\\\": model.rsquared,\\n            \\\"Adjusted_R2\\\": model.rsquared_adj,\\n            \\\"n\\\": int(model.nobs),\\n        })\\n\\n    return rows\\n\\n\\ndef gas_label(gas):\\n    return {\\\"N2O\\\": \\\"N₂O\\\", \\\"CO2\\\": \\\"CO₂\\\", \\\"CH4\\\": \\\"CH₄\\\"}[gas]\\n\\n\\ndef path_label(treatment, mediator, gas):\\n    return f\\\"{treatment} → {mediator} → {gas_label(gas)}\\\"\\n\\n\\ndef draw_forest_plot(gas_results, save_dir):\\n    gas = gas_results[\\\"Gas\\\"].iloc[0]\\n    treatment_order = {name: i for i, name in enumerate(TREATMENTS)}\\n    mediator_order = {\\n        name: i for i, name in enumerate(MEDIATORS[gas])\\n    }\\n\\n    plot_df = gas_results.copy()\\n    plot_df[\\\"_t\\\"] = plot_df[\\\"Treatment\\\"].map(treatment_order)\\n    plot_df[\\\"_m\\\"] = plot_df[\\\"Mediator\\\"].map(mediator_order)\\n    plot_df = plot_df.sort_values([\\\"_t\\\", \\\"_m\\\"]).reset_index(drop=True)\\n\\n    y = np.arange(len(plot_df))[::-1]\\n    labels = [\\n        path_label(row.Treatment, row.Mediator, gas)\\n        for row in plot_df.itertuples()\\n    ]\\n\\n    fig, ax = plt.subplots(\\n        figsize=(7.2, max(5.0, len(plot_df) * 0.42 + 1.7))\\n    )\\n\\n    for y_pos, row in zip(y, plot_df.itertuples()):\\n        left = row.Indirect_ab - row.Indirect_CI_low\\n        right = row.Indirect_CI_high - row.Indirect_ab\\n\\n        ax.errorbar(\\n            row.Indirect_ab,\\n            y_pos,\\n            xerr=np.array([[left], [right]]),\\n            fmt=\\\"o\\\",\\n            markersize=5.5,\\n            markerfacecolor=\\\"black\\\" if row.Supported_CI else \\\"white\\\",\\n            markeredgecolor=\\\"black\\\",\\n            ecolor=\\\"black\\\",\\n            elinewidth=1.0,\\n            capsize=3,\\n        )\\n\\n    ax.axvline(0, color=\\\"0.35\\\", linestyle=\\\"--\\\", linewidth=0.9)\\n    ax.set_yticks(y)\\n    ax.set_yticklabels(labels)\\n    ax.set_xlabel(\\\"Standardized indirect effect (a × b)\\\")\\n    ax.set_title(f\\\"{gas_label(gas)}: bootstrap indirect effects\\\")\\n    ax.grid(axis=\\\"x\\\", linestyle=\\\":\\\", linewidth=0.5, alpha=0.45)\\n    ax.spines[\\\"top\\\"].set_visible(False)\\n    ax.spines[\\\"right\\\"].set_visible(False)\\n\\n    fig.tight_layout()\\n    fig.savefig(\\n        save_dir / f\\\"{gas}_indirect_effect_forest_600dpi.png\\\",\\n        dpi=DPI,\\n        bbox_inches=\\\"tight\\\",\\n    )\\n    fig.savefig(\\n        save_dir / f\\\"{gas}_indirect_effect_forest_600dpi.tif\\\",\\n        dpi=DPI,\\n        bbox_inches=\\\"tight\\\",\\n    )\\n    plt.close(fig)\\n\\n\\ndef format_excel(file_path):\\n    workbook = load_workbook(file_path)\\n    header_fill = PatternFill(\\\"solid\\\", fgColor=\\\"D9EAF7\\\")\\n\\n    for sheet in workbook.worksheets:\\n        sheet.freeze_panes = \\\"A2\\\"\\n        sheet.auto_filter.ref = sheet.dimensions\\n\\n        for cell in sheet[1]:\\n            cell.font = Font(name=\\\"Times New Roman\\\", bold=True)\\n            cell.fill = header_fill\\n            cell.alignment = Alignment(\\n                horizontal=\\\"center\\\",\\n                vertical=\\\"center\\\",\\n                wrap_text=True,\\n            )\\n\\n        for row in sheet.iter_rows(min_row=2):\\n            for cell in row:\\n                cell.font = Font(name=\\\"Times New Roman\\\")\\n\\n        for column_cells in sheet.columns:\\n            letter = get_column_letter(column_cells[0].column)\\n            max_len = max(\\n                len(str(cell.value)) if cell.value is not None else 0\\n                for cell in column_cells[:300]\\n            )\\n            sheet.column_dimensions[letter].width = min(\\n                max(max_len + 2, 10),\\n                36,\\n            )\\n\\n    workbook.save(file_path)\\n\\n\\n# ============================================================\\n# 4. 读取数据并统一列名\\n# ============================================================\\n\\ndata_path = Path(DATA_FILE)\\nsave_dir = Path(OUTPUT_DIR)\\nsave_dir.mkdir(parents=True, exist_ok=True)\\n\\nif not data_path.exists():\\n    raise FileNotFoundError(\\n        f\\\"找不到数据文件：\\\\n{data_path}\\\\n请修改 DATA_FILE。\\\"\\n    )\\n\\nraw = pd.read_excel(\\n    data_path,\\n    sheet_name=SHEET_NAME,\\n    engine=\\\"openpyxl\\\",\\n)\\nraw.columns = [str(col).strip() for col in raw.columns]\\n\\nrequired_keys = (\\n    GASES\\n    + TREATMENTS\\n    + BASE_COVARIATES\\n    + sorted(set(sum(MEDIATORS.values(), [])))\\n)\\n\\ncolumn_map = {\\n    key: find_column(raw, key, required=True)\\n    for key in required_keys\\n}\\ncolumn_map[\\\"Study_ID\\\"] = find_column(\\n    raw,\\n    \\\"Study_ID\\\",\\n    required=False,\\n)\\n\\ndata = pd.DataFrame(index=raw.index)\\n\\nfor key, actual_column in column_map.items():\\n    if actual_column is None:\\n        continue\\n\\n    if key == \\\"Study_ID\\\":\\n        data[key] = raw[actual_column]\\n    else:\\n        data[key] = to_numeric(raw[actual_column])\\n\\ndata = data.replace([np.inf, -np.inf], np.nan)\\n\\nif BOOTSTRAP_MODE == \\\"cluster\\\" and \\\"Study_ID\\\" not in data.columns:\\n    raise KeyError(\\n        \\\"选择了 cluster Bootstrap，但没有识别到 Study_ID。\\\"\\n    )\\n\\nprint(\\\"=\\\" * 70)\\nprint(\\\"列名对应关系\\\")\\nprint(\\\"=\\\" * 70)\\nfor key, value in column_map.items():\\n    print(f\\\"{key:>9s} -> {value}\\\")\\n\\n\\n# ============================================================\\n# 5. 逐条运行全部 42 条候选路径\\n# ============================================================\\n\\nresult_rows = []\\ncoefficient_rows = []\\nskipped_rows = []\\n\\ntotal_paths = sum(\\n    len(TREATMENTS) * len(MEDIATORS[gas])\\n    for gas in GASES\\n)\\ncounter = 0\\n\\nfor gas in GASES:\\n    for treatment in TREATMENTS:\\n        other_treatments = [\\n            item for item in TREATMENTS\\n            if item != treatment\\n        ]\\n\\n        for mediator in MEDIATORS[gas]:\\n            counter += 1\\n            path_id = f\\\"{gas}_{treatment}_{mediator}\\\"\\n            label = path_label(treatment, mediator, gas)\\n\\n            covariates = BASE_COVARIATES + other_treatments\\n            covariates = [\\n                variable for variable in covariates\\n                if variable not in {gas, treatment, mediator}\\n            ]\\n            covariates = list(dict.fromkeys(covariates))\\n\\n            numeric_variables = [\\n                gas,\\n                treatment,\\n                mediator,\\n            ] + covariates\\n\\n            columns_for_path = numeric_variables.copy()\\n            if BOOTSTRAP_MODE == \\\"cluster\\\":\\n                columns_for_path.append(\\\"Study_ID\\\")\\n\\n            path_data = (\\n                data[columns_for_path]\\n                .replace([np.inf, -np.inf], np.nan)\\n                .dropna()\\n                .copy()\\n            )\\n\\n            print(\\n                f\\\"[{counter:02d}/{total_paths}] \\\"\\n                f\\\"{label} | n = {len(path_data)}\\\"\\n            )\\n\\n            if len(path_data) < MIN_N:\\n                skipped_rows.append({\\n                    \\\"Path_ID\\\": path_id,\\n                    \\\"Path\\\": label,\\n                    \\\"Reason\\\": f\\\"完整样本量 {len(path_data)} < {MIN_N}\\\",\\n                })\\n                continue\\n\\n            try:\\n                z, covariates_used = standardize_complete_data(\\n                    path_data[numeric_variables],\\n                    treatment,\\n                    mediator,\\n                    gas,\\n                    covariates,\\n                )\\n\\n                clusters = None\\n                if BOOTSTRAP_MODE == \\\"cluster\\\":\\n                    clusters = path_data.loc[\\n                        z.index,\\n                        \\\"Study_ID\\\",\\n                    ].astype(str).to_numpy()\\n\\n                # a 路径：M ~ T + C\\n                model_a = fit_hc3(\\n                    z[mediator],\\n                    z[[treatment] + covariates_used],\\n                )\\n\\n                # b 路径和直接效应 c'：Y ~ T + M + C\\n                model_b = fit_hc3(\\n                    z[gas],\\n                    z[[treatment, mediator] + covariates_used],\\n                )\\n\\n                # 总效应 c：Y ~ T + C\\n                model_c = fit_hc3(\\n                    z[gas],\\n                    z[[treatment] + covariates_used],\\n                )\\n\\n                a = model_a.params[treatment]\\n                b = model_b.params[mediator]\\n                c_prime = model_b.params[treatment]\\n                c_total = model_c.params[treatment]\\n                ab = a * b\\n\\n                boot = bootstrap_ab(\\n                    z=z,\\n                    treatment=treatment,\\n                    mediator=mediator,\\n                    gas=gas,\\n                    covariates=covariates_used,\\n                    reps=BOOTSTRAP_REPS,\\n                    seed=RANDOM_SEED + counter * 1009,\\n                    mode=BOOTSTRAP_MODE,\\n                    clusters=clusters,\\n                )\\n\\n                proportion_mediated = np.nan\\n                if (\\n                    abs(c_total) > 1e-8\\n                    and np.sign(ab) == np.sign(c_total)\\n                ):\\n                    proportion_mediated = ab / c_total\\n\\n                result_rows.append({\\n                    \\\"Path_ID\\\": path_id,\\n                    \\\"Path\\\": label,\\n                    \\\"Gas\\\": gas,\\n                    \\\"Treatment\\\": treatment,\\n                    \\\"Mediator\\\": mediator,\\n                    \\\"n\\\": len(z),\\n                    \\\"Covariates\\\": \\\", \\\".join(covariates_used),\\n\\n                    \\\"a_T_to_M\\\": a,\\n                    \\\"a_HC3_SE\\\": model_a.bse[treatment],\\n                    \\\"a_p\\\": model_a.pvalues[treatment],\\n\\n                    \\\"b_M_to_Y\\\": b,\\n                    \\\"b_HC3_SE\\\": model_b.bse[mediator],\\n                    \\\"b_p\\\": model_b.pvalues[mediator],\\n\\n                    \\\"Direct_c_prime\\\": c_prime,\\n                    \\\"Direct_HC3_SE\\\": model_b.bse[treatment],\\n                    \\\"Direct_p\\\": model_b.pvalues[treatment],\\n\\n                    \\\"Total_c\\\": c_total,\\n                    \\\"Total_HC3_SE\\\": model_c.bse[treatment],\\n                    \\\"Total_p\\\": model_c.pvalues[treatment],\\n\\n                    \\\"Indirect_ab\\\": ab,\\n                    \\\"Indirect_boot_mean\\\": boot[\\\"boot_mean\\\"],\\n                    \\\"Indirect_boot_SE\\\": boot[\\\"boot_se\\\"],\\n                    \\\"Indirect_CI_low\\\": boot[\\\"ci_low\\\"],\\n                    \\\"Indirect_CI_high\\\": boot[\\\"ci_high\\\"],\\n                    \\\"boot_p\\\": boot[\\\"boot_p\\\"],\\n                    \\\"Bootstrap_success\\\": boot[\\\"success\\\"],\\n\\n                    \\\"R2_a\\\": model_a.rsquared,\\n                    \\\"R2_b_direct\\\": model_b.rsquared,\\n                    \\\"R2_total\\\": model_c.rsquared,\\n\\n                    \\\"Proportion_mediated\\\": proportion_mediated,\\n                    \\\"Indirect_direction\\\": (\\n                        \\\"Positive\\\" if ab > 0\\n                        else \\\"Negative\\\" if ab < 0\\n                        else \\\"Zero\\\"\\n                    ),\\n                    \\\"Mediation_pattern\\\": mediation_pattern(\\n                        ab,\\n                        boot[\\\"ci_low\\\"],\\n                        boot[\\\"ci_high\\\"],\\n                        c_prime,\\n                        model_b.pvalues[treatment],\\n                    ),\\n                    \\\"Bootstrap_mode\\\": BOOTSTRAP_MODE,\\n                })\\n\\n                coefficient_rows.extend(\\n                    extract_coefficients(\\n                        model_a,\\n                        path_id,\\n                        \\\"a: M ~ T + covariates\\\",\\n                    )\\n                )\\n                coefficient_rows.extend(\\n                    extract_coefficients(\\n                        model_b,\\n                        path_id,\\n                        \\\"b/c': Y ~ T + M + covariates\\\",\\n                    )\\n                )\\n                coefficient_rows.extend(\\n                    extract_coefficients(\\n                        model_c,\\n                        path_id,\\n                        \\\"c: Y ~ T + covariates\\\",\\n                    )\\n                )\\n\\n            except Exception as error:\\n                skipped_rows.append({\\n                    \\\"Path_ID\\\": path_id,\\n                    \\\"Path\\\": label,\\n                    \\\"Reason\\\": str(error),\\n                })\\n                print(f\\\"    跳过：{error}\\\")\\n\\n\\n# ============================================================\\n# 6. 汇总、FDR 校正与正文候选路径筛选\\n# ============================================================\\n\\nif not result_rows:\\n    raise RuntimeError(\\n        \\\"没有任何路径成功运行，请检查数据列名和缺失值。\\\"\\n    )\\n\\nresults = add_fdr(pd.DataFrame(result_rows))\\ncoefficients = pd.DataFrame(coefficient_rows)\\nskipped = pd.DataFrame(skipped_rows)\\n\\ngas_order = {gas: i for i, gas in enumerate(GASES)}\\ntreatment_order = {\\n    treatment: i for i, treatment in enumerate(TREATMENTS)\\n}\\n\\nresults[\\\"_gas_order\\\"] = results[\\\"Gas\\\"].map(gas_order)\\nresults[\\\"_treatment_order\\\"] = results[\\\"Treatment\\\"].map(treatment_order)\\nresults[\\\"_mediator_order\\\"] = results.apply(\\n    lambda row: MEDIATORS[row[\\\"Gas\\\"]].index(row[\\\"Mediator\\\"]),\\n    axis=1,\\n)\\n\\nresults = (\\n    results\\n    .sort_values([\\n        \\\"_gas_order\\\",\\n        \\\"_treatment_order\\\",\\n        \\\"_mediator_order\\\",\\n    ])\\n    .drop(columns=[\\n        \\\"_gas_order\\\",\\n        \\\"_treatment_order\\\",\\n        \\\"_mediator_order\\\",\\n    ])\\n    .reset_index(drop=True)\\n)\\n\\nsupported_ci = results[results[\\\"Supported_CI\\\"]].copy()\\nsupported_fdr_gas = results[\\n    results[\\\"Supported_FDR_within_gas\\\"]\\n].copy()\\nsupported_fdr_global = results[\\n    results[\\\"Supported_FDR_global\\\"]\\n].copy()\\n\\n# 正文图每种气体最多保留 3 条：\\n# 先选气体内 FDR 通过的路径，再补充仅 Bootstrap CI 通过的路径。\\ncandidate_list = []\\n\\nfor gas in GASES:\\n    gas_df = results[results[\\\"Gas\\\"] == gas].copy()\\n\\n    first = gas_df[\\n        gas_df[\\\"Supported_FDR_within_gas\\\"]\\n    ].copy()\\n    first[\\\"Selection_basis\\\"] = \\\"Bootstrap CI + within-gas FDR\\\"\\n\\n    second = gas_df[\\n        gas_df[\\\"Supported_CI\\\"]\\n        & ~gas_df[\\\"Supported_FDR_within_gas\\\"]\\n    ].copy()\\n    second[\\\"Selection_basis\\\"] = \\\"Bootstrap CI only\\\"\\n\\n    selected = pd.concat(\\n        [first, second],\\n        ignore_index=True,\\n    )\\n    selected[\\\"_abs_ab\\\"] = selected[\\\"Indirect_ab\\\"].abs()\\n    selected = (\\n        selected\\n        .sort_values(\\n            [\\\"Selection_basis\\\", \\\"_abs_ab\\\"],\\n            ascending=[True, False],\\n        )\\n        .drop_duplicates(\\\"Path_ID\\\")\\n        .head(3)\\n        .drop(columns=\\\"_abs_ab\\\")\\n    )\\n    candidate_list.append(selected)\\n\\nfigure_candidates = pd.concat(\\n    candidate_list,\\n    ignore_index=True,\\n)\\n\\n\\n# ============================================================\\n# 7. 保存 Excel、CSV 和 600 dpi 森林图\\n# ============================================================\\n\\nsettings = pd.DataFrame({\\n    \\\"Item\\\": [\\n        \\\"Data file\\\",\\n        \\\"Raw rows\\\",\\n        \\\"Bootstrap repetitions\\\",\\n        \\\"Bootstrap mode\\\",\\n        \\\"Minimum complete-case n\\\",\\n        \\\"Regression\\\",\\n        \\\"Indirect-effect CI\\\",\\n        \\\"Multiple testing\\\",\\n        \\\"Standardization\\\",\\n        \\\"Covariates\\\",\\n        \\\"Interpretation\\\",\\n    ],\\n    \\\"Value\\\": [\\n        str(data_path),\\n        len(raw),\\n        BOOTSTRAP_REPS,\\n        BOOTSTRAP_MODE,\\n        MIN_N,\\n        \\\"OLS with HC3 robust standard errors\\\",\\n        \\\"95% percentile bootstrap CI\\\",\\n        \\\"Benjamini-Hochberg FDR\\\",\\n        \\\"Within each pathway complete-case sample\\\",\\n        \\\"MAT, MAP, N rate, P rate, K rate, and other two amendments\\\",\\n        \\\"Exploratory causal mediation; SHAP is not causal evidence\\\",\\n    ],\\n})\\n\\ncolumn_mapping = pd.DataFrame({\\n    \\\"Canonical_variable\\\": list(column_map.keys()),\\n    \\\"Actual_column\\\": list(column_map.values()),\\n})\\n\\ndata_summary = pd.DataFrame([\\n    {\\n        \\\"Variable\\\": column,\\n        \\\"Available_n\\\": int(data[column].notna().sum()),\\n        \\\"Missing_n\\\": int(data[column].isna().sum()),\\n        \\\"Mean\\\": (\\n            data[column].mean()\\n            if column != \\\"Study_ID\\\" else np.nan\\n        ),\\n        \\\"SD\\\": (\\n            data[column].std()\\n            if column != \\\"Study_ID\\\" else np.nan\\n        ),\\n        \\\"Min\\\": (\\n            data[column].min()\\n            if column != \\\"Study_ID\\\" else np.nan\\n        ),\\n        \\\"Max\\\": (\\n            data[column].max()\\n            if column != \\\"Study_ID\\\" else np.nan\\n        ),\\n    }\\n    for column in data.columns\\n])\\n\\nexcel_path = save_dir / OUTPUT_EXCEL\\n\\nwith pd.ExcelWriter(excel_path, engine=\\\"openpyxl\\\") as writer:\\n    results.to_excel(writer, sheet_name=\\\"All_paths\\\", index=False)\\n\\n    for gas in GASES:\\n        results[\\n            results[\\\"Gas\\\"] == gas\\n        ].to_excel(\\n            writer,\\n            sheet_name=gas,\\n            index=False,\\n        )\\n\\n    supported_ci.to_excel(\\n        writer,\\n        sheet_name=\\\"Supported_CI\\\",\\n        index=False,\\n    )\\n    supported_fdr_gas.to_excel(\\n        writer,\\n        sheet_name=\\\"Supported_FDR_gas\\\",\\n        index=False,\\n    )\\n    supported_fdr_global.to_excel(\\n        writer,\\n        sheet_name=\\\"Supported_FDR_global\\\",\\n        index=False,\\n    )\\n    figure_candidates.to_excel(\\n        writer,\\n        sheet_name=\\\"Figure_candidates\\\",\\n        index=False,\\n    )\\n    coefficients.to_excel(\\n        writer,\\n        sheet_name=\\\"All_coefficients\\\",\\n        index=False,\\n    )\\n    skipped.to_excel(\\n        writer,\\n        sheet_name=\\\"Skipped_paths\\\",\\n        index=False,\\n    )\\n    settings.to_excel(\\n        writer,\\n        sheet_name=\\\"Settings\\\",\\n        index=False,\\n    )\\n    column_mapping.to_excel(\\n        writer,\\n        sheet_name=\\\"Column_mapping\\\",\\n        index=False,\\n    )\\n    data_summary.to_excel(\\n        writer,\\n        sheet_name=\\\"Data_summary\\\",\\n        index=False,\\n    )\\n\\nformat_excel(excel_path)\\n\\nresults.to_csv(\\n    save_dir / \\\"mediation_all_paths.csv\\\",\\n    index=False,\\n    encoding=\\\"utf-8-sig\\\",\\n)\\nsupported_ci.to_csv(\\n    save_dir / \\\"mediation_supported_CI.csv\\\",\\n    index=False,\\n    encoding=\\\"utf-8-sig\\\",\\n)\\nfigure_candidates.to_csv(\\n    save_dir / \\\"mediation_figure_candidates.csv\\\",\\n    index=False,\\n    encoding=\\\"utf-8-sig\\\",\\n)\\n\\nfor gas in GASES:\\n    gas_results = results[results[\\\"Gas\\\"] == gas]\\n    if not gas_results.empty:\\n        draw_forest_plot(gas_results, save_dir)\\n\\n\\n# ============================================================\\n# 8. 控制台输出\\n# ============================================================\\n\\nprint(\\\"\\\\n\\\" + \\\"=\\\" * 70)\\nprint(\\\"分析完成\\\")\\nprint(\\\"=\\\" * 70)\\nprint(f\\\"成功运行路径：{len(results)}\\\")\\nprint(f\\\"跳过路径：{len(skipped)}\\\")\\nprint(f\\\"Bootstrap 95% CI 不跨 0：{results['Supported_CI'].sum()}\\\")\\nprint(\\n    \\\"气体内 FDR 通过：\\\"\\n    f\\\"{results['Supported_FDR_within_gas'].sum()}\\\"\\n)\\nprint(f\\\"全局 FDR 通过：{results['Supported_FDR_global'].sum()}\\\")\\nprint(f\\\"结果文件：{excel_path}\\\")\\nprint(f\\\"图片与 CSV 文件夹：{save_dir}\\\")\\n\\nif not supported_ci.empty:\\n    print(\\\"\\\\nBootstrap 95% CI 支持的间接路径：\\\")\\n    print(\\n        supported_ci[\\n            [\\n                \\\"Path\\\",\\n                \\\"n\\\",\\n                \\\"a_T_to_M\\\",\\n                \\\"b_M_to_Y\\\",\\n                \\\"Indirect_ab\\\",\\n                \\\"Indirect_CI_low\\\",\\n                \\\"Indirect_CI_high\\\",\\n                \\\"boot_p\\\",\\n                \\\"FDR_q_within_gas\\\",\\n            ]\\n        ].to_string(\\n            index=False,\\n            float_format=lambda x: f\\\"{x:.4f}\\\",\\n        )\\n    )\\nelse:\\n    print(\\\"\\\\n没有间接效应的 Bootstrap 95% CI 排除 0。\\\")\"},\"plot_paths\":{\"filename\":\"GHG_final_SHAP_supported_mediation_forest_plot.py\",\"source\":\"# ============================================================\\n# 最终SHAP模型约束下的探索性因果中介分析森林图\\n#\\n# 最终机器学习/SHAP模型：\\n#   N2O -> ET\\n#   CO2 -> GBDT\\n#   CH4 -> ET\\n#\\n# 最终作图路径必须同时满足：\\n# 1. 中介变量在对应最终SHAP模型中具有解释意义；\\n# 2. 已在因果中介分析结果文件中实际完成估计；\\n# 3. 间接效应Bootstrap 95% CI不跨0；\\n# 4. 每种气体仅保留少量可解释路径，避免图形拥挤。\\n#\\n# 本代码只筛选和重新绘图，不重新估计中介模型。\\n# A. Single-path effects: standardized beta + HC3 95% CI\\n# B. Indirect effects: a x b + bootstrap 95% CI\\n# ============================================================\\n\\nimport os\\nimport math\\nimport numpy as np\\nimport pandas as pd\\nimport matplotlib.pyplot as plt\\nfrom matplotlib.ticker import FuncFormatter\\n\\n\\n# ============================================================\\n# 0. 文件路径\\n# ============================================================\\n\\nRESULT_DIR = r\\\"E:\\\\温室气体模型\\\\7\\\\因果中介分析_新SHAP\\\"\\nSAVE_DIR = r\\\"E:\\\\温室气体模型\\\\image\\\\7\\\"\\n\\nos.makedirs(SAVE_DIR, exist_ok=True)\\n\\nCANDIDATE_CSV = os.path.join(\\n    RESULT_DIR,\\n    \\\"mediation_figure_candidates.csv\\\"\\n)\\n\\nCANDIDATE_XLSX = os.path.join(\\n    RESULT_DIR,\\n    \\\"探索性因果中介分析_全部路径.xlsx\\\"\\n)\\n\\nOUTPUT_BASENAME = \\\"final_SHAP_supported_mediation_forest_plot\\\"\\n\\nPNG_PATH = os.path.join(\\n    SAVE_DIR,\\n    f\\\"{OUTPUT_BASENAME}_600dpi.png\\\"\\n)\\n\\nTIFF_PATH = os.path.join(\\n    SAVE_DIR,\\n    f\\\"{OUTPUT_BASENAME}_600dpi.tiff\\\"\\n)\\n\\nPDF_PATH = os.path.join(\\n    SAVE_DIR,\\n    f\\\"{OUTPUT_BASENAME}.pdf\\\"\\n)\\n\\nSELECTED_PATHS_CSV = os.path.join(\\n    SAVE_DIR,\\n    \\\"final_SHAP_supported_mediation_paths.csv\\\"\\n)\\n\\n\\n# ============================================================\\n# 1. 全局绘图设置\\n# ============================================================\\n\\nplt.rcParams[\\\"font.family\\\"] = \\\"Times New Roman\\\"\\nplt.rcParams[\\\"mathtext.fontset\\\"] = \\\"stix\\\"\\nplt.rcParams[\\\"axes.unicode_minus\\\"] = False\\n\\nplt.rcParams[\\\"pdf.fonttype\\\"] = 42\\nplt.rcParams[\\\"ps.fonttype\\\"] = 42\\n\\nBLACK = \\\"#000000\\\"\\nZERO_COLOR = \\\"#8C8C8C\\\"\\nSEPARATOR_COLOR = \\\"#D2D2D2\\\"\\n\\n\\n# ============================================================\\n# 2. 读取结果\\n# ============================================================\\n\\ndef load_candidate_dataframe():\\n    \\\"\\\"\\\"\\n    优先读取CSV。\\n    如果CSV不存在，则从Excel中的Figure_candidates工作表读取。\\n    \\\"\\\"\\\"\\n\\n    if os.path.exists(CANDIDATE_CSV):\\n        print(f\\\"Reading: {CANDIDATE_CSV}\\\")\\n        return pd.read_csv(CANDIDATE_CSV)\\n\\n    if os.path.exists(CANDIDATE_XLSX):\\n        print(f\\\"Reading: {CANDIDATE_XLSX}\\\")\\n\\n        excel_file = pd.ExcelFile(CANDIDATE_XLSX)\\n\\n        possible_sheets = [\\n            \\\"Figure_candidates\\\",\\n            \\\"Figure candidates\\\",\\n            \\\"figure_candidates\\\",\\n            \\\"Candidates\\\"\\n        ]\\n\\n        matched_sheet = None\\n\\n        for sheet in possible_sheets:\\n            if sheet in excel_file.sheet_names:\\n                matched_sheet = sheet\\n                break\\n\\n        if matched_sheet is None:\\n            raise KeyError(\\n                \\\"Excel文件中未找到Figure_candidates工作表。\\\\n\\\"\\n                f\\\"现有工作表：{excel_file.sheet_names}\\\"\\n            )\\n\\n        return pd.read_excel(\\n            CANDIDATE_XLSX,\\n            sheet_name=matched_sheet\\n        )\\n\\n    raise FileNotFoundError(\\n        \\\"未找到因果中介分析候选路径文件：\\\\n\\\"\\n        f\\\"{CANDIDATE_CSV}\\\\n\\\"\\n        f\\\"{CANDIDATE_XLSX}\\\"\\n    )\\n\\n\\ndf = load_candidate_dataframe()\\n\\n\\n# ============================================================\\n# 3. 检查数据列\\n# ============================================================\\n\\nrequired_columns = [\\n    \\\"Path\\\",\\n    \\\"Gas\\\",\\n    \\\"Treatment\\\",\\n    \\\"Mediator\\\",\\n    \\\"a_T_to_M\\\",\\n    \\\"a_HC3_SE\\\",\\n    \\\"a_p\\\",\\n    \\\"b_M_to_Y\\\",\\n    \\\"b_HC3_SE\\\",\\n    \\\"b_p\\\",\\n    \\\"Indirect_ab\\\",\\n    \\\"Indirect_CI_low\\\",\\n    \\\"Indirect_CI_high\\\"\\n]\\n\\nmissing_columns = [\\n    column\\n    for column in required_columns\\n    if column not in df.columns\\n]\\n\\nif missing_columns:\\n    raise KeyError(\\n        f\\\"结果文件缺少以下必要列：{missing_columns}\\\"\\n    )\\n\\ndf = df.copy()\\n\\nnumeric_columns = [\\n    \\\"a_T_to_M\\\",\\n    \\\"a_HC3_SE\\\",\\n    \\\"a_p\\\",\\n    \\\"b_M_to_Y\\\",\\n    \\\"b_HC3_SE\\\",\\n    \\\"b_p\\\",\\n    \\\"Indirect_ab\\\",\\n    \\\"Indirect_CI_low\\\",\\n    \\\"Indirect_CI_high\\\"\\n]\\n\\nfor column in numeric_columns:\\n    df[column] = pd.to_numeric(\\n        df[column],\\n        errors=\\\"coerce\\\"\\n    )\\n\\ndf = df.dropna(\\n    subset=[\\n        \\\"Gas\\\",\\n        \\\"Treatment\\\",\\n        \\\"Mediator\\\",\\n        \\\"Indirect_ab\\\",\\n        \\\"Indirect_CI_low\\\",\\n        \\\"Indirect_CI_high\\\"\\n    ]\\n).copy()\\n\\nif df.empty:\\n    raise ValueError(\\n        \\\"候选路径结果为空，无法绘图。\\\"\\n    )\\n\\n\\n# ============================================================\\n# 4. 最终模型与最终路径筛选\\n# ============================================================\\n\\n# 最终用于SHAP解释的模型。这里只用于记录和核对，\\n# 不参与中介效应数值计算。\\nFINAL_SHAP_MODELS = {\\n    \\\"N2O\\\": \\\"ET\\\",\\n    \\\"CO2\\\": \\\"GBDT\\\",\\n    \\\"CH4\\\": \\\"ET\\\",\\n}\\n\\n# 最终路径清单。\\n# 这些路径在当前结果文件中已有完整估计，且对应的中介变量\\n# 与最终SHAP结果一致。不要仅因为某变量SHAP排名较高，\\n# 就在未重新估计中介模型的情况下把新路径直接加到图中。\\nFINAL_PATH_ORDER = [\\n    # N2O：SOM和AK均为最终ET模型中的重要土壤变量\\n    (\\\"N2O\\\", \\\"BS\\\", \\\"SOM\\\"),\\n    (\\\"N2O\\\", \\\"BS\\\", \\\"AK\\\"),\\n    (\\\"N2O\\\", \\\"SR\\\", \\\"AK\\\"),\\n\\n    # CO2：AK、AN和pH均在最终GBDT模型中具有解释意义\\n    (\\\"CO2\\\", \\\"SR\\\", \\\"AK\\\"),\\n    (\\\"CO2\\\", \\\"BS\\\", \\\"AN\\\"),\\n    (\\\"CO2\\\", \\\"BC\\\", \\\"pH\\\"),\\n\\n    # CH4：AN和SOM均为最终ET模型中的候选土壤变量\\n    (\\\"CH4\\\", \\\"BS\\\", \\\"AN\\\"),\\n    (\\\"CH4\\\", \\\"BC\\\", \\\"SOM\\\"),\\n]\\n\\n# 是否仅保留Bootstrap 95% CI不跨0的间接效应。\\n# 正式结果图建议保持True。\\nREQUIRE_SIGNIFICANT_INDIRECT = True\\n\\n\\ndef normalize_path_token(value):\\n    \\\"\\\"\\\"统一Gas、Treatment和Mediator字符串格式。\\\"\\\"\\\"\\n\\n    return str(value).strip().replace(\\\"₂\\\", \\\"2\\\").replace(\\\"₄\\\", \\\"4\\\")\\n\\n\\ndf[\\\"Gas\\\"] = df[\\\"Gas\\\"].map(normalize_path_token)\\ndf[\\\"Treatment\\\"] = df[\\\"Treatment\\\"].map(normalize_path_token)\\ndf[\\\"Mediator\\\"] = df[\\\"Mediator\\\"].map(normalize_path_token)\\n\\ndf[\\\"_path_key\\\"] = list(\\n    zip(\\n        df[\\\"Gas\\\"],\\n        df[\\\"Treatment\\\"],\\n        df[\\\"Mediator\\\"],\\n    )\\n)\\n\\nfinal_path_rank = {\\n    path_key: rank\\n    for rank, path_key in enumerate(FINAL_PATH_ORDER)\\n}\\n\\nmissing_final_paths = [\\n    path_key\\n    for path_key in FINAL_PATH_ORDER\\n    if path_key not in set(df[\\\"_path_key\\\"])\\n]\\n\\nif missing_final_paths:\\n    missing_text = \\\"\\\\n\\\".join(\\n        f\\\"  {gas}: {treatment} -> {mediator} -> {gas}\\\"\\n        for gas, treatment, mediator in missing_final_paths\\n    )\\n\\n    raise KeyError(\\n        \\\"结果文件中缺少以下最终路径，不能只通过绘图代码补出来：\\\\n\\\"\\n        + missing_text\\n        + \\\"\\\\n请先重新运行因果中介分析，生成这些路径的估计结果。\\\"\\n    )\\n\\ndf = df.loc[\\n    df[\\\"_path_key\\\"].isin(FINAL_PATH_ORDER)\\n].copy()\\n\\nif REQUIRE_SIGNIFICANT_INDIRECT:\\n    significant_mask = (\\n        (df[\\\"Indirect_CI_low\\\"] > 0)\\n        | (df[\\\"Indirect_CI_high\\\"] < 0)\\n    )\\n\\n    excluded_non_significant = df.loc[\\n        ~significant_mask,\\n        [\\n            \\\"Gas\\\",\\n            \\\"Treatment\\\",\\n            \\\"Mediator\\\",\\n            \\\"Indirect_ab\\\",\\n            \\\"Indirect_CI_low\\\",\\n            \\\"Indirect_CI_high\\\",\\n        ],\\n    ].copy()\\n\\n    if not excluded_non_significant.empty:\\n        print(\\n            \\\"以下预设路径的Bootstrap 95% CI跨0，\\\"\\n            \\\"已从正式结果图中排除：\\\"\\n        )\\n        print(excluded_non_significant.to_string(index=False))\\n\\n    df = df.loc[significant_mask].copy()\\n\\nif df.empty:\\n    raise ValueError(\\n        \\\"应用最终SHAP路径和间接效应显著性条件后，\\\"\\n        \\\"没有可绘制路径。\\\"\\n    )\\n\\ndf[\\\"_final_path_rank\\\"] = df[\\\"_path_key\\\"].map(final_path_rank)\\ndf = df.sort_values(\\\"_final_path_rank\\\").reset_index(drop=True)\\n\\n# 保存最终实际用于绘图的路径和数值，便于论文核对。\\ndf.to_csv(\\n    SELECTED_PATHS_CSV,\\n    index=False,\\n    encoding=\\\"utf-8-sig\\\",\\n)\\n\\nprint(\\\"=\\\" * 90)\\nprint(\\\"最终SHAP模型：\\\")\\nfor gas_name, model_name in FINAL_SHAP_MODELS.items():\\n    print(f\\\"  {gas_name}: {model_name}\\\")\\n\\nprint(\\\"\\\\n最终纳入森林图的中介路径：\\\")\\nfor _, selected_row in df.iterrows():\\n    print(\\n        f'  {selected_row[\\\"Gas\\\"]}: '\\n        f'{selected_row[\\\"Treatment\\\"]} -> '\\n        f'{selected_row[\\\"Mediator\\\"]} -> '\\n        f'{selected_row[\\\"Gas\\\"]}; '\\n        f'a*b={selected_row[\\\"Indirect_ab\\\"]:.3f}, '\\n        f'95% CI=({selected_row[\\\"Indirect_CI_low\\\"]:.3f}, '\\n        f'{selected_row[\\\"Indirect_CI_high\\\"]:.3f})'\\n    )\\nprint(\\\"=\\\" * 90)\\n\\n\\n# ============================================================\\n# 5. 气体名称和排列顺序\\n# ============================================================\\n\\ngas_order = [\\n    \\\"N2O\\\",\\n    \\\"CO2\\\",\\n    \\\"CH4\\\"\\n]\\n\\ngas_unicode = {\\n    \\\"N2O\\\": \\\"N₂O\\\",\\n    \\\"CO2\\\": \\\"CO₂\\\",\\n    \\\"CH4\\\": \\\"CH₄\\\"\\n}\\n\\ngas_heading = {\\n    \\\"N2O\\\": r\\\"Pathways related to N$_2$O emission\\\",\\n    \\\"CO2\\\": r\\\"Pathways related to CO$_2$ emission\\\",\\n    \\\"CH4\\\": r\\\"Pathways related to CH$_4$ emission\\\"\\n}\\n\\ndf[\\\"Gas\\\"] = pd.Categorical(\\n    df[\\\"Gas\\\"].astype(str),\\n    categories=gas_order,\\n    ordered=True\\n)\\n\\n# 保留FINAL_PATH_ORDER中规定的组内顺序。\\ndf = df.sort_values(\\n    by=[\\\"Gas\\\", \\\"_final_path_rank\\\"]\\n).reset_index(drop=True)\\n\\n\\n# ============================================================\\n# 5. 辅助函数\\n# ============================================================\\n\\ndef format_axis_tick(value, position):\\n    \\\"\\\"\\\"\\n    横坐标刻度格式。\\n    \\\"\\\"\\\"\\n\\n    if abs(value) < 1e-10:\\n        return \\\"0\\\"\\n\\n    if abs(value) >= 1:\\n        return f\\\"{value:.1f}\\\"\\n\\n    return f\\\"{value:.2f}\\\"\\n\\n\\ndef format_ci_value(value):\\n    \\\"\\\"\\\"\\n    置信区间格式。\\n    \\\"\\\"\\\"\\n\\n    if 0 < abs(value) < 0.001:\\n        return f\\\"{value:.4f}\\\"\\n\\n    return f\\\"{value:.3f}\\\"\\n\\n\\ndef format_p_value(value):\\n    \\\"\\\"\\\"\\n    p值格式。\\n    \\\"\\\"\\\"\\n\\n    if pd.isna(value):\\n        return \\\"NA\\\"\\n\\n    if value < 0.0001:\\n        return \\\"<0.0001\\\"\\n\\n    return f\\\"{value:.4f}\\\"\\n\\n\\ndef nice_limits(values, expand_ratio=0.12, min_expand=0.05):\\n    \\\"\\\"\\\"\\n    根据置信区间自动确定横坐标范围。\\n    \\\"\\\"\\\"\\n\\n    values = np.asarray(values, dtype=float)\\n    values = values[np.isfinite(values)]\\n\\n    if len(values) == 0:\\n        return -1.0, 1.0\\n\\n    value_min = np.min(values)\\n    value_max = np.max(values)\\n\\n    if math.isclose(value_min, value_max):\\n        delta = max(\\n            abs(value_min) * 0.20,\\n            min_expand\\n        )\\n\\n        value_min -= delta\\n        value_max += delta\\n\\n    value_span = value_max - value_min\\n\\n    expand_value = max(\\n        value_span * expand_ratio,\\n        min_expand\\n    )\\n\\n    x_min = value_min - expand_value\\n    x_max = value_max + expand_value\\n\\n    # 保证零点在横坐标范围内\\n    x_min = min(x_min, 0.0)\\n    x_max = max(x_max, 0.0)\\n\\n    max_absolute = max(\\n        abs(x_min),\\n        abs(x_max)\\n    )\\n\\n    if max_absolute >= 1.5:\\n        step = 0.5\\n    elif max_absolute >= 0.8:\\n        step = 0.2\\n    else:\\n        step = 0.1\\n\\n    x_min = math.floor(x_min / step) * step\\n    x_max = math.ceil(x_max / step) * step\\n\\n    if math.isclose(x_min, x_max):\\n        x_min -= step\\n        x_max += step\\n\\n    return x_min, x_max\\n\\n\\ndef make_ticks(x_min, x_max, target_number=6):\\n    \\\"\\\"\\\"\\n    自动生成横坐标刻度。\\n    \\\"\\\"\\\"\\n\\n    ticks = np.linspace(\\n        x_min,\\n        x_max,\\n        target_number\\n    )\\n\\n    if max(abs(x_min), abs(x_max)) >= 1:\\n        ticks = np.round(ticks, 1)\\n    else:\\n        ticks = np.round(ticks, 2)\\n\\n    return ticks\\n\\n\\ndef draw_forest_item(\\n    axis,\\n    y,\\n    estimate,\\n    low,\\n    high,\\n    marker=\\\"D\\\",\\n    marker_size=6.1,\\n    line_width=1.45,\\n    cap_height=0.085\\n):\\n    \\\"\\\"\\\"\\n    绘制点估计、置信区间和端帽。\\n    \\\"\\\"\\\"\\n\\n    axis.hlines(\\n        y=y,\\n        xmin=low,\\n        xmax=high,\\n        color=BLACK,\\n        linewidth=line_width,\\n        zorder=2\\n    )\\n\\n    axis.vlines(\\n        x=[low, high],\\n        ymin=y - cap_height,\\n        ymax=y + cap_height,\\n        color=BLACK,\\n        linewidth=0.9,\\n        zorder=2\\n    )\\n\\n    axis.plot(\\n        estimate,\\n        y,\\n        marker=marker,\\n        markersize=marker_size,\\n        markerfacecolor=BLACK,\\n        markeredgecolor=BLACK,\\n        markeredgewidth=0.8,\\n        linestyle=\\\"None\\\",\\n        zorder=3\\n    )\\n\\n\\ndef setup_text_axis(axis, y_min, y_max):\\n    \\\"\\\"\\\"\\n    设置路径、数值和p值文字列。\\n    \\\"\\\"\\\"\\n\\n    axis.set_xlim(0, 1)\\n    axis.set_ylim(y_min, y_max)\\n    axis.axis(\\\"off\\\")\\n\\n\\ndef setup_forest_axis(\\n    axis,\\n    x_min,\\n    x_max,\\n    x_ticks,\\n    x_label,\\n    y_min,\\n    y_max\\n):\\n    \\\"\\\"\\\"\\n    设置森林图坐标轴。\\n    \\\"\\\"\\\"\\n\\n    axis.set_xlim(x_min, x_max)\\n    axis.set_ylim(y_min, y_max)\\n\\n    axis.axvline(\\n        x=0,\\n        color=ZERO_COLOR,\\n        linestyle=(0, (4, 4)),\\n        linewidth=1.0,\\n        zorder=0\\n    )\\n\\n    axis.set_xticks(x_ticks)\\n\\n    axis.xaxis.set_major_formatter(\\n        FuncFormatter(format_axis_tick)\\n    )\\n\\n    axis.set_xlabel(\\n        x_label,\\n        fontsize=11.3,\\n        color=BLACK,\\n        labelpad=3\\n    )\\n\\n    axis.set_yticks([])\\n\\n    axis.spines[\\\"top\\\"].set_visible(False)\\n    axis.spines[\\\"right\\\"].set_visible(False)\\n    axis.spines[\\\"left\\\"].set_visible(False)\\n\\n    axis.spines[\\\"bottom\\\"].set_color(BLACK)\\n    axis.spines[\\\"bottom\\\"].set_linewidth(0.9)\\n\\n    axis.tick_params(\\n        axis=\\\"x\\\",\\n        labelsize=10.2,\\n        colors=BLACK,\\n        length=4,\\n        width=0.8,\\n        pad=2\\n    )\\n\\n\\ndef draw_header_line(axis, y, x_start, x_end):\\n    \\\"\\\"\\\"\\n    绘制表头横线。\\n    \\\"\\\"\\\"\\n\\n    axis.hlines(\\n        y=y,\\n        xmin=x_start,\\n        xmax=x_end,\\n        color=BLACK,\\n        linewidth=0.8\\n    )\\n\\n\\ndef draw_separator_line(axis, y, x_start, x_end):\\n    \\\"\\\"\\\"\\n    绘制气体组之间的灰色分隔线。\\n    \\\"\\\"\\\"\\n\\n    axis.hlines(\\n        y=y,\\n        xmin=x_start,\\n        xmax=x_end,\\n        color=SEPARATOR_COLOR,\\n        linewidth=0.8\\n    )\\n\\n\\n# ============================================================\\n# 6. 构建A图数据\\n# ============================================================\\n\\nA_grouped_rows = {}\\n\\nfor gas in gas_order:\\n\\n    gas_dataframe = df[\\n        df[\\\"Gas\\\"].astype(str) == gas\\n    ].copy()\\n\\n    if gas_dataframe.empty:\\n        continue\\n\\n    gas_rows = []\\n    seen_paths = set()\\n\\n    for _, row in gas_dataframe.iterrows():\\n\\n        # ----------------------------------------------------\\n        # a路径：Treatment -> Mediator\\n        # ----------------------------------------------------\\n\\n        a_path_label = (\\n            f'{row[\\\"Treatment\\\"]} → {row[\\\"Mediator\\\"]}'\\n        )\\n\\n        a_path_key = (\\n            \\\"a\\\",\\n            a_path_label\\n        )\\n\\n        if a_path_key not in seen_paths:\\n\\n            a_beta = float(row[\\\"a_T_to_M\\\"])\\n            a_se = float(row[\\\"a_HC3_SE\\\"])\\n\\n            a_low = a_beta - 1.96 * a_se\\n            a_high = a_beta + 1.96 * a_se\\n\\n            gas_rows.append(\\n                {\\n                    \\\"type\\\": \\\"data\\\",\\n                    \\\"path\\\": a_path_label,\\n                    \\\"beta\\\": a_beta,\\n                    \\\"low\\\": a_low,\\n                    \\\"high\\\": a_high,\\n                    \\\"p\\\": float(row[\\\"a_p\\\"])\\n                }\\n            )\\n\\n            seen_paths.add(a_path_key)\\n\\n        # ----------------------------------------------------\\n        # b路径：Mediator -> Gas\\n        # ----------------------------------------------------\\n\\n        b_path_label = (\\n            f'{row[\\\"Mediator\\\"]} → {gas_unicode[gas]}'\\n        )\\n\\n        b_path_key = (\\n            \\\"b\\\",\\n            b_path_label\\n        )\\n\\n        if b_path_key not in seen_paths:\\n\\n            b_beta = float(row[\\\"b_M_to_Y\\\"])\\n            b_se = float(row[\\\"b_HC3_SE\\\"])\\n\\n            b_low = b_beta - 1.96 * b_se\\n            b_high = b_beta + 1.96 * b_se\\n\\n            gas_rows.append(\\n                {\\n                    \\\"type\\\": \\\"data\\\",\\n                    \\\"path\\\": b_path_label,\\n                    \\\"beta\\\": b_beta,\\n                    \\\"low\\\": b_low,\\n                    \\\"high\\\": b_high,\\n                    \\\"p\\\": float(row[\\\"b_p\\\"])\\n                }\\n            )\\n\\n            seen_paths.add(b_path_key)\\n\\n    if gas_rows:\\n        A_grouped_rows[gas] = gas_rows\\n\\n\\n# ------------------------------------------------------------\\n# 设置A图纵坐标\\n# ------------------------------------------------------------\\n\\nrows_A = []\\nA_separator_positions = []\\n\\npresent_A_gases = [\\n    gas\\n    for gas in gas_order\\n    if gas in A_grouped_rows\\n]\\n\\nA_total_rows = sum(\\n    1 + len(A_grouped_rows[gas])\\n    for gas in present_A_gases\\n)\\n\\ncurrent_y = float(A_total_rows) + 0.35\\n\\nfor gas_index, gas in enumerate(present_A_gases):\\n\\n    rows_A.append(\\n        {\\n            \\\"type\\\": \\\"group\\\",\\n            \\\"label\\\": gas_heading[gas],\\n            \\\"y\\\": current_y\\n        }\\n    )\\n\\n    current_y -= 1.0\\n\\n    for row in A_grouped_rows[gas]:\\n\\n        row_copy = row.copy()\\n        row_copy[\\\"y\\\"] = current_y\\n\\n        rows_A.append(row_copy)\\n\\n        current_y -= 1.0\\n\\n    if gas_index < len(present_A_gases) - 1:\\n\\n        A_separator_positions.append(\\n            current_y + 0.50\\n        )\\n\\n\\nA_y_values = [\\n    row[\\\"y\\\"]\\n    for row in rows_A\\n]\\n\\nA_Y_MIN = min(A_y_values) - 0.75\\nA_Y_MAX = max(A_y_values) + 0.90\\n\\nA_effect_values = []\\n\\nfor row in rows_A:\\n\\n    if row[\\\"type\\\"] == \\\"data\\\":\\n\\n        A_effect_values.extend(\\n            [\\n                row[\\\"low\\\"],\\n                row[\\\"high\\\"]\\n            ]\\n        )\\n\\nA_X_MIN, A_X_MAX = nice_limits(\\n    A_effect_values,\\n    expand_ratio=0.12,\\n    min_expand=0.08\\n)\\n\\nA_X_TICKS = make_ticks(\\n    A_X_MIN,\\n    A_X_MAX,\\n    target_number=6\\n)\\n\\n\\n# ============================================================\\n# 7. 构建B图数据\\n# ============================================================\\n\\nrows_B = []\\nB_separator_positions = []\\n\\nB_total_rows = len(df)\\ncurrent_y = float(B_total_rows) + 0.35\\n\\npresent_B_gases = [\\n    gas\\n    for gas in gas_order\\n    if not df[df[\\\"Gas\\\"].astype(str) == gas].empty\\n]\\n\\nfor gas_index, gas in enumerate(present_B_gases):\\n\\n    gas_dataframe = df[\\n        df[\\\"Gas\\\"].astype(str) == gas\\n    ].copy()\\n\\n    for _, row in gas_dataframe.iterrows():\\n\\n        rows_B.append(\\n            {\\n                \\\"gas\\\": gas,\\n                \\\"path\\\": (\\n                    f'{row[\\\"Treatment\\\"]} → '\\n                    f'{row[\\\"Mediator\\\"]} → '\\n                    f'{gas_unicode[gas]}'\\n                ),\\n                \\\"ab\\\": float(row[\\\"Indirect_ab\\\"]),\\n                \\\"low\\\": float(row[\\\"Indirect_CI_low\\\"]),\\n                \\\"high\\\": float(row[\\\"Indirect_CI_high\\\"]),\\n                \\\"y\\\": current_y\\n            }\\n        )\\n\\n        current_y -= 1.0\\n\\n    if gas_index < len(present_B_gases) - 1:\\n\\n        B_separator_positions.append(\\n            current_y + 0.50\\n        )\\n\\n\\nB_y_values = [\\n    row[\\\"y\\\"]\\n    for row in rows_B\\n]\\n\\nB_Y_MIN = min(B_y_values) - 0.75\\nB_Y_MAX = max(B_y_values) + 0.90\\n\\nB_effect_values = []\\n\\nfor row in rows_B:\\n\\n    B_effect_values.extend(\\n        [\\n            row[\\\"low\\\"],\\n            row[\\\"high\\\"]\\n        ]\\n    )\\n\\nB_X_MIN, B_X_MAX = nice_limits(\\n    B_effect_values,\\n    expand_ratio=0.12,\\n    min_expand=0.05\\n)\\n\\nB_X_TICKS = make_ticks(\\n    B_X_MIN,\\n    B_X_MAX,\\n    target_number=6\\n)\\n\\n\\n# ============================================================\\n# 8. 创建画布\\n# ============================================================\\n\\nnumber_A_rows = len(rows_A)\\nnumber_B_rows = len(rows_B)\\n\\nA_panel_height = max(\\n    6.8,\\n    number_A_rows * 0.43\\n)\\n\\nB_panel_height = max(\\n    4.3,\\n    number_B_rows * 0.54\\n)\\n\\nfigure_height = (\\n    A_panel_height\\n    + B_panel_height\\n    + 2.2\\n)\\n\\nfig = plt.figure(\\n    figsize=(14.5, figure_height),\\n    facecolor=\\\"white\\\"\\n)\\n\\n# ------------------------------------------------------------\\n# 最外层分为：\\n# 0：A标题\\n# 1：A图\\n# 2：空白间隔\\n# 3：B标题\\n# 4：B图\\n# ------------------------------------------------------------\\n\\nouter_grid = fig.add_gridspec(\\n    nrows=5,\\n    ncols=1,\\n    height_ratios=[\\n        0.65,\\n        A_panel_height,\\n        0.85,\\n        0.65,\\n        B_panel_height\\n    ],\\n    left=0.045,\\n    right=0.985,\\n    top=0.985,\\n    bottom=0.055,\\n    hspace=0.02\\n)\\n\\n\\n# ============================================================\\n# 9. A图标题\\n# ============================================================\\n\\nax_A_title = fig.add_subplot(\\n    outer_grid[0, 0]\\n)\\n\\nax_A_title.axis(\\\"off\\\")\\n\\nax_A_title.text(\\n    0.002,\\n    0.55,\\n    r\\\"A. Single-path effects \\\"\\n    r\\\"(standardized $\\\\beta$, HC3 95% CI)\\\",\\n    fontsize=15,\\n    fontweight=\\\"bold\\\",\\n    color=BLACK,\\n    ha=\\\"left\\\",\\n    va=\\\"center\\\",\\n    transform=ax_A_title.transAxes\\n)\\n\\n\\n# ============================================================\\n# 10. A图主体\\n# ============================================================\\n\\nA_grid = outer_grid[1, 0].subgridspec(\\n    nrows=1,\\n    ncols=20,\\n    wspace=0.06\\n)\\n\\nax_A_path = fig.add_subplot(\\n    A_grid[0, 0:5]\\n)\\n\\nax_A_plot = fig.add_subplot(\\n    A_grid[0, 5:12],\\n    sharey=ax_A_path\\n)\\n\\nax_A_beta = fig.add_subplot(\\n    A_grid[0, 12:17],\\n    sharey=ax_A_path\\n)\\n\\nax_A_p = fig.add_subplot(\\n    A_grid[0, 17:20],\\n    sharey=ax_A_path\\n)\\n\\nsetup_text_axis(\\n    ax_A_path,\\n    A_Y_MIN,\\n    A_Y_MAX\\n)\\n\\nsetup_text_axis(\\n    ax_A_beta,\\n    A_Y_MIN,\\n    A_Y_MAX\\n)\\n\\nsetup_text_axis(\\n    ax_A_p,\\n    A_Y_MIN,\\n    A_Y_MAX\\n)\\n\\nsetup_forest_axis(\\n    axis=ax_A_plot,\\n    x_min=A_X_MIN,\\n    x_max=A_X_MAX,\\n    x_ticks=A_X_TICKS,\\n    x_label=r\\\"Standardized $\\\\beta$\\\",\\n    y_min=A_Y_MIN,\\n    y_max=A_Y_MAX\\n)\\n\\n\\n# ------------------------------------------------------------\\n# A图表头\\n# ------------------------------------------------------------\\n\\nA_HEADER_Y = A_Y_MAX - 0.30\\nA_HEADER_LINE_Y = A_HEADER_Y - 0.22\\n\\nax_A_path.text(\\n    0.01,\\n    A_HEADER_Y,\\n    \\\"Pathway\\\",\\n    fontsize=11.8,\\n    fontweight=\\\"bold\\\",\\n    color=BLACK,\\n    va=\\\"bottom\\\"\\n)\\n\\nax_A_beta.text(\\n    0.01,\\n    A_HEADER_Y,\\n    r\\\"$\\\\beta$ (95% CI)\\\",\\n    fontsize=11.8,\\n    fontweight=\\\"bold\\\",\\n    color=BLACK,\\n    va=\\\"bottom\\\"\\n)\\n\\nax_A_p.text(\\n    0.02,\\n    A_HEADER_Y,\\n    r\\\"$p$ value\\\",\\n    fontsize=11.8,\\n    fontweight=\\\"bold\\\",\\n    color=BLACK,\\n    va=\\\"bottom\\\"\\n)\\n\\ndraw_header_line(\\n    ax_A_path,\\n    A_HEADER_LINE_Y,\\n    0,\\n    1\\n)\\n\\ndraw_header_line(\\n    ax_A_plot,\\n    A_HEADER_LINE_Y,\\n    A_X_MIN,\\n    A_X_MAX\\n)\\n\\ndraw_header_line(\\n    ax_A_beta,\\n    A_HEADER_LINE_Y,\\n    0,\\n    1\\n)\\n\\ndraw_header_line(\\n    ax_A_p,\\n    A_HEADER_LINE_Y,\\n    0,\\n    1\\n)\\n\\n\\n# ------------------------------------------------------------\\n# A图气体分隔线\\n# ------------------------------------------------------------\\n\\nfor separator_y in A_separator_positions:\\n\\n    draw_separator_line(\\n        ax_A_path,\\n        separator_y,\\n        0,\\n        1\\n    )\\n\\n    draw_separator_line(\\n        ax_A_plot,\\n        separator_y,\\n        A_X_MIN,\\n        A_X_MAX\\n    )\\n\\n    draw_separator_line(\\n        ax_A_beta,\\n        separator_y,\\n        0,\\n        1\\n    )\\n\\n    draw_separator_line(\\n        ax_A_p,\\n        separator_y,\\n        0,\\n        1\\n    )\\n\\n\\n# ------------------------------------------------------------\\n# 绘制A图\\n# ------------------------------------------------------------\\n\\nfor row in rows_A:\\n\\n    if row[\\\"type\\\"] == \\\"group\\\":\\n\\n        ax_A_path.text(\\n            0.01,\\n            row[\\\"y\\\"],\\n            row[\\\"label\\\"],\\n            fontsize=11.6,\\n            fontweight=\\\"bold\\\",\\n            color=BLACK,\\n            va=\\\"center\\\"\\n        )\\n\\n    else:\\n\\n        ax_A_path.text(\\n            0.01,\\n            row[\\\"y\\\"],\\n            row[\\\"path\\\"],\\n            fontsize=11.0,\\n            color=BLACK,\\n            va=\\\"center\\\"\\n        )\\n\\n        draw_forest_item(\\n            axis=ax_A_plot,\\n            y=row[\\\"y\\\"],\\n            estimate=row[\\\"beta\\\"],\\n            low=row[\\\"low\\\"],\\n            high=row[\\\"high\\\"]\\n        )\\n\\n        beta_ci_text = (\\n            f'{row[\\\"beta\\\"]:.3f} '\\n            f'({format_ci_value(row[\\\"low\\\"])}, '\\n            f'{format_ci_value(row[\\\"high\\\"])})'\\n        )\\n\\n        ax_A_beta.text(\\n            0.01,\\n            row[\\\"y\\\"],\\n            beta_ci_text,\\n            fontsize=10.5,\\n            color=BLACK,\\n            va=\\\"center\\\"\\n        )\\n\\n        ax_A_p.text(\\n            0.02,\\n            row[\\\"y\\\"],\\n            format_p_value(row[\\\"p\\\"]),\\n            fontsize=10.5,\\n            color=BLACK,\\n            va=\\\"center\\\"\\n        )\\n\\n\\n# ============================================================\\n# 11. 中间空白间隔\\n# ============================================================\\n\\nax_spacer = fig.add_subplot(\\n    outer_grid[2, 0]\\n)\\n\\nax_spacer.axis(\\\"off\\\")\\n\\n\\n# ============================================================\\n# 12. B图标题\\n# ============================================================\\n\\nax_B_title = fig.add_subplot(\\n    outer_grid[3, 0]\\n)\\n\\nax_B_title.axis(\\\"off\\\")\\n\\nax_B_title.text(\\n    0.002,\\n    0.45,\\n    r\\\"B. Indirect effects \\\"\\n    r\\\"($a \\\\times b$) with bootstrap 95% CI\\\",\\n    fontsize=15,\\n    fontweight=\\\"bold\\\",\\n    color=BLACK,\\n    ha=\\\"left\\\",\\n    va=\\\"center\\\",\\n    transform=ax_B_title.transAxes\\n)\\n\\n\\n# ============================================================\\n# 13. B图主体\\n# ============================================================\\n\\nB_grid = outer_grid[4, 0].subgridspec(\\n    nrows=1,\\n    ncols=20,\\n    wspace=0.06\\n)\\n\\nax_B_path = fig.add_subplot(\\n    B_grid[0, 0:6]\\n)\\n\\nax_B_ab = fig.add_subplot(\\n    B_grid[0, 6:8],\\n    sharey=ax_B_path\\n)\\n\\nax_B_plot = fig.add_subplot(\\n    B_grid[0, 8:15],\\n    sharey=ax_B_path\\n)\\n\\nax_B_ci = fig.add_subplot(\\n    B_grid[0, 15:20],\\n    sharey=ax_B_path\\n)\\n\\nsetup_text_axis(\\n    ax_B_path,\\n    B_Y_MIN,\\n    B_Y_MAX\\n)\\n\\nsetup_text_axis(\\n    ax_B_ab,\\n    B_Y_MIN,\\n    B_Y_MAX\\n)\\n\\nsetup_text_axis(\\n    ax_B_ci,\\n    B_Y_MIN,\\n    B_Y_MAX\\n)\\n\\nsetup_forest_axis(\\n    axis=ax_B_plot,\\n    x_min=B_X_MIN,\\n    x_max=B_X_MAX,\\n    x_ticks=B_X_TICKS,\\n    x_label=r\\\"Indirect effect ($a \\\\times b$)\\\",\\n    y_min=B_Y_MIN,\\n    y_max=B_Y_MAX\\n)\\n\\n\\n# ------------------------------------------------------------\\n# B图表头\\n# ------------------------------------------------------------\\n\\nB_HEADER_Y = B_Y_MAX - 0.30\\nB_HEADER_LINE_Y = B_HEADER_Y - 0.22\\n\\nax_B_path.text(\\n    0.01,\\n    B_HEADER_Y,\\n    \\\"Indirect pathway\\\",\\n    fontsize=11.8,\\n    fontweight=\\\"bold\\\",\\n    color=BLACK,\\n    va=\\\"bottom\\\"\\n)\\n\\nax_B_ab.text(\\n    0.02,\\n    B_HEADER_Y,\\n    r\\\"$a \\\\times b$\\\",\\n    fontsize=11.8,\\n    fontweight=\\\"bold\\\",\\n    color=BLACK,\\n    va=\\\"bottom\\\"\\n)\\n\\nax_B_ci.text(\\n    0.01,\\n    B_HEADER_Y,\\n    \\\"Bootstrap 95% CI\\\",\\n    fontsize=11.8,\\n    fontweight=\\\"bold\\\",\\n    color=BLACK,\\n    va=\\\"bottom\\\"\\n)\\n\\ndraw_header_line(\\n    ax_B_path,\\n    B_HEADER_LINE_Y,\\n    0,\\n    1\\n)\\n\\ndraw_header_line(\\n    ax_B_ab,\\n    B_HEADER_LINE_Y,\\n    0,\\n    1\\n)\\n\\ndraw_header_line(\\n    ax_B_plot,\\n    B_HEADER_LINE_Y,\\n    B_X_MIN,\\n    B_X_MAX\\n)\\n\\ndraw_header_line(\\n    ax_B_ci,\\n    B_HEADER_LINE_Y,\\n    0,\\n    1\\n)\\n\\n\\n# ------------------------------------------------------------\\n# B图气体分隔线\\n# ------------------------------------------------------------\\n\\nfor separator_y in B_separator_positions:\\n\\n    draw_separator_line(\\n        ax_B_path,\\n        separator_y,\\n        0,\\n        1\\n    )\\n\\n    draw_separator_line(\\n        ax_B_ab,\\n        separator_y,\\n        0,\\n        1\\n    )\\n\\n    draw_separator_line(\\n        ax_B_plot,\\n        separator_y,\\n        B_X_MIN,\\n        B_X_MAX\\n    )\\n\\n    draw_separator_line(\\n        ax_B_ci,\\n        separator_y,\\n        0,\\n        1\\n    )\\n\\n\\n# ------------------------------------------------------------\\n# 绘制B图\\n# ------------------------------------------------------------\\n\\nfor row in rows_B:\\n\\n    ax_B_path.text(\\n        0.01,\\n        row[\\\"y\\\"],\\n        row[\\\"path\\\"],\\n        fontsize=11.0,\\n        color=BLACK,\\n        va=\\\"center\\\"\\n    )\\n\\n    ax_B_ab.text(\\n        0.02,\\n        row[\\\"y\\\"],\\n        f'{row[\\\"ab\\\"]:.3f}',\\n        fontsize=10.6,\\n        color=BLACK,\\n        va=\\\"center\\\"\\n    )\\n\\n    draw_forest_item(\\n        axis=ax_B_plot,\\n        y=row[\\\"y\\\"],\\n        estimate=row[\\\"ab\\\"],\\n        low=row[\\\"low\\\"],\\n        high=row[\\\"high\\\"]\\n    )\\n\\n    bootstrap_ci_text = (\\n        f'({format_ci_value(row[\\\"low\\\"])}, '\\n        f'{format_ci_value(row[\\\"high\\\"])})'\\n    )\\n\\n    ax_B_ci.text(\\n        0.01,\\n        row[\\\"y\\\"],\\n        bootstrap_ci_text,\\n        fontsize=10.5,\\n        color=BLACK,\\n        va=\\\"center\\\"\\n    )\\n\\n\\n# ============================================================\\n# 14. 保存图像\\n# ============================================================\\n\\nplt.savefig(\\n    PNG_PATH,\\n    dpi=600,\\n    bbox_inches=\\\"tight\\\",\\n    facecolor=\\\"white\\\",\\n    pad_inches=0.06\\n)\\n\\nplt.savefig(\\n    TIFF_PATH,\\n    dpi=600,\\n    bbox_inches=\\\"tight\\\",\\n    facecolor=\\\"white\\\",\\n    pad_inches=0.06\\n)\\n\\nplt.savefig(\\n    PDF_PATH,\\n    bbox_inches=\\\"tight\\\",\\n    facecolor=\\\"white\\\",\\n    pad_inches=0.06\\n)\\n\\n\\n# ============================================================\\n# 15. 显示结果\\n# ============================================================\\n\\nplt.show()\\nplt.close(fig)\\n\\nprint(\\\"\\\\nFigures saved successfully:\\\")\\nprint(f\\\"PNG  : {PNG_PATH}\\\")\\nprint(f\\\"TIFF : {TIFF_PATH}\\\")\\nprint(f\\\"PDF  : {PDF_PATH}\\\")\\nprint(f\\\"Paths: {SELECTED_PATHS_CSV}\\\")\"},\"plot_dependence\":{\"filename\":\"Fig_3_5_candidate_path_SHAP_dependence_final.py\",\"source\":\"# ============================================================\\n# Fig. 3.5 候选关联路径中土壤变量的 SHAP dependence 图（终版）\\n#\\n# 最终模型：\\n#   N2O -> ET\\n#   CO2 -> GBDT\\n#   CH4 -> ET\\n#\\n# 最终候选路径：\\n#   (a) BS - SOM - N2O\\n#   (b) BS - AK  - N2O\\n#   (c) SR - AK  - N2O\\n#   (d) SR - AK  - CO2\\n#   (e) BS - AN  - CO2\\n#   (f) BC - pH  - CO2\\n#   (g) BS - AN  - CH4\\n#   (h) BC - SOM - CH4\\n#\\n# 本版修改：\\n# 1. 不再用箭头标题直接暗示因果关系，改为“气体对土壤变量的SHAP响应（颜色为处理量）”；\\n# 2. BS、SR、BC分别使用独立且跨子图一致的共享颜色范围；\\n# 3. 颜色范围采用2.5%~97.5%分位数，减少极端施用量压缩主体色阶；\\n# 4. LOWESS仅在2.5%~97.5%数据区间拟合；5%~95%为实线，边缘为虚线；\\n# 5. 同一气体各子图统一y轴；每行仅左侧子图保留y轴标题与刻度标签；\\n# 6. 只保存PNG，关闭交互显示和tight bbox，降低600 dpi保存时的内存占用。\\n# ============================================================\\n\\nimport gc\\nimport warnings\\nfrom pathlib import Path\\n\\nimport numpy as np\\nimport pandas as pd\\nimport matplotlib as mpl\\n\\n# 使用非交互后端，减少Jupyter保存高分辨率图时的内存占用\\nmpl.use(\\\"Agg\\\")\\n\\nimport matplotlib.pyplot as plt\\nfrom matplotlib.colors import Normalize\\nfrom matplotlib.cm import ScalarMappable\\nfrom statsmodels.nonparametric.smoothers_lowess import lowess\\n\\nwarnings.filterwarnings(\\\"ignore\\\")\\n\\n\\n# ============================================================\\n# 0. 全局设置\\n# ============================================================\\n\\nmpl.rcParams[\\\"font.family\\\"] = \\\"Times New Roman\\\"\\nmpl.rcParams[\\\"font.size\\\"] = 11\\nmpl.rcParams[\\\"axes.unicode_minus\\\"] = False\\nmpl.rcParams[\\\"mathtext.fontset\\\"] = \\\"stix\\\"\\nmpl.rcParams[\\\"savefig.facecolor\\\"] = \\\"white\\\"\\n\\n# 读取“全部数据重新拟合后”的SHAP结果\\nSHAP_DIR = Path(\\n    r\\\"E:\\\\温室气体模型\\\\7\\\\ML_SHAP_最优模型\\\\Final_models_SHAP_full_data\\\"\\n)\\n\\nSAVE_DIR = Path(\\n    r\\\"E:\\\\温室气体模型\\\\image\\\\dependence\\\"\\n)\\nSAVE_DIR.mkdir(parents=True, exist_ok=True)\\n\\nPNG_PATH = SAVE_DIR / \\\"Fig_3_5_candidate_path_SHAP_dependence_final_600dpi.png\\\"\\n\\n# 终稿分辨率；如内存仍不足，可改为450\\nSAVE_DPI = 600\\n\\n# LOWESS参数\\nLOWESS_FRAC = 0.45\\nLOWESS_FIT_LOW_Q = 2.5\\nLOWESS_SOLID_LOW_Q = 5.0\\nLOWESS_SOLID_HIGH_Q = 95.0\\nLOWESS_FIT_HIGH_Q = 97.5\\n\\n# 散点样式\\nPOINT_SIZE = 25\\nPOINT_ALPHA = 0.80\\n\\n# 颜色图\\nCMAP_NAME = \\\"coolwarm\\\"\\nCOLOR_LOW_Q = 2.5\\nCOLOR_HIGH_Q = 97.5\\n\\n# 画布大小。适度缩小可明显降低600 dpi导出内存。\\nFIGSIZE = (14.2, 10.0)\\n\\n\\n# ============================================================\\n# 1. SHAP文件\\n# ============================================================\\n\\nNPZ_FILES = {\\n    \\\"N2O\\\": SHAP_DIR / \\\"N2O\\\" / \\\"N2O_ET_SHAP_values_full_data.npz\\\",\\n    \\\"CO2\\\": SHAP_DIR / \\\"CO2\\\" / \\\"CO2_GBDT_SHAP_values_full_data.npz\\\",\\n    \\\"CH4\\\": SHAP_DIR / \\\"CH4\\\" / \\\"CH4_ET_SHAP_values_full_data.npz\\\",\\n}\\n\\nfor gas, path in NPZ_FILES.items():\\n    if not path.exists():\\n        raise FileNotFoundError(\\n            f\\\"{gas} 的SHAP文件不存在：\\\\n{path}\\\"\\n        )\\n\\n\\n# ============================================================\\n# 2. 标签与子图设置\\n# ============================================================\\n\\nX_LABELS = {\\n    \\\"SOM\\\": r\\\"SOM (g kg$^{-1}$)\\\",\\n    \\\"AK\\\": r\\\"AK (mg kg$^{-1}$)\\\",\\n    \\\"AN\\\": r\\\"AN (mg kg$^{-1}$)\\\",\\n    \\\"pH\\\": \\\"pH\\\",\\n}\\n\\nGAS_LABELS = {\\n    \\\"N2O\\\": r\\\"N$_2$O\\\",\\n    \\\"CO2\\\": r\\\"CO$_2$\\\",\\n    \\\"CH4\\\": r\\\"CH$_4$\\\",\\n}\\n\\n# 标题改为模型响应表述，不把SHAP dependence图单独解释为已证实的因果链。\\nPLOT_SPECS = [\\n    {\\n        \\\"tag\\\": \\\"(a)\\\",\\n        \\\"gas\\\": \\\"N2O\\\",\\n        \\\"feature\\\": \\\"SOM\\\",\\n        \\\"color_feature\\\": \\\"BS\\\",\\n        \\\"title\\\": r\\\"N$_2$O response to SOM (color: BS)\\\",\\n        \\\"show_ylabel\\\": True,\\n    },\\n    {\\n        \\\"tag\\\": \\\"(b)\\\",\\n        \\\"gas\\\": \\\"N2O\\\",\\n        \\\"feature\\\": \\\"AK\\\",\\n        \\\"color_feature\\\": \\\"BS\\\",\\n        \\\"title\\\": r\\\"N$_2$O response to AK (color: BS)\\\",\\n        \\\"show_ylabel\\\": False,\\n    },\\n    {\\n        \\\"tag\\\": \\\"(c)\\\",\\n        \\\"gas\\\": \\\"N2O\\\",\\n        \\\"feature\\\": \\\"AK\\\",\\n        \\\"color_feature\\\": \\\"SR\\\",\\n        \\\"title\\\": r\\\"N$_2$O response to AK (color: SR)\\\",\\n        \\\"show_ylabel\\\": False,\\n    },\\n    {\\n        \\\"tag\\\": \\\"(d)\\\",\\n        \\\"gas\\\": \\\"CO2\\\",\\n        \\\"feature\\\": \\\"AK\\\",\\n        \\\"color_feature\\\": \\\"SR\\\",\\n        \\\"title\\\": r\\\"CO$_2$ response to AK (color: SR)\\\",\\n        \\\"show_ylabel\\\": True,\\n    },\\n    {\\n        \\\"tag\\\": \\\"(e)\\\",\\n        \\\"gas\\\": \\\"CO2\\\",\\n        \\\"feature\\\": \\\"AN\\\",\\n        \\\"color_feature\\\": \\\"BS\\\",\\n        \\\"title\\\": r\\\"CO$_2$ response to AN (color: BS)\\\",\\n        \\\"show_ylabel\\\": False,\\n    },\\n    {\\n        \\\"tag\\\": \\\"(f)\\\",\\n        \\\"gas\\\": \\\"CO2\\\",\\n        \\\"feature\\\": \\\"pH\\\",\\n        \\\"color_feature\\\": \\\"BC\\\",\\n        \\\"title\\\": r\\\"CO$_2$ response to pH (color: BC)\\\",\\n        \\\"show_ylabel\\\": False,\\n    },\\n    {\\n        \\\"tag\\\": \\\"(g)\\\",\\n        \\\"gas\\\": \\\"CH4\\\",\\n        \\\"feature\\\": \\\"AN\\\",\\n        \\\"color_feature\\\": \\\"BS\\\",\\n        \\\"title\\\": r\\\"CH$_4$ response to AN (color: BS)\\\",\\n        \\\"show_ylabel\\\": True,\\n    },\\n    {\\n        \\\"tag\\\": \\\"(h)\\\",\\n        \\\"gas\\\": \\\"CH4\\\",\\n        \\\"feature\\\": \\\"SOM\\\",\\n        \\\"color_feature\\\": \\\"BC\\\",\\n        \\\"title\\\": r\\\"CH$_4$ response to SOM (color: BC)\\\",\\n        \\\"show_ylabel\\\": False,\\n    },\\n]\\n\\n\\n# ============================================================\\n# 3. 读取SHAP结果\\n# ============================================================\\n\\ndef decode_feature_name(value):\\n    if isinstance(value, bytes):\\n        return value.decode(\\\"utf-8\\\", errors=\\\"ignore\\\")\\n    return str(value)\\n\\n\\ndef load_saved_shap(npz_path):\\n    \\\"\\\"\\\"读取已保存的SHAP值、特征值和特征名。\\\"\\\"\\\"\\n\\n    with np.load(npz_path, allow_pickle=True) as data:\\n        required_keys = [\\n            \\\"shap_values\\\",\\n            \\\"feature_values\\\",\\n            \\\"feature_names\\\",\\n        ]\\n\\n        for key in required_keys:\\n            if key not in data.files:\\n                raise KeyError(\\n                    f\\\"{npz_path.name} 缺少字段：{key}\\\"\\n                )\\n\\n        shap_values = np.asarray(\\n            data[\\\"shap_values\\\"],\\n            dtype=float,\\n        )\\n\\n        feature_values = np.asarray(\\n            data[\\\"feature_values\\\"],\\n            dtype=float,\\n        )\\n\\n        feature_names = [\\n            decode_feature_name(value).strip()\\n            for value in data[\\\"feature_names\\\"].tolist()\\n        ]\\n\\n    if shap_values.ndim == 3 and shap_values.shape[-1] == 1:\\n        shap_values = shap_values[:, :, 0]\\n\\n    if shap_values.shape != feature_values.shape:\\n        raise ValueError(\\n            f\\\"{npz_path.name} 中shap_values与feature_values维度不一致：\\\"\\n            f\\\"{shap_values.shape} vs {feature_values.shape}\\\"\\n        )\\n\\n    if shap_values.shape[1] != len(feature_names):\\n        raise ValueError(\\n            f\\\"{npz_path.name} 中变量名数量与矩阵列数不一致：\\\"\\n            f\\\"{len(feature_names)} vs {shap_values.shape[1]}\\\"\\n        )\\n\\n    return {\\n        \\\"shap_values\\\": shap_values,\\n        \\\"feature_values\\\": feature_values,\\n        \\\"feature_names\\\": feature_names,\\n    }\\n\\n\\nsaved_results = {\\n    gas: load_saved_shap(path)\\n    for gas, path in NPZ_FILES.items()\\n}\\n\\nfor gas, result in saved_results.items():\\n    print(\\n        f\\\"{gas}: 样本数={result['shap_values'].shape[0]}, \\\"\\n        f\\\"变量数={result['shap_values'].shape[1]}\\\"\\n    )\\n    print(\\\"变量名：\\\", result[\\\"feature_names\\\"])\\n\\n\\n# ============================================================\\n# 4. 数据提取和坐标范围\\n# ============================================================\\n\\ndef get_feature_index(feature_names, feature):\\n    clean_names = [str(name).strip() for name in feature_names]\\n\\n    if feature not in clean_names:\\n        raise KeyError(\\n            f\\\"找不到变量 {feature}，当前变量名为：{clean_names}\\\"\\n        )\\n\\n    return clean_names.index(feature)\\n\\n\\ndef extract_panel_data(gas, feature, color_feature):\\n    \\\"\\\"\\\"提取指定气体和指定特征对应的SHAP dependence数据。\\\"\\\"\\\"\\n\\n    result = saved_results[gas]\\n\\n    feature_names = result[\\\"feature_names\\\"]\\n    shap_values = result[\\\"shap_values\\\"]\\n    feature_values = result[\\\"feature_values\\\"]\\n\\n    feature_index = get_feature_index(\\n        feature_names,\\n        feature,\\n    )\\n\\n    color_index = get_feature_index(\\n        feature_names,\\n        color_feature,\\n    )\\n\\n    x = feature_values[:, feature_index].copy()\\n    y = shap_values[:, feature_index].copy()\\n    color_raw = feature_values[:, color_index].copy()\\n\\n    valid_mask = (\\n        np.isfinite(x)\\n        & np.isfinite(y)\\n        & np.isfinite(color_raw)\\n    )\\n\\n    x = x[valid_mask]\\n    y = y[valid_mask]\\n    color_raw = color_raw[valid_mask]\\n\\n    # 施用量理论上不应小于0；如有轻微负值，作图时截断至0。\\n    color_raw = np.clip(\\n        color_raw,\\n        a_min=0,\\n        a_max=None,\\n    )\\n\\n    color_log = np.log1p(color_raw)\\n\\n    return x, y, color_raw, color_log\\n\\n\\ndef padded_limits(values, margin_ratio=0.08):\\n    \\\"\\\"\\\"根据全部有效点计算带留白的坐标范围。\\\"\\\"\\\"\\n\\n    values = np.asarray(values, dtype=float)\\n    values = values[np.isfinite(values)]\\n\\n    if len(values) == 0:\\n        return -1.0, 1.0\\n\\n    value_min = float(np.min(values))\\n    value_max = float(np.max(values))\\n\\n    value_range = value_max - value_min\\n\\n    if np.isclose(value_range, 0):\\n        value_range = max(abs(value_min), 1.0)\\n\\n    margin = value_range * margin_ratio\\n\\n    return value_min - margin, value_max + margin\\n\\n\\ndef calc_gas_y_limits(gas, margin_ratio=0.08):\\n    \\\"\\\"\\\"同一气体的全部候选路径使用相同y轴范围。\\\"\\\"\\\"\\n\\n    gas_y_values = []\\n\\n    for spec in PLOT_SPECS:\\n        if spec[\\\"gas\\\"] != gas:\\n            continue\\n\\n        _, y, _, _ = extract_panel_data(\\n            gas=spec[\\\"gas\\\"],\\n            feature=spec[\\\"feature\\\"],\\n            color_feature=spec[\\\"color_feature\\\"],\\n        )\\n\\n        gas_y_values.extend(y.tolist())\\n\\n    return padded_limits(\\n        gas_y_values,\\n        margin_ratio=margin_ratio,\\n    )\\n\\n\\ndef calc_color_norms():\\n    \\\"\\\"\\\"\\n    为BS、SR和BC分别建立跨面板一致的颜色范围。\\n    使用2.5%和97.5%分位数降低单个极端施用量对主体色阶的影响。\\n    \\\"\\\"\\\"\\n\\n    treatment_log_values = {\\n        \\\"BS\\\": [],\\n        \\\"SR\\\": [],\\n        \\\"BC\\\": [],\\n    }\\n\\n    for spec in PLOT_SPECS:\\n        _, _, _, color_log = extract_panel_data(\\n            gas=spec[\\\"gas\\\"],\\n            feature=spec[\\\"feature\\\"],\\n            color_feature=spec[\\\"color_feature\\\"],\\n        )\\n\\n        treatment_log_values[\\n            spec[\\\"color_feature\\\"]\\n        ].extend(color_log.tolist())\\n\\n    norms = {}\\n\\n    for treatment, values in treatment_log_values.items():\\n        values = np.asarray(values, dtype=float)\\n        values = values[np.isfinite(values)]\\n\\n        if len(values) == 0:\\n            norms[treatment] = Normalize(\\n                vmin=0,\\n                vmax=1,\\n                clip=True,\\n            )\\n            continue\\n\\n        vmin = float(\\n            np.nanpercentile(values, COLOR_LOW_Q)\\n        )\\n        vmax = float(\\n            np.nanpercentile(values, COLOR_HIGH_Q)\\n        )\\n\\n        if np.isclose(vmin, vmax):\\n            vmin = float(np.min(values))\\n            vmax = float(np.max(values))\\n\\n        if np.isclose(vmin, vmax):\\n            vmax = vmin + 1.0\\n\\n        norms[treatment] = Normalize(\\n            vmin=vmin,\\n            vmax=vmax,\\n            clip=True,\\n        )\\n\\n    return norms\\n\\n\\nGAS_YLIMS = {\\n    gas: calc_gas_y_limits(gas)\\n    for gas in [\\\"N2O\\\", \\\"CO2\\\", \\\"CH4\\\"]\\n}\\n\\nCOLOR_NORMS = calc_color_norms()\\n\\nprint(\\\"\\\\n各气体统一y轴范围：\\\")\\nfor gas, limits in GAS_YLIMS.items():\\n    print(gas, limits)\\n\\n\\n# ============================================================\\n# 5. LOWESS平滑及稀疏尾部处理\\n# ============================================================\\n\\ndef calculate_lowess_segments(x, y, frac=0.45):\\n    \\\"\\\"\\\"\\n    在x的2.5%~97.5%范围内计算LOWESS。\\n\\n    返回：\\n    - 左侧稀疏边缘：2.5%~5%，虚线；\\n    - 中央主体区间：5%~95%，实线；\\n    - 右侧稀疏边缘：95%~97.5%，虚线。\\n\\n    这样既保留趋势连续性，又避免把少数边缘点支持的趋势画成同等确定的实线。\\n    \\\"\\\"\\\"\\n\\n    x = np.asarray(x, dtype=float)\\n    y = np.asarray(y, dtype=float)\\n\\n    valid_mask = np.isfinite(x) & np.isfinite(y)\\n    x = x[valid_mask]\\n    y = y[valid_mask]\\n\\n    empty = (np.array([]), np.array([]))\\n\\n    if len(x) < 8 or np.isclose(np.nanstd(x), 0):\\n        return empty, empty, empty\\n\\n    fit_low = float(\\n        np.nanpercentile(x, LOWESS_FIT_LOW_Q)\\n    )\\n    solid_low = float(\\n        np.nanpercentile(x, LOWESS_SOLID_LOW_Q)\\n    )\\n    solid_high = float(\\n        np.nanpercentile(x, LOWESS_SOLID_HIGH_Q)\\n    )\\n    fit_high = float(\\n        np.nanpercentile(x, LOWESS_FIT_HIGH_Q)\\n    )\\n\\n    fit_mask = (\\n        (x >= fit_low)\\n        & (x <= fit_high)\\n    )\\n\\n    x_fit = x[fit_mask]\\n    y_fit = y[fit_mask]\\n\\n    if len(x_fit) < 8 or np.isclose(np.nanstd(x_fit), 0):\\n        return empty, empty, empty\\n\\n    sort_order = np.argsort(x_fit)\\n    x_fit = x_fit[sort_order]\\n    y_fit = y_fit[sort_order]\\n\\n    smoothed = lowess(\\n        endog=y_fit,\\n        exog=x_fit,\\n        frac=frac,\\n        it=0,\\n        return_sorted=True,\\n    )\\n\\n    smooth_x = smoothed[:, 0]\\n    smooth_y = smoothed[:, 1]\\n\\n    left_mask = smooth_x <= solid_low\\n    center_mask = (\\n        (smooth_x >= solid_low)\\n        & (smooth_x <= solid_high)\\n    )\\n    right_mask = smooth_x >= solid_high\\n\\n    left_segment = (\\n        smooth_x[left_mask],\\n        smooth_y[left_mask],\\n    )\\n\\n    center_segment = (\\n        smooth_x[center_mask],\\n        smooth_y[center_mask],\\n    )\\n\\n    right_segment = (\\n        smooth_x[right_mask],\\n        smooth_y[right_mask],\\n    )\\n\\n    return left_segment, center_segment, right_segment\\n\\n\\n# ============================================================\\n# 6. 单个子图绘制函数\\n# ============================================================\\n\\ndef draw_panel(ax, spec):\\n    x, y, _, color_log = extract_panel_data(\\n        gas=spec[\\\"gas\\\"],\\n        feature=spec[\\\"feature\\\"],\\n        color_feature=spec[\\\"color_feature\\\"],\\n    )\\n\\n    cmap = mpl.colormaps[CMAP_NAME]\\n    norm = COLOR_NORMS[spec[\\\"color_feature\\\"]]\\n\\n    ax.scatter(\\n        x,\\n        y,\\n        c=color_log,\\n        cmap=cmap,\\n        norm=norm,\\n        s=POINT_SIZE,\\n        alpha=POINT_ALPHA,\\n        edgecolors=\\\"none\\\",\\n        linewidths=0,\\n        rasterized=True,\\n        zorder=2,\\n    )\\n\\n    left_segment, center_segment, right_segment = (\\n        calculate_lowess_segments(\\n            x,\\n            y,\\n            frac=LOWESS_FRAC,\\n        )\\n    )\\n\\n    # 中央样本支持较充分的区间使用实线\\n    center_x, center_y = center_segment\\n    if len(center_x) >= 2:\\n        ax.plot(\\n            center_x,\\n            center_y,\\n            color=\\\"black\\\",\\n            linewidth=2.0,\\n            linestyle=\\\"-\\\",\\n            solid_capstyle=\\\"round\\\",\\n            zorder=4,\\n        )\\n\\n    # 两端样本相对稀疏的区间使用虚线\\n    for tail_x, tail_y in [left_segment, right_segment]:\\n        if len(tail_x) >= 2:\\n            ax.plot(\\n                tail_x,\\n                tail_y,\\n                color=\\\"black\\\",\\n                linewidth=1.5,\\n                linestyle=(0, (4, 3)),\\n                zorder=3,\\n            )\\n\\n    ax.axhline(\\n        y=0,\\n        color=\\\"#808080\\\",\\n        linestyle=\\\"--\\\",\\n        linewidth=0.85,\\n        zorder=1,\\n    )\\n\\n    ax.set_title(\\n        spec[\\\"title\\\"],\\n        fontsize=11.5,\\n        pad=7,\\n    )\\n\\n    ax.text(\\n        0.01,\\n        1.025,\\n        spec[\\\"tag\\\"],\\n        transform=ax.transAxes,\\n        fontsize=11.5,\\n        fontweight=\\\"bold\\\",\\n        ha=\\\"left\\\",\\n        va=\\\"bottom\\\",\\n    )\\n\\n    ax.set_xlabel(\\n        X_LABELS.get(\\n            spec[\\\"feature\\\"],\\n            spec[\\\"feature\\\"],\\n        ),\\n        fontsize=10.5,\\n    )\\n\\n    if spec[\\\"show_ylabel\\\"]:\\n        ax.set_ylabel(\\n            \\\"SHAP value\\\",\\n            fontsize=10.5,\\n        )\\n    else:\\n        ax.set_ylabel(\\\"\\\")\\n        ax.tick_params(\\n            axis=\\\"y\\\",\\n            labelleft=False,\\n        )\\n\\n    ax.set_ylim(\\n        GAS_YLIMS[spec[\\\"gas\\\"]]\\n    )\\n\\n    ax.tick_params(\\n        axis=\\\"both\\\",\\n        labelsize=9.5,\\n        length=3,\\n        width=0.8,\\n    )\\n\\n    ax.grid(\\n        axis=\\\"both\\\",\\n        linestyle=\\\":\\\",\\n        linewidth=0.45,\\n        alpha=0.28,\\n        zorder=0,\\n    )\\n\\n    for spine in ax.spines.values():\\n        spine.set_linewidth(0.85)\\n\\n    # 样本量放在右上角，便于识别不同子图的有效样本数\\n    ax.text(\\n        0.98,\\n        0.96,\\n        f\\\"n = {len(x)}\\\",\\n        transform=ax.transAxes,\\n        fontsize=8.8,\\n        ha=\\\"right\\\",\\n        va=\\\"top\\\",\\n    )\\n\\n    print(\\n        f\\\"{spec['tag']} {spec['title']}: 有效点数={len(x)}\\\"\\n    )\\n\\n\\n# ============================================================\\n# 7. 创建布局\\n# ============================================================\\n\\nfig = plt.figure(\\n    figsize=FIGSIZE,\\n    facecolor=\\\"white\\\",\\n)\\n\\nouter = fig.add_gridspec(\\n    nrows=3,\\n    ncols=1,\\n    height_ratios=[1.0, 1.0, 0.95],\\n    left=0.065,\\n    right=0.905,\\n    top=0.955,\\n    bottom=0.075,\\n    hspace=0.36,\\n)\\n\\n# 第一行：N2O，3图\\ngs_row1 = outer[0].subgridspec(\\n    1,\\n    3,\\n    wspace=0.24,\\n)\\n\\nax_a = fig.add_subplot(gs_row1[0, 0])\\nax_b = fig.add_subplot(gs_row1[0, 1], sharey=ax_a)\\nax_c = fig.add_subplot(gs_row1[0, 2], sharey=ax_a)\\n\\n# 第二行：CO2，3图\\ngs_row2 = outer[1].subgridspec(\\n    1,\\n    3,\\n    wspace=0.24,\\n)\\n\\nax_d = fig.add_subplot(gs_row2[0, 0])\\nax_e = fig.add_subplot(gs_row2[0, 1], sharey=ax_d)\\nax_f = fig.add_subplot(gs_row2[0, 2], sharey=ax_d)\\n\\n# 第三行：CH4，2图居中\\ngs_row3 = outer[2].subgridspec(\\n    1,\\n    4,\\n    width_ratios=[0.24, 1.0, 1.0, 0.24],\\n    wspace=0.24,\\n)\\n\\nax_g = fig.add_subplot(gs_row3[0, 1])\\nax_h = fig.add_subplot(gs_row3[0, 2], sharey=ax_g)\\n\\naxes_map = {\\n    \\\"(a)\\\": ax_a,\\n    \\\"(b)\\\": ax_b,\\n    \\\"(c)\\\": ax_c,\\n    \\\"(d)\\\": ax_d,\\n    \\\"(e)\\\": ax_e,\\n    \\\"(f)\\\": ax_f,\\n    \\\"(g)\\\": ax_g,\\n    \\\"(h)\\\": ax_h,\\n}\\n\\nfor spec in PLOT_SPECS:\\n    draw_panel(\\n        ax=axes_map[spec[\\\"tag\\\"]],\\n        spec=spec,\\n    )\\n\\n\\n# ============================================================\\n# 8. BS、SR、BC三个共享颜色条\\n# ============================================================\\n\\n# 颜色条的位置分别覆盖其相关面板所在的大致区域。\\ncax_bs = fig.add_axes([0.925, 0.705, 0.012, 0.185])\\ncax_sr = fig.add_axes([0.925, 0.415, 0.012, 0.185])\\ncax_bc = fig.add_axes([0.925, 0.125, 0.012, 0.185])\\n\\nfor treatment, color_axis in zip(\\n    [\\\"BS\\\", \\\"SR\\\", \\\"BC\\\"],\\n    [cax_bs, cax_sr, cax_bc],\\n):\\n    scalar_mappable = ScalarMappable(\\n        norm=COLOR_NORMS[treatment],\\n        cmap=mpl.colormaps[CMAP_NAME],\\n    )\\n    scalar_mappable.set_array([])\\n\\n    colorbar = fig.colorbar(\\n        scalar_mappable,\\n        cax=color_axis,\\n        orientation=\\\"vertical\\\",\\n    )\\n\\n    colorbar.set_label(\\n        rf\\\"log({treatment} + 1)\\\",\\n        fontsize=9.5,\\n        labelpad=5,\\n    )\\n\\n    colorbar.ax.tick_params(\\n        labelsize=8.5,\\n        length=2.5,\\n        width=0.7,\\n    )\\n\\n    colorbar.outline.set_linewidth(0.8)\\n\\n\\n# ============================================================\\n# 9. 仅保存PNG并释放内存\\n# ============================================================\\n\\n# 不使用bbox_inches='tight'，避免高分辨率保存时额外渲染整张图。\\nfig.savefig(\\n    PNG_PATH,\\n    dpi=SAVE_DPI,\\n    format=\\\"png\\\",\\n    facecolor=\\\"white\\\",\\n    edgecolor=\\\"none\\\",\\n)\\n\\nplt.close(fig)\\nfig.clear()\\n\\ndel fig\\n\\ngc.collect()\\n\\nprint(\\\"\\\\n\\\" + \\\"=\\\" * 80)\\nprint(\\\"终版SHAP候选路径响应图已保存：\\\")\\nprint(PNG_PATH)\\nprint(\\\"=\\\" * 80)\"},\"plot_predictions\":{\"filename\":\"粘贴的文本 (1)(20261001-072143).txt\",\"source\":\"# ============================================================\\n# Fig. 6\\n# Observed vs Predicted + Prediction Error Distribution\\n#\\n# 30 repeated 80/20 splits\\n# -> collect TEST-set predictions\\n# -> group by Sample_index\\n# -> average predictions for each sample\\n# -> one point per independent sample\\n#\\n# Left panel:\\n#   Observed vs Predicted\\n#\\n# Right panel:\\n#   Prediction error distribution\\n#   Error = Predicted - Observed\\n#\\n# Final models:\\n#   N2O : ET\\n#   CO2 : GBDT\\n#   CH4 : ET\\n# ============================================================\\n\\n\\n# ============================================================\\n# 0. 导入库\\n# ============================================================\\n\\nimport pandas as pd\\nimport numpy as np\\nimport matplotlib.pyplot as plt\\n\\nfrom pathlib import Path\\n\\nfrom sklearn.metrics import (\\n    r2_score,\\n    mean_squared_error,\\n    mean_absolute_error\\n)\\n\\n\\n# ============================================================\\n# 1. 文件路径\\n# ============================================================\\n\\n# 30次重复80/20划分得到的测试集预测结果\\nINPUT_FILE = Path(\\n    r\\\"E:\\\\温室气体模型\\\\7\\\\Repeated_outer_split_6panel\\\\repeat_test_predictions_df.csv\\\"\\n)\\n\\n\\n# 最终图片和数据保存位置\\nOUTPUT_DIR = Path(\\n    r\\\"E:\\\\温室气体模型\\\\image\\\\1\\\\final\\\\1\\\\Fig6_final\\\"\\n)\\n\\n\\nOUTPUT_DIR.mkdir(\\n    parents=True,\\n    exist_ok=True\\n)\\n\\n\\n# ============================================================\\n# 2. 最终模型\\n# ============================================================\\n\\nFINAL_MODELS = {\\n    \\\"N2O\\\": \\\"ET\\\",\\n    \\\"CO2\\\": \\\"GBDT\\\",\\n    \\\"CH4\\\": \\\"ET\\\"\\n}\\n\\n\\n# ============================================================\\n# 3. 全局绘图格式\\n# ============================================================\\n\\nplt.rcParams[\\\"font.family\\\"] = \\\"Times New Roman\\\"\\n\\nplt.rcParams[\\\"mathtext.fontset\\\"] = \\\"stix\\\"\\n\\nplt.rcParams[\\\"axes.unicode_minus\\\"] = False\\n\\nplt.rcParams[\\\"font.size\\\"] = 12\\n\\nplt.rcParams[\\\"axes.linewidth\\\"] = 1.0\\n\\n\\n# ------------------------------------------------------------\\n# 统一散点颜色\\n# ------------------------------------------------------------\\n\\nPOINT_COLOR = \\\"#E88B62\\\"\\n\\nPOINT_EDGE = \\\"#A95538\\\"\\n\\n\\n# ------------------------------------------------------------\\n# 参考线颜色\\n# ------------------------------------------------------------\\n\\nREFERENCE_COLOR = \\\"#555555\\\"\\n\\n\\n# ------------------------------------------------------------\\n# 输出分辨率\\n# ------------------------------------------------------------\\n\\nSAVE_DPI = 600\\n\\n\\n# ============================================================\\n# 4. 读取30次测试预测\\n# ============================================================\\n\\ndf = pd.read_csv(\\n    INPUT_FILE\\n)\\n\\n\\nprint(\\\"=\\\" * 70)\\n\\nprint(\\\"Input data\\\")\\n\\nprint(\\\"=\\\" * 70)\\n\\n\\nprint(\\n    \\\"Total prediction records:\\\",\\n    len(df)\\n)\\n\\n\\nprint(\\\"\\\\nColumns:\\\")\\n\\nprint(\\n    df.columns.tolist()\\n)\\n\\n\\n# ============================================================\\n# 5. 按 Sample_index 合并30次测试预测\\n# ============================================================\\n\\nresults = {}\\n\\nsummary = []\\n\\n\\nfor gas, model in FINAL_MODELS.items():\\n\\n    # --------------------------------------------------------\\n    # 选择当前气体 + 最终模型\\n    # --------------------------------------------------------\\n\\n    temp = df[\\n        (df[\\\"Gas\\\"] == gas) &\\n        (df[\\\"Model\\\"] == model)\\n    ].copy()\\n\\n\\n    # --------------------------------------------------------\\n    # 同一个样本可能多次进入测试集\\n    #\\n    # Observed:\\n    #     原始观测值\\n    #\\n    # Predicted:\\n    #     多次进入测试集后的预测均值\\n    #\\n    # Predicted_SD:\\n    #     多次测试预测的标准差\\n    #\\n    # Test_count:\\n    #     该样本进入测试集的次数\\n    # --------------------------------------------------------\\n\\n    sample_mean = (\\n        temp\\n        .groupby(\\n            \\\"Sample_index\\\",\\n            as_index=False\\n        )\\n        .agg(\\n\\n            Observed=(\\n                \\\"Observed\\\",\\n                \\\"first\\\"\\n            ),\\n\\n            Predicted=(\\n                \\\"Predicted\\\",\\n                \\\"mean\\\"\\n            ),\\n\\n            Predicted_SD=(\\n                \\\"Predicted\\\",\\n                \\\"std\\\"\\n            ),\\n\\n            Test_count=(\\n                \\\"Predicted\\\",\\n                \\\"count\\\"\\n            )\\n        )\\n    )\\n\\n\\n    # --------------------------------------------------------\\n    # 如果某样本只进入测试集一次\\n    # SD 会是 NaN\\n    # --------------------------------------------------------\\n\\n    sample_mean[\\\"Predicted_SD\\\"] = (\\n        sample_mean[\\n            \\\"Predicted_SD\\\"\\n        ].fillna(0)\\n    )\\n\\n\\n    # ========================================================\\n    # 5.1 计算 Prediction Error\\n    # ========================================================\\n\\n    # Error > 0:\\n    #     模型高估\\n    #\\n    # Error < 0:\\n    #     模型低估\\n    #\\n    # Error = 0:\\n    #     完全预测正确\\n\\n    sample_mean[\\\"Error\\\"] = (\\n        sample_mean[\\\"Predicted\\\"]\\n        -\\n        sample_mean[\\\"Observed\\\"]\\n    )\\n\\n\\n    # --------------------------------------------------------\\n    # Absolute Error\\n    # --------------------------------------------------------\\n\\n    sample_mean[\\\"Absolute_Error\\\"] = (\\n        np.abs(\\n            sample_mean[\\\"Error\\\"]\\n        )\\n    )\\n\\n\\n    # --------------------------------------------------------\\n    # Squared Error\\n    # --------------------------------------------------------\\n\\n    sample_mean[\\\"Squared_Error\\\"] = (\\n        sample_mean[\\\"Error\\\"] ** 2\\n    )\\n\\n\\n    # ========================================================\\n    # 5.2 模型评价指标\\n    # ========================================================\\n\\n    y_true = (\\n        sample_mean[\\n            \\\"Observed\\\"\\n        ].to_numpy()\\n    )\\n\\n\\n    y_pred = (\\n        sample_mean[\\n            \\\"Predicted\\\"\\n        ].to_numpy()\\n    )\\n\\n\\n    # --------------------------------------------------------\\n    # R²\\n    # --------------------------------------------------------\\n\\n    R2 = r2_score(\\n        y_true,\\n        y_pred\\n    )\\n\\n\\n    # --------------------------------------------------------\\n    # RMSE\\n    # --------------------------------------------------------\\n\\n    RMSE = np.sqrt(\\n        mean_squared_error(\\n            y_true,\\n            y_pred\\n        )\\n    )\\n\\n\\n    # --------------------------------------------------------\\n    # MAE\\n    # --------------------------------------------------------\\n\\n    MAE = mean_absolute_error(\\n        y_true,\\n        y_pred\\n    )\\n\\n\\n    # --------------------------------------------------------\\n    # 样本数\\n    # 仍然计算，但不显示在图中\\n    # --------------------------------------------------------\\n\\n    n = len(\\n        sample_mean\\n    )\\n\\n\\n    # ========================================================\\n    # 5.3 Error统计\\n    # ========================================================\\n\\n    errors = (\\n        sample_mean[\\n            \\\"Error\\\"\\n        ].to_numpy()\\n    )\\n\\n\\n    # Mean Error\\n    mean_error = np.mean(\\n        errors\\n    )\\n\\n\\n    # Error SD\\n    error_sd = np.std(\\n        errors,\\n        ddof=1\\n    )\\n\\n\\n    # Error Variance\\n    error_variance = np.var(\\n        errors,\\n        ddof=1\\n    )\\n\\n\\n    # ========================================================\\n    # 5.4 保存当前气体结果\\n    # ========================================================\\n\\n    results[gas] = {\\n\\n        \\\"model\\\": model,\\n\\n        \\\"data\\\": sample_mean,\\n\\n        \\\"R2\\\": R2,\\n\\n        \\\"RMSE\\\": RMSE,\\n\\n        \\\"MAE\\\": MAE,\\n\\n        \\\"n\\\": n,\\n\\n        \\\"Mean_Error\\\": mean_error,\\n\\n        \\\"Error_SD\\\": error_sd,\\n\\n        \\\"Error_Variance\\\": error_variance\\n    }\\n\\n\\n    # ========================================================\\n    # 5.5 Summary\\n    # ========================================================\\n\\n    summary.append({\\n\\n        \\\"Gas\\\": gas,\\n\\n        \\\"Model\\\": model,\\n\\n        \\\"n\\\": n,\\n\\n        \\\"R2\\\": R2,\\n\\n        \\\"RMSE\\\": RMSE,\\n\\n        \\\"MAE\\\": MAE,\\n\\n        \\\"Mean_Error\\\": mean_error,\\n\\n        \\\"Error_SD\\\": error_sd,\\n\\n        \\\"Error_Variance\\\": error_variance,\\n\\n        \\\"Mean_test_count\\\":\\n            sample_mean[\\n                \\\"Test_count\\\"\\n            ].mean(),\\n\\n        \\\"Min_test_count\\\":\\n            sample_mean[\\n                \\\"Test_count\\\"\\n            ].min(),\\n\\n        \\\"Max_test_count\\\":\\n            sample_mean[\\n                \\\"Test_count\\\"\\n            ].max()\\n    })\\n\\n\\n    # ========================================================\\n    # 5.6 控制台输出\\n    # ========================================================\\n\\n    print(\\n        \\\"\\\\n\\\" +\\n        \\\"=\\\" * 70\\n    )\\n\\n    print(\\n        f\\\"{gas} — {model}\\\"\\n    )\\n\\n    print(\\n        \\\"=\\\" * 70\\n    )\\n\\n\\n    print(\\n        f\\\"n              = {n}\\\"\\n    )\\n\\n    print(\\n        f\\\"R²             = {R2:.4f}\\\"\\n    )\\n\\n    print(\\n        f\\\"RMSE           = {RMSE:.4f}\\\"\\n    )\\n\\n    print(\\n        f\\\"MAE            = {MAE:.4f}\\\"\\n    )\\n\\n    print(\\n        f\\\"Mean Error     = {mean_error:.4f}\\\"\\n    )\\n\\n    print(\\n        f\\\"Error SD       = {error_sd:.4f}\\\"\\n    )\\n\\n    print(\\n        f\\\"Error Variance = {error_variance:.4f}\\\"\\n    )\\n\\n\\n    print(\\n        \\\"Test frequency per sample:\\\",\\n        f\\\"{sample_mean['Test_count'].min()}–\\\"\\n        f\\\"{sample_mean['Test_count'].max()}, \\\"\\n        f\\\"mean = \\\"\\n        f\\\"{sample_mean['Test_count'].mean():.2f}\\\"\\n    )\\n\\n\\n# ============================================================\\n# 6. 保存最终绘图数据\\n# ============================================================\\n\\nsummary_df = pd.DataFrame(\\n    summary\\n)\\n\\n\\nEXCEL_FILE = (\\n    OUTPUT_DIR /\\n    \\\"Fig6_Observed_Predicted_Error_data.xlsx\\\"\\n)\\n\\n\\nwith pd.ExcelWriter(\\n    EXCEL_FILE,\\n    engine=\\\"openpyxl\\\"\\n) as writer:\\n\\n\\n    # --------------------------------------------------------\\n    # 总体模型指标\\n    # --------------------------------------------------------\\n\\n    summary_df.to_excel(\\n        writer,\\n        sheet_name=\\\"Metrics\\\",\\n        index=False\\n    )\\n\\n\\n    # --------------------------------------------------------\\n    # 三种气体分别保存\\n    # --------------------------------------------------------\\n\\n    for gas in [\\n        \\\"N2O\\\",\\n        \\\"CO2\\\",\\n        \\\"CH4\\\"\\n    ]:\\n\\n        results[\\n            gas\\n        ][\\\"data\\\"].to_excel(\\n\\n            writer,\\n\\n            sheet_name=(\\n                f\\\"{gas}_\\\"\\n                f\\\"{results[gas]['model']}\\\"\\n            ),\\n\\n            index=False\\n        )\\n\\n\\n# ============================================================\\n# 7. 图形文字设置\\n# ============================================================\\n\\nTITLES = {\\n\\n    \\\"N2O\\\":\\n        r\\\"N$_2$O — ET\\\",\\n\\n    \\\"CO2\\\":\\n        r\\\"CO$_2$ — GBDT\\\",\\n\\n    \\\"CH4\\\":\\n        r\\\"CH$_4$ — ET\\\"\\n}\\n\\n\\nPANEL_LABELS = {\\n\\n    \\\"N2O\\\": \\\"(a)\\\",\\n\\n    \\\"CO2\\\": \\\"(b)\\\",\\n\\n    \\\"CH4\\\": \\\"(c)\\\"\\n}\\n\\n\\nUNITS = {\\n\\n    \\\"N2O\\\":\\n        r\\\"kg N$_2$O ha$^{-1}$\\\",\\n\\n    \\\"CO2\\\":\\n        r\\\"kg CO$_2$ ha$^{-1}$\\\",\\n\\n    \\\"CH4\\\":\\n        r\\\"kg CH$_4$ ha$^{-1}$\\\"\\n}\\n\\n\\n# ============================================================\\n# 8. 创建 Figure\\n# ============================================================\\n\\nfig = plt.figure(\\n    figsize=(18.0, 5.3)\\n)\\n\\n\\n# ------------------------------------------------------------\\n# 外层：\\n#\\n# N2O | CO2 | CH4\\n# ------------------------------------------------------------\\n\\nouter_grid = fig.add_gridspec(\\n\\n    1,\\n    3,\\n\\n    left=0.055,\\n\\n    right=0.99,\\n\\n    bottom=0.17,\\n\\n    top=0.85,\\n\\n    wspace=0.32\\n)\\n\\n\\n# ============================================================\\n# 9. 分别绘制三个气体\\n# ============================================================\\n\\nfor i, gas in enumerate(\\n    [\\\"N2O\\\", \\\"CO2\\\", \\\"CH4\\\"]\\n):\\n\\n\\n    # ========================================================\\n    # 9.1 每个气体内部划分\\n    #\\n    # 左：\\n    # Observed vs Predicted\\n    #\\n    # 右：\\n    # Error distribution\\n    #\\n    # 比例约 4.2 : 1\\n    # ========================================================\\n\\n    inner_grid = (\\n        outer_grid[i]\\n        .subgridspec(\\n\\n            1,\\n            2,\\n\\n            width_ratios=[\\n                4.6,\\n                0.85\\n            ],\\n\\n            wspace=0.08\\n        )\\n    )\\n\\n\\n    # --------------------------------------------------------\\n    # 左侧主图\\n    # --------------------------------------------------------\\n\\n    ax = fig.add_subplot(\\n        inner_grid[0]\\n    )\\n\\n\\n    # --------------------------------------------------------\\n    # 右侧 Error 图\\n    # 与左侧共享 Y 轴\\n    # --------------------------------------------------------\\n\\n    ax_err = fig.add_subplot(\\n        inner_grid[1],\\n        sharey=ax\\n    )\\n\\n\\n    # ========================================================\\n    # 9.2 获取当前气体数据\\n    # ========================================================\\n\\n    result = results[\\n        gas\\n    ]\\n\\n\\n    plot_df = result[\\n        \\\"data\\\"\\n    ]\\n\\n\\n    # --------------------------------------------------------\\n    # Observed\\n    # --------------------------------------------------------\\n\\n    x = (\\n        plot_df[\\n            \\\"Observed\\\"\\n        ].to_numpy()\\n    )\\n\\n\\n    # --------------------------------------------------------\\n    # Mean Predicted\\n    # --------------------------------------------------------\\n\\n    y = (\\n        plot_df[\\n            \\\"Predicted\\\"\\n        ].to_numpy()\\n    )\\n\\n\\n    # --------------------------------------------------------\\n    # Prediction Error\\n    # --------------------------------------------------------\\n\\n    error = (\\n        plot_df[\\n            \\\"Error\\\"\\n        ].to_numpy()\\n    )\\n\\n\\n    # --------------------------------------------------------\\n    # 模型信息\\n    # --------------------------------------------------------\\n\\n    model = result[\\n        \\\"model\\\"\\n    ]\\n\\n\\n    R2 = result[\\n        \\\"R2\\\"\\n    ]\\n\\n\\n    RMSE = result[\\n        \\\"RMSE\\\"\\n    ]\\n\\n\\n    MAE = result[\\n        \\\"MAE\\\"\\n    ]\\n\\n\\n    # ========================================================\\n    # 10. 左侧 Observed vs Predicted\\n    # ========================================================\\n\\n    ax.scatter(\\n\\n        x,\\n        y,\\n\\n        s=31,\\n\\n        facecolor=POINT_COLOR,\\n\\n        edgecolor=POINT_EDGE,\\n\\n        linewidth=0.45,\\n\\n        alpha=0.72,\\n\\n        zorder=3\\n    )\\n\\n\\n    # ========================================================\\n    # 10.1 左图坐标范围\\n    # ========================================================\\n\\n    minimum = min(\\n        np.min(x),\\n        np.min(y)\\n    )\\n\\n\\n    maximum = max(\\n        np.max(x),\\n        np.max(y)\\n    )\\n\\n\\n    span = (\\n        maximum\\n        -\\n        minimum\\n    )\\n\\n\\n    if span == 0:\\n\\n        span = 1.0\\n\\n\\n    lower = max(\\n        0,\\n        minimum\\n        -\\n        0.04 * span\\n    )\\n\\n\\n    upper = (\\n        maximum\\n        +\\n        0.06 * span\\n    )\\n\\n\\n    # ========================================================\\n    # 10.2 1:1 reference line\\n    # ========================================================\\n\\n    ax.plot(\\n\\n        [lower, upper],\\n\\n        [lower, upper],\\n\\n        linestyle=\\\"--\\\",\\n\\n        linewidth=1.10,\\n\\n        color=REFERENCE_COLOR,\\n\\n        label=\\\"1:1 line\\\",\\n\\n        zorder=2\\n    )\\n\\n\\n    # --------------------------------------------------------\\n    # X、Y轴完全相同范围\\n    # --------------------------------------------------------\\n\\n    ax.set_xlim(\\n        lower,\\n        upper\\n    )\\n\\n\\n    ax.set_ylim(\\n        lower,\\n        upper\\n    )\\n\\n\\n    # ========================================================\\n    # 10.3 标题\\n    # ========================================================\\n\\n    ax.set_title(\\n\\n        TITLES[gas],\\n\\n        fontsize=16.5,\\n\\n        fontweight=\\\"normal\\\",\\n\\n        pad=15\\n    )\\n\\n\\n    # ========================================================\\n    # 10.4 X轴\\n    # ========================================================\\n\\n    ax.set_xlabel(\\n\\n        \\\"Observed emission\\\\n\\\"\\n        f\\\"({UNITS[gas]})\\\",\\n\\n        fontsize=12.5\\n    )\\n\\n\\n    # ========================================================\\n    # 10.5 Y轴\\n    # ========================================================\\n\\n    ax.set_ylabel(\\n\\n        \\\"Predicted emission\\\\n\\\"\\n        f\\\"({UNITS[gas]})\\\",\\n\\n        fontsize=12.5\\n    )\\n\\n\\n    # ========================================================\\n    # 10.6 模型评价指标\\n    #\\n    # 注意：\\n    # 已按照要求删除 n\\n    # ========================================================\\n\\n    metric_text = (\\n\\n        f\\\"Model: {model}\\\\n\\\"\\n\\n        rf\\\"$R^2$ = {R2:.3f}\\\"\\n        \\\"\\\\n\\\"\\n\\n        f\\\"RMSE = {RMSE:,.2f}\\\\n\\\"\\n\\n        f\\\"MAE = {MAE:,.2f}\\\"\\n    )\\n\\n\\n    ax.text(\\n\\n        0.055,\\n        0.955,\\n\\n        metric_text,\\n\\n        transform=ax.transAxes,\\n\\n        horizontalalignment=\\\"left\\\",\\n\\n        verticalalignment=\\\"top\\\",\\n\\n        fontsize=11.5,\\n\\n        linespacing=1.30\\n    )\\n\\n\\n    # ========================================================\\n    # 10.7 Panel label\\n    # ========================================================\\n\\n    ax.text(\\n\\n        -0.17,\\n        1.09,\\n\\n        PANEL_LABELS[gas],\\n\\n        transform=ax.transAxes,\\n\\n        fontsize=18,\\n\\n        fontweight=\\\"bold\\\",\\n\\n        color=\\\"#C00000\\\",\\n\\n        horizontalalignment=\\\"left\\\",\\n\\n        verticalalignment=\\\"top\\\"\\n    )\\n\\n\\n    # ========================================================\\n    # 10.8 Legend\\n    # ========================================================\\n\\n    ax.legend(\\n\\n        loc=\\\"lower right\\\",\\n\\n        frameon=False,\\n\\n        fontsize=10.5,\\n\\n        handlelength=2.3\\n    )\\n\\n\\n    # ========================================================\\n    # 10.9 Tick\\n    # ========================================================\\n\\n    ax.tick_params(\\n\\n        axis=\\\"both\\\",\\n\\n        which=\\\"major\\\",\\n\\n        labelsize=10.5,\\n\\n        direction=\\\"out\\\",\\n\\n        length=4,\\n\\n        width=0.9\\n    )\\n\\n\\n    # ========================================================\\n    # 10.10 Border\\n    # ========================================================\\n\\n    for spine in ax.spines.values():\\n\\n        spine.set_linewidth(\\n            1.0\\n        )\\n\\n\\n    # ========================================================\\n    # 11. 右侧 Prediction Error Distribution\\n    # ========================================================\\n\\n    # --------------------------------------------------------\\n    # Error:\\n    #\\n    # Predicted - Observed\\n    #\\n    # Y:\\n    #\\n    # Predicted\\n    #\\n    # 因此右图中的每一个点与左图中的点一一对应\\n    # --------------------------------------------------------\\n\\n\\n    # ========================================================\\n    # 11.1 添加极小水平 jitter\\n    # ========================================================\\n\\n    # jitter 仅用于防止散点完全重叠\\n    # 不改变任何统计结果\\n\\n    rng = np.random.default_rng(\\n        42 + i\\n    )\\n\\n\\n    error_range = (\\n        np.max(error)\\n        -\\n        np.min(error)\\n    )\\n\\n\\n    if error_range == 0:\\n\\n        error_range = 1.0\\n\\n\\n    jitter = rng.normal(\\n\\n        loc=0,\\n\\n        scale=(\\n            0.012\\n            *\\n            error_range\\n        ),\\n\\n        size=len(error)\\n    )\\n\\n\\n    error_plot = (\\n        error\\n        +\\n        jitter\\n    )\\n\\n\\n    # ========================================================\\n    # 11.2 Error散点\\n    #\\n    # 与左侧主图完全统一颜色\\n    # ========================================================\\n\\n    ax_err.scatter(\\n\\n        error_plot,\\n        y,\\n\\n        s=31,\\n\\n        facecolor=POINT_COLOR,\\n\\n        edgecolor=POINT_EDGE,\\n\\n        linewidth=0.45,\\n\\n        alpha=0.72,\\n\\n        zorder=3\\n    )\\n\\n\\n    # ========================================================\\n    # 11.3 Error = 0 reference line\\n    # ========================================================\\n\\n    ax_err.axvline(\\n\\n        x=0,\\n\\n        linestyle=\\\"--\\\",\\n\\n        linewidth=1.05,\\n\\n        color=REFERENCE_COLOR,\\n\\n        zorder=2\\n    )\\n\\n\\n    # ========================================================\\n    # 11.4 Error X轴设置\\n    # ========================================================\\n\\n    max_abs_error = np.max(\\n        np.abs(error)\\n    )\\n\\n\\n    error_limit = (\\n        max_abs_error\\n        *\\n        1.12\\n    )\\n\\n\\n    if error_limit == 0:\\n\\n        error_limit = 1.0\\n\\n\\n    # --------------------------------------------------------\\n    # 以0为中心左右对称\\n    # --------------------------------------------------------\\n\\n    ax_err.set_xlim(\\n\\n        -error_limit,\\n\\n        error_limit\\n    )\\n\\n\\n    # ========================================================\\n    # 11.5 Error X轴刻度\\n    #\\n    # 左端、0、右端\\n    # ========================================================\\n\\n    tick_value = (\\n        error_limit\\n        *\\n        0.80\\n    )\\n\\n\\n    ax_err.set_xticks(\\n\\n        [\\n            -tick_value,\\n            0,\\n            tick_value\\n        ]\\n    )\\n\\n\\n    # --------------------------------------------------------\\n    # 自动设置小数位\\n    # --------------------------------------------------------\\n\\n    if tick_value < 1:\\n\\n        error_labels = [\\n\\n            f\\\"{-tick_value:.2f}\\\",\\n\\n            \\\"0\\\",\\n\\n            f\\\"{tick_value:.2f}\\\"\\n        ]\\n\\n\\n    elif tick_value < 10:\\n\\n        error_labels = [\\n\\n            f\\\"{-tick_value:.1f}\\\",\\n\\n            \\\"0\\\",\\n\\n            f\\\"{tick_value:.1f}\\\"\\n        ]\\n\\n\\n    else:\\n\\n        error_labels = [\\n\\n            f\\\"{-tick_value:.0f}\\\",\\n\\n            \\\"0\\\",\\n\\n            f\\\"{tick_value:.0f}\\\"\\n        ]\\n\\n\\n    ax_err.set_xticklabels(\\n        error_labels\\n    )\\n\\n\\n    # ========================================================\\n    # 11.6 Error轴标题\\n    # ========================================================\\n\\n    ax_err.set_xlabel(\\n\\n        \\\"Error\\\",\\n\\n        fontsize=11.5,\\n\\n        labelpad=7\\n    )\\n\\n\\n    # ========================================================\\n    # 11.7 隐藏右图Y轴数字\\n    # ========================================================\\n\\n    ax_err.tick_params(\\n\\n        axis=\\\"y\\\",\\n\\n        left=False,\\n\\n        right=False,\\n\\n        labelleft=False,\\n\\n        labelright=False\\n    )\\n\\n\\n    # ========================================================\\n    # 11.8 Error X轴Tick\\n    # ========================================================\\n\\n    ax_err.tick_params(\\n\\n        axis=\\\"x\\\",\\n\\n        labelsize=9.5,\\n\\n        direction=\\\"out\\\",\\n\\n        length=4,\\n\\n        width=0.9\\n    )\\n\\n\\n    # ========================================================\\n    # 11.9 Error图边框\\n    #\\n    # 参考你提供的论文图：\\n    # 仅保留底部X轴\\n    # ========================================================\\n\\n    ax_err.spines[\\n        \\\"top\\\"\\n    ].set_visible(\\n        False\\n    )\\n\\n\\n    ax_err.spines[\\n        \\\"right\\\"\\n    ].set_visible(\\n        False\\n    )\\n\\n\\n    ax_err.spines[\\n        \\\"left\\\"\\n    ].set_visible(\\n        False\\n    )\\n\\n\\n    ax_err.spines[\\n        \\\"bottom\\\"\\n    ].set_linewidth(\\n        1.0\\n    )\\n\\n\\n# ============================================================\\n# 12. 保存图片\\n# ============================================================\\n\\nPNG_FILE = (\\n    OUTPUT_DIR /\\n    \\\"Fig6_Observed_vs_predicted_with_error_final_600dpi_SD.png\\\"\\n)\\n\\n\\n\\n\\n\\n# ------------------------------------------------------------\\n# PNG\\n# ------------------------------------------------------------\\n\\nfig.savefig(\\n\\n    PNG_FILE,\\n\\n    dpi=SAVE_DPI,\\n\\n    bbox_inches=\\\"tight\\\",\\n\\n    facecolor=\\\"white\\\"\\n)\\n\\n\\n\\nplt.show()\\n\\n\\n# ============================================================\\n# 13. 输出最终结果\\n# ============================================================\\n\\nprint(\\n    \\\"\\\\n\\\" +\\n    \\\"=\\\" * 70\\n)\\n\\n\\nprint(\\n    \\\"Fig.6 completed\\\"\\n)\\n\\n\\nprint(\\n    \\\"=\\\" * 70\\n)\\n\\n\\nprint(\\n    \\\"\\\\nPerformance and error statistics:\\\"\\n)\\n\\n\\nprint(\\n\\n    summary_df[\\n        [\\n            \\\"Gas\\\",\\n            \\\"Model\\\",\\n            \\\"n\\\",\\n            \\\"R2\\\",\\n            \\\"RMSE\\\",\\n            \\\"MAE\\\",\\n            \\\"Mean_Error\\\",\\n            \\\"Error_SD\\\",\\n            \\\"Error_Variance\\\",\\n            \\\"Mean_test_count\\\"\\n        ]\\n    ].to_string(\\n        index=False\\n    )\\n)\\n\\n\\nprint(\\n    \\\"\\\\nPNG:\\\"\\n)\\n\\n\\nprint(\\n    \\\"\\\\nPlotting data:\\\"\\n)\\n\\nprint(\\n    EXCEL_FILE\\n)\"}}")

def main():
    parser = argparse.ArgumentParser(description=__doc__,
        formatter_class=argparse.RawDescriptionHelpFormatter)
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument("--list", action="store_true")
    group.add_argument("--check", action="store_true")
    group.add_argument("--extract", type=Path)
    group.add_argument("--run", choices=sorted(MODULES))
    parser.add_argument("--acknowledge-unverified", action="store_true",
                        help="Required to execute archived unverified sources.")
    args = parser.parse_args()
    if args.list:
        for key, item in MODULES.items():
            print(f"{key}: {item['filename']}")
    elif args.check:
        failures = []
        for key, item in MODULES.items():
            try:
                compile(item["source"], item["filename"], "exec")
                print(f"PASS {key}")
            except SyntaxError as exc:
                failures.append(key)
                print(f"FAIL {key}: {exc}")
        if failures:
            raise SystemExit(1)
    elif args.extract:
        args.extract.mkdir(parents=True, exist_ok=True)
        for key, item in MODULES.items():
            target = args.extract / (key + ".py")
            if target.exists():
                raise SystemExit(f"Refusing to overwrite: {target}")
        for key, item in MODULES.items():
            (args.extract / (key + ".py")).write_text(item["source"], encoding="utf-8")
        print(f"Extracted {len(MODULES)} modules to {args.extract.resolve()}")
    else:
        if not args.acknowledge_unverified:
            parser.error("Sources are unverified; inspect --extract output before using --acknowledge-unverified.")
        item = MODULES[args.run]
        namespace = {"__name__": "__main__", "__file__": str(Path(__file__).resolve())}
        exec(compile(item["source"], item["filename"], "exec"), namespace)

if __name__ == "__main__":
    main()

